async function loadPdfJs() {
  if (pdfjsLib) return pdfjsLib;
  const originalWarn = console.warn;
  console.warn = (...args) => {
    const text = args.join(" ");
    if (text.includes("Cannot polyfill `DOMMatrix`") || text.includes("Cannot polyfill `Path2D`")) return;
    originalWarn(...args);
  };
  try {
    pdfjsLib = await import("pdfjs-dist/legacy/build/pdf.mjs");
    if (pdfjsLib.GlobalWorkerOptions) {
      pdfjsLib.GlobalWorkerOptions.workerSrc = null;
    }
    return pdfjsLib;
  } finally {
    console.warn = originalWarn;
  }
}

function isDesktopFeatureRunning() {
  return Boolean(desktopFeatureProc && desktopFeatureProc.exitCode === null && !desktopFeatureProc.killed);
}

function desktopFeatureStatus(extra = {}) {
  return {
    running: isDesktopFeatureRunning(),
    pid: isDesktopFeatureRunning() ? desktopFeatureProc.pid : null,
    startedAt: desktopFeatureStartedAt,
    mode: desktopFeatureProc ? desktopFeatureProc.__launchMode : null,
    ...extra,
  };
}

function normalizeSharedConfig(raw) {
  const config = { ...DEFAULT_SHARED_CONFIG, ...(raw || {}) };
  config.serverBaseUrl = String(config.serverBaseUrl || DEFAULT_SHARED_CONFIG.serverBaseUrl).replace(/\/+$/, "");
  config.betaToken = String(config.betaToken || DEFAULT_SHARED_CONFIG.betaToken);
  if (!Array.isArray(config.testUsers) || config.testUsers.length === 0) {
    config.testUsers = DEFAULT_SHARED_CONFIG.testUsers;
  }
  config.targetLanguage = String(config.targetLanguage || DEFAULT_SHARED_CONFIG.targetLanguage).trim().toLowerCase();
  if (!["en", "zh", "ja", "ko", "fr", "de", "es"].includes(config.targetLanguage)) {
    config.targetLanguage = DEFAULT_SHARED_CONFIG.targetLanguage;
  }
  const rawProvider = raw && typeof raw.provider === "object" ? raw.provider : {};
  const normalizeProviderEntry = (entry, fallbackId) => ({
    id: String(entry && entry.id || fallbackId || "provider-default"),
    name: String(entry && entry.name || (OPENAI_COMPATIBLE_PROVIDER_PRESETS[String(entry && entry.preset || "")] || {}).label || "默认配置"),
    type: "openai_compatible",
    preset: String(entry && entry.preset || inferProviderPreset(entry && entry.baseUrl) || "custom").trim().toLowerCase(),
    baseUrl: normalizeOpenAiCompatibleBaseUrl(entry && entry.baseUrl),
    apiKey: String(entry && entry.apiKey || "").trim(),
    model: String(entry && entry.model || "").trim(),
  });
  const rawProfiles = raw && Array.isArray(raw.providerProfiles) ? raw.providerProfiles : [];
  config.providerProfiles = (rawProfiles.length ? rawProfiles : [rawProvider]).map((entry, index) => normalizeProviderEntry(entry, index ? `provider-${index + 1}` : "provider-default"));
  const requestedActiveId = String(raw && raw.activeProviderId || rawProvider.id || config.providerProfiles[0].id);
  const active = config.providerProfiles.find((entry) => entry.id === requestedActiveId) || config.providerProfiles[0];
  config.activeProviderId = active.id;
  config.provider = { ...active };
  return config;
}

function normalizeOpenAiCompatibleBaseUrl(value) {
  let baseUrl = String(value || "").trim().replace(/\/+$/, "");
  baseUrl = baseUrl.replace(/\/chat\/completions$/i, "");
  return baseUrl;
}

function inferProviderPreset(baseUrl) {
  const normalized = normalizeOpenAiCompatibleBaseUrl(baseUrl).toLowerCase();
  const match = Object.values(OPENAI_COMPATIBLE_PROVIDER_PRESETS).find((preset) => preset.baseUrl && normalized === preset.baseUrl.toLowerCase());
  return match ? match.id : "custom";
}

function validateProviderConfig(provider) {
  const preset = String(provider && provider.preset || "custom").trim().toLowerCase();
  const presetDefinition = OPENAI_COMPATIBLE_PROVIDER_PRESETS[preset] || OPENAI_COMPATIBLE_PROVIDER_PRESETS.custom;
  const normalized = {
    type: "openai_compatible",
    preset: presetDefinition.id,
    baseUrl: normalizeOpenAiCompatibleBaseUrl(provider && provider.baseUrl),
    apiKey: String(provider && provider.apiKey || "").trim(),
    model: String(provider && provider.model || "").trim(),
  };
  if (!normalized.baseUrl) throw new Error("请填写 Base URL");
  let parsedUrl;
  try {
    parsedUrl = new URL(normalized.baseUrl);
  } catch (_err) {
    throw new Error("Base URL 格式无效");
  }
  if (!["http:", "https:"].includes(parsedUrl.protocol)) {
    throw new Error("Base URL 必须使用 http 或 https");
  }
  if (presetDefinition.requiresApiKey && !normalized.apiKey) throw new Error("请填写 API Key");
  if (!normalized.model) throw new Error("请填写 Model");
  return normalized;
}

function providerPublicEntry(provider, activeProviderId) {
  provider = provider || {};
  const key = String(provider.apiKey || "");
  const presetDefinition = OPENAI_COMPATIBLE_PROVIDER_PRESETS[String(provider.preset || "custom")] || OPENAI_COMPATIBLE_PROVIDER_PRESETS.custom;
  return {
    id: String(provider.id || ""),
    name: String(provider.name || "默认配置"),
    type: "openai_compatible",
    preset: String(provider.preset || "custom"),
    baseUrl: String(provider.baseUrl || ""),
    model: String(provider.model || ""),
    apiKeyConfigured: Boolean(key),
    apiKeyMasked: key ? `${key.slice(0, Math.min(3, key.length))}${"•".repeat(Math.min(8, Math.max(4, key.length - 3)))}` : "",
    ready: Boolean(provider.baseUrl && provider.model && (key || !presetDefinition.requiresApiKey)),
    active: Boolean(provider.id && provider.id === activeProviderId),
  };
}

function getProviderPublicConfig(config = readSharedConfig()) {
  return providerPublicEntry(config.provider || {}, config.activeProviderId);
}

function getProviderManagerPublicConfig(config = readSharedConfig()) {
  return {
    activeProviderId: String(config.activeProviderId || ""),
    active: getProviderPublicConfig(config),
    profiles: (config.providerProfiles || []).map((entry) => providerPublicEntry(entry, config.activeProviderId)),
  };
}

function getProviderPresetList() {
  return Object.values(OPENAI_COMPATIBLE_PROVIDER_PRESETS).map((preset) => ({ ...preset }));
}

function serializeProviderError(error, seen = new Set()) {
  if (error == null) return null;
  if (typeof error !== "object") return { name: typeof error, message: String(error) };
  if (seen.has(error)) return { name: "CircularError", message: "[Circular cause]" };
  seen.add(error);
  const serialized = {
    name: String(error.name || "Error"),
    message: String(error.message || error),
    stack: String(error.stack || ""),
  };
  for (const key of ["code", "errno", "syscall", "status", "statusCode", "responseBody", "url", "method"]) {
    if (error[key] !== undefined && error[key] !== null) serialized[key] = String(error[key]);
  }
  if (error.cause !== undefined) serialized.cause = serializeProviderError(error.cause, seen);
  return serialized;
}

function createProviderHttpError(response, responseBody, responseData) {
  const detail = responseData && (responseData.error && (responseData.error.message || responseData.error) || responseData.message || responseData.detail);
  const error = new Error(`${`Provider HTTP ${response.status} ${response.statusText || ""}`.trim()}${detail ? `：${String(detail)}` : ""}`);
  error.status = response.status;
  error.statusCode = response.status;
  error.responseBody = responseBody;
  error.url = response.url;
  error.method = "POST";
  return error;
}

function saveProviderConfig(input) {
  const current = readSharedConfig();
  const incoming = input && typeof input === "object" ? input : {};
  const incomingId = String(incoming.id || "").trim();
  const existing = (current.providerProfiles || []).find((entry) => entry.id === incomingId);
  const apiKey = String(incoming.apiKey || "").trim() || String(existing && existing.apiKey || "").trim();
  const validated = validateProviderConfig({ ...incoming, apiKey });
  const provider = {
    ...validated,
    id: incomingId || `provider-${crypto.randomUUID()}`,
    name: String(incoming.name || "").trim() || (OPENAI_COMPATIBLE_PROVIDER_PRESETS[validated.preset] || {}).label || "自定义配置",
  };
  const profiles = (current.providerProfiles || []).filter((entry) => entry.id !== provider.id).concat(provider);
  const saved = writeSharedConfig({ ...current, providerProfiles: profiles, activeProviderId: provider.id, provider });
  return getProviderManagerPublicConfig(saved);
}

function activateProviderConfig(providerId) {
  const current = readSharedConfig();
  const provider = (current.providerProfiles || []).find((entry) => entry.id === String(providerId || ""));
  if (!provider) throw new Error("配置不存在或已被移除");
  const saved = writeSharedConfig({ ...current, activeProviderId: provider.id, provider });
  return getProviderManagerPublicConfig(saved);
}

function extractProviderContentValue(value) {
  if (typeof value === "string") return value.trim();
  if (Array.isArray(value)) {
    return value.map(extractProviderContentValue).filter(Boolean).join("").trim();
  }
  if (!value || typeof value !== "object") return "";
  for (const key of ["text", "value", "content", "output_text"]) {
    const extracted = extractProviderContentValue(value[key]);
    if (extracted) return extracted;
  }
  return "";
}

function extractOpenAiCompatibleText(data) {
  const message = data && data.choices && data.choices[0] && data.choices[0].message;
  const candidates = [
    message && message.content,
    data && data.choices && data.choices[0] && data.choices[0].text,
    data && data.output_text,
    data && data.output,
    data && data.response,
    data && data.content,
  ];
  for (const candidate of candidates) {
    const extracted = extractProviderContentValue(candidate);
    if (extracted) return extracted;
  }
  return "";
}

async function callOpenAiCompatibleProvider(providerInput, request, timeoutMs = 60000) {
  const provider = validateProviderConfig(providerInput);
  const capabilityKey = providerRuntimeCapabilityKey(provider);
  const learnedMaxTokens = Number(providerExpandedCompletionBudget.get(capabilityKey) || 0);
  const effectiveMaxTokens = request.acceptAnyResponseBody
    ? Number(request.maxTokens || 32)
    : Math.max(Number(request.maxTokens || 32), learnedMaxTokens);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), Math.max(1000, Number(timeoutMs) || 60000));
  try {
    const response = await fetch(`${provider.baseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${provider.apiKey}`,
      },
      body: JSON.stringify({
        model: provider.model,
        messages: request.messages,
        temperature: request.temperature == null ? 0 : request.temperature,
        max_tokens: effectiveMaxTokens,
        stream: false,
        ...(provider.preset === "deepseek" ? { thinking: { type: "disabled" } } : {}),
      }),
      signal: controller.signal,
    });
    const responseText = await response.text();
    if (!responseText) {
      const error = createProviderHttpError(response, responseText, null);
      error.message = `Provider HTTP ${response.status} 成功，但响应体为空`;
      throw error;
    }
    let data = null;
    try {
      data = JSON.parse(responseText);
    } catch (parseError) {
      if (response.ok && request.acceptAnyResponseBody) {
        return { text: "", model: provider.model, httpStatus: response.status, responseBody: responseText, responseData: null };
      }
      const error = new Error(`Provider 返回的不是 JSON（HTTP ${response.status}）`, { cause: parseError });
      error.status = response.status;
      error.statusCode = response.status;
      error.responseBody = responseText;
      error.url = response.url;
      error.method = "POST";
      throw error;
    }
    if (!response.ok) {
      throw createProviderHttpError(response, responseText, data);
    }
    const text = extractOpenAiCompatibleText(data);
    if (!text && !request.acceptAnyResponseBody) {
      const firstChoice = data && Array.isArray(data.choices) ? data.choices[0] : null;
      const message = firstChoice && firstChoice.message;
      const hasReasoning = Boolean(message && extractProviderContentValue(message.reasoning_content));
      const exhausted = String(firstChoice && firstChoice.finish_reason || "").toLowerCase() === "length";
      if (!request.emptyContentRetry && (hasReasoning || exhausted)) {
        const expandedMaxTokens = Math.min(8192, Math.max(2048, effectiveMaxTokens * 4));
        providerExpandedCompletionBudget.set(capabilityKey, expandedMaxTokens);
        debugPdfWarn("[LINGOFLOW][PROVIDER EMPTY CONTENT RETRY]", {
          model: provider.model,
          finishReason: firstChoice && firstChoice.finish_reason,
          hasReasoning,
          previousMaxTokens: effectiveMaxTokens,
          expandedMaxTokens,
        });
        return callOpenAiCompatibleProvider(provider, {
          ...request,
          maxTokens: expandedMaxTokens,
          emptyContentRetry: true,
        }, Math.max(timeoutMs, 30000));
      }
      const error = new Error("Provider 返回成功，但没有可用文本");
      error.status = response.status;
      error.statusCode = response.status;
      error.responseBody = responseText;
      error.url = response.url;
      error.method = "POST";
      throw error;
    }
    return { text, model: provider.model, httpStatus: response.status, responseBody: responseText, responseData: data };
  } catch (err) {
    if (err && err.name === "AbortError") throw new Error("Provider 请求超时", { cause: err });
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

async function testProviderConnection(input) {
  const current = readSharedConfig();
  const incoming = input && typeof input === "object" ? input : {};
  const savedProfile = (current.providerProfiles || []).find((entry) => entry.id === String(incoming.id || ""));
  const provider = validateProviderConfig({
    ...(savedProfile || current.provider || {}),
    ...incoming,
    apiKey: String(incoming.apiKey || "").trim() || String(savedProfile && savedProfile.apiKey || current.provider && current.provider.apiKey || "").trim(),
  });
  const startedAt = Date.now();
  const result = await callOpenAiCompatibleProvider(provider, {
    messages: [
      { role: "system", content: "Reply with OK only." },
      { role: "user", content: "Connection test" },
    ],
    temperature: 0,
    maxTokens: 8,
    acceptAnyResponseBody: true,
  }, 15000);
  debugPdfLog("[LINGOFLOW][PROVIDER TEST RESPONSE]", result.responseBody);
  const hasChoices = Boolean(result.responseData && Array.isArray(result.responseData.choices) && result.responseData.choices.length > 0);
  if (Number(result.httpStatus) !== 200 || !hasChoices) {
    const error = new Error(`Provider 连接响应不符合预期：HTTP ${result.httpStatus || "unknown"}，choices ${hasChoices ? "non-empty" : "empty"}`);
    error.status = result.httpStatus;
    error.statusCode = result.httpStatus;
    error.responseBody = result.responseBody;
    throw error;
  }
  const presetDefinition = OPENAI_COMPATIBLE_PROVIDER_PRESETS[provider.preset] || OPENAI_COMPATIBLE_PROVIDER_PRESETS.custom;
  const latencyMs = Date.now() - startedAt;
  return {
    ok: true,
    message: "Provider 已连接",
    provider: presetDefinition.label,
    model: result.model,
    latencyMs,
    diagnostic: {
      httpStatus: result.httpStatus,
      parsedText: result.text || "",
      responseBody: result.responseBody,
      responseData: result.responseData,
    },
  };
}

function getTargetLanguageName(value) {
  const normalized = String(value || "zh").toLowerCase();
  return ({ zh: "Simplified Chinese", "zh-cn": "Simplified Chinese", en: "English", ja: "Japanese", ko: "Korean", fr: "French", de: "German", es: "Spanish" })[normalized] || value || "Simplified Chinese";
}

async function translateWithConfiguredProvider(input) {
  const config = readSharedConfig();
  const provider = validateProviderConfig(config.provider);
  const text = String(input && input.text || "").trim();
  if (!text) throw new Error("翻译文本为空");
  const targetName = getTargetLanguageName(input && (input.targetLanguage || input.target_lang));
  const context = String(input && input.context || "").trim();
  const system = [
    `You are a translation engine. Translate the user's text into ${targetName}.`,
    "Return only the translation. Do not explain. Do not include labels, markdown, or quotation marks.",
    "Preserve names, technical terms, placeholders, equations, and citation tokens exactly.",
    context ? `Document instructions: ${context}` : "",
  ].filter(Boolean).join(" ");
  const result = await callOpenAiCompatibleProvider(provider, {
    messages: [{ role: "system", content: system }, { role: "user", content: text }],
    temperature: 0.1,
    maxTokens: Math.min(4096, Math.max(256, Math.ceil(text.length * 2.2))),
  });
  return { status: "ok", translation: result.text, provider: "openai_compatible", model: result.model };
}

function readSharedConfig() {
  try {
    if (!fs.existsSync(SHARED_CONFIG_PATH)) {
      return writeSharedConfig(DEFAULT_SHARED_CONFIG);
    }
    const parsed = JSON.parse(fs.readFileSync(SHARED_CONFIG_PATH, "utf8"));
    const config = normalizeSharedConfig(parsed);
    if (JSON.stringify(config) !== JSON.stringify(parsed)) {
      writeSharedConfig(config);
    }
    return config;
  } catch (err) {
    console.error("[config] read failed:", err.message || err);
    return { ...DEFAULT_SHARED_CONFIG };
  }
}


function writeSharedConfig(nextConfig) {
  const config = normalizeSharedConfig(nextConfig);
  fs.mkdirSync(path.dirname(SHARED_CONFIG_PATH), { recursive: true });
  fs.writeFileSync(SHARED_CONFIG_PATH, JSON.stringify(config, null, 2), "utf8");
  return config;
}

function decodePdfTextString(value) {
  if (!value) return "";
  const bytes = [];
  for (let i = 0; i < value.length; i += 1) {
    const ch = value[i];
    if (ch === "\\") {
      const next = value[i + 1];
      if (next === "n") {
        bytes.push(10);
        i += 1;
      } else if (next === "r") {
        bytes.push(10);
        i += 1;
      } else if (next === "t") {
        bytes.push(9);
        i += 1;
      } else if (next === "b" || next === "f") {
        i += 1;
      } else if (next === "(" || next === ")" || next === "\\") {
        bytes.push(next.charCodeAt(0));
        i += 1;
      } else if (/[0-7]/.test(next || "")) {
        const octal = value.slice(i + 1, i + 4).match(/^[0-7]{1,3}/);
        if (octal) {
          bytes.push(parseInt(octal[0], 8));
          i += octal[0].length;
        }
      } else if (next) {
        bytes.push(next.charCodeAt(0));
        i += 1;
      }
    } else {
      bytes.push(ch.charCodeAt(0) & 0xff);
    }
  }

  const buffer = Buffer.from(bytes);
  if (buffer.length >= 2 && buffer[0] === 0xfe && buffer[1] === 0xff) {
    let out = "";
    for (let i = 2; i + 1 < buffer.length; i += 2) {
      const code = buffer.readUInt16BE(i);
      if (code) out += String.fromCharCode(code);
    }
    return out;
  }
  return buffer.toString("latin1");
}

function decodePdfHexString(value) {
  const clean = String(value || "").replace(/\s+/g, "");
  if (!clean) return "";
  const even = clean.length % 2 === 0 ? clean : `${clean}0`;
  const buffer = Buffer.from(even, "hex");
  if (buffer.length >= 2 && buffer[0] === 0xfe && buffer[1] === 0xff) {
    let out = "";
    for (let i = 2; i + 1 < buffer.length; i += 2) {
      const code = buffer.readUInt16BE(i);
      if (code) out += String.fromCharCode(code);
    }
    return out;
  }
  return buffer.toString("latin1");
}

function extractStringsFromPdfStream(streamText) {
  const parts = [];
  const tokenPattern = /\((?:\\.|[^\\()])*\)\s*Tj|<([0-9A-Fa-f\s]+)>\s*Tj|\[(.*?)\]\s*TJ/gs;
  let match;
  while ((match = tokenPattern.exec(streamText))) {
    const token = match[0];
    if (token.endsWith("Tj")) {
      if (token[0] === "(") {
        parts.push(decodePdfTextString(token.slice(1, token.lastIndexOf(")"))));
      } else {
        parts.push(decodePdfHexString(match[1]));
      }
    } else if (token.endsWith("TJ")) {
      const arrayBody = match[2] || "";
      const arrayParts = [];
      const arrayPattern = /\((?:\\.|[^\\()])*\)|<([0-9A-Fa-f\s]+)>/g;
      let arrayMatch;
      while ((arrayMatch = arrayPattern.exec(arrayBody))) {
        const raw = arrayMatch[0];
        arrayParts.push(raw[0] === "(" ? decodePdfTextString(raw.slice(1, -1)) : decodePdfHexString(arrayMatch[1]));
      }
      parts.push(arrayParts.join(""));
    }
  }
  return parts.join(" ");
}

function normalizeExtractedPdfText(text) {
  return String(text || "")
    .normalize("NFKC")
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "")
    .replace(/[\ue000-\uf8ff]/g, "")
    .replace(/\u00ad/g, "")
    .replace(/\ufb00/g, "ff")
    .replace(/\ufb01/g, "fi")
    .replace(/\ufb02/g, "fl")
    .replace(/\ufb03/g, "ffi")
    .replace(/\ufb04/g, "ffl")
    .replace(/\r/g, "\n")
    .replace(/([A-Za-z])-\n([a-z])/g, "$1$2")
    .replace(/([A-Za-z,;:])\n([a-z(])/g, "$1 $2")
    .replace(/([\p{L}\p{N}])[ \t]+(\p{M}+)[ \t]*([\p{L}\p{N}])/gu, "$1$3$2")
    .replace(/(\p{M})\1+/gu, "$1")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/\n[ \t]+/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .normalize("NFC")
    .trim();
}

function textGarbageScore(text) {
  const value = String(text || "");
  if (!value) return Number.POSITIVE_INFINITY;
  const bad = (value.match(/[\u0000-\u001f\u007f\ufffd\ue000-\uf8ff]/g) || []).length;
  const normal = (value.match(/[A-Za-z0-9\u4e00-\u9fff]/g) || []).length;
  return bad * 8 + Math.max(0, value.length - normal) / Math.max(1, value.length);
}

function inflatePdfStream(raw) {
  try {
    return zlib.inflateSync(raw);
  } catch (_err) {
    try {
      return zlib.inflateRawSync(raw);
    } catch (_rawErr) {
      return raw;
    }
  }
}

function extractPdfTextFromBufferFallback(buffer) {
  const binary = buffer.toString("latin1");
  const streamPattern = /<<(.*?)>>\s*stream\r?\n?([\s\S]*?)\r?\n?endstream/g;
  const pages = (binary.match(/\/Type\s*\/Page\b/g) || []).length;
  const chunks = [];
  let match;

  while ((match = streamPattern.exec(binary))) {
    const dict = match[1] || "";
    const raw = Buffer.from(match[2] || "", "latin1");
    const decoded = /\/FlateDecode\b/.test(dict) ? inflatePdfStream(raw) : raw;
    const streamText = decoded.toString("latin1");
    const text = extractStringsFromPdfStream(streamText);
    if (text.trim()) chunks.push(text);
  }

  const text = normalizeExtractedPdfText(chunks.join("\n\n"));
  return {
    text,
    pages,
    charCount: text.length,
    paragraphCount: text ? text.split(/\n\s*\n/).filter(Boolean).length : 0,
  };
}

function textItemsToLines(items) {
  const rows = [];
  const yTolerance = 3;
  items.forEach((item) => {
    const text = normalizeExtractedPdfText(item.str || "");
    if (!text) return;
    const transform = item.transform || [];
    const x = Number(transform[4] || 0);
    const y = Number(transform[5] || 0);
    const width = Number(item.width || 0);
    let row = rows.find((candidate) => Math.abs(candidate.y - y) <= yTolerance);
    if (!row) {
      row = { y, parts: [] };
      rows.push(row);
    }
    row.parts.push({ x, width, text });
  });

  return rows
    .sort((a, b) => b.y - a.y)
    .map((row) => {
      const parts = row.parts.sort((a, b) => a.x - b.x);
      let line = "";
      let lastEnd = null;
      parts.forEach((part) => {
        if (!line) {
          line = part.text;
        } else {
          const avgCharWidth = part.text.length ? Math.max(1.5, part.width / part.text.length) : 4;
          const gap = lastEnd === null ? 0 : part.x - lastEnd;
          const needsSpace = gap > avgCharWidth * 0.45 && !/\s$/.test(line) && !/^[,.;:!?)]/.test(part.text);
          line += needsSpace ? ` ${part.text}` : part.text;
        }
        lastEnd = part.x + Math.max(part.width, 0);
      });
      return normalizeMergedFormulaLineText(line);
    })
    .filter(Boolean);
}

function textItemsToSequentialLines(items) {
  const lines = [];
  let line = "";
  items.forEach((item) => {
    const text = normalizeExtractedPdfText(item.str || "");
    if (!text) return;
    if (!line) {
      line = text;
    } else if (/\s$/.test(line) || /^[,.;:!?)]/.test(text)) {
      line += text;
    } else {
      line += ` ${text}`;
    }
    if (item.hasEOL) {
      lines.push(line);
      line = "";
    }
  });
  if (line) lines.push(line);
  return lines.map((entry) => normalizeMergedFormulaLineText(entry)).filter(Boolean);
}

function makeBBox(items) {
  if (!items || !items.length) return { x: 0, y: 0, width: 0, height: 0 };
  const left = Math.min(...items.map((item) => item.x));
  const top = Math.min(...items.map((item) => item.y));
  const right = Math.max(...items.map((item) => item.x + item.width));
  const bottom = Math.max(...items.map((item) => item.y + item.height));
  return {
    x: Number(left.toFixed(2)),
    y: Number(top.toFixed(2)),
    width: Number(Math.max(0, right - left).toFixed(2)),
    height: Number(Math.max(0, bottom - top).toFixed(2)),
  };
}

function makeBboxRange(boxes) {
  const valid = (boxes || []).filter((box) => box && Number(box.width) >= 0 && Number(box.height) >= 0);
  if (!valid.length) return null;
  const left = Math.min(...valid.map((box) => Number(box.x || 0)));
  const top = Math.min(...valid.map((box) => Number(box.y || 0)));
  const right = Math.max(...valid.map((box) => Number(box.x || 0) + Number(box.width || 0)));
  const bottom = Math.max(...valid.map((box) => Number(box.y || 0) + Number(box.height || 0)));
  return {
    xMin: Number(left.toFixed(2)),
    yMin: Number(top.toFixed(2)),
    xMax: Number(right.toFixed(2)),
    yMax: Number(bottom.toFixed(2)),
  };
}

function getSegmentPageNumbers(segment) {
  const pages = new Set();
  (segment && segment.lines || []).forEach((line) => {
    const pageNumber = Number(line && line.pageNumber || 0);
    if (pageNumber) pages.add(pageNumber);
  });
  (segment && segment.lineBoxes || []).forEach((line) => {
    const pageNumber = Number(line && line.pageNumber || 0);
    if (pageNumber) pages.add(pageNumber);
  });
  const ownPage = Number(segment && segment.pageNumber || 0);
  if (ownPage) pages.add(ownPage);
  return [...pages].sort((a, b) => a - b);
}

function getSegmentColumns(segment) {
  const columns = new Set();
  (segment && segment.lines || []).forEach((line) => columns.add(String(line && line.column || segment.column || "single")));
  (segment && segment.lineBoxes || []).forEach((line) => columns.add(String(line && line.column || segment.column || "single")));
  if (segment && segment.column) columns.add(String(segment.column));
  return [...columns].filter(Boolean);
}

function isNormalFullWidthSegment(segment) {
  return ["title", "author", "affiliation", "correspondence", "receivedDate", "funding", "abstract-title", "keywords", "heading", "caption"].includes(String(segment && segment.type || ""));
}

function getOversizedSegmentWarning(segment, pageSize) {
  const bbox = segment && segment.bbox;
  if (!bbox || !pageSize || !pageSize.width || !pageSize.height) return "";
  const width = Number(bbox.width || 0);
  const height = Number(bbox.height || 0);
  const x = Number(bbox.x || 0);
  const y = Number(bbox.y || 0);
  if ((width > pageSize.width * 0.95 && !isNormalFullWidthSegment(segment)) || height > pageSize.height * 0.6) {
    return "oversized_segment_bbox";
  }
  if (x < -2 || y < -2 || x + width > pageSize.width + 2 || y + height > pageSize.height + 2) {
    return "segment_bbox_out_of_page";
  }
  return "";
}

function makePreviewText(text, maxLength = 50) {
  const value = normalizeExtractedPdfText(text || "");
  return value.length > maxLength ? `${value.slice(0, maxLength)}……` : value;
}

function textSuspiciousScore(text) {
  const value = String(text || "");
  if (!value) return { garbageRatio: 0, symbolRatio: 0 };
  const garbage = (value.match(/[\ufffd\ue000-\uf8ff\u0000-\u001f\u007f]/g) || []).length;
  const symbols = (value.match(/[^\p{L}\p{N}\s.,;:!?'"()[\]{}\-–—/%+*=<>]/gu) || []).length;
  return {
    garbageRatio: garbage / value.length,
    symbolRatio: symbols / value.length,
  };
}

function normalizePdfTextItem(item, pageNumber, pageHeight, pageWidth) {
  const text = normalizeExtractedPdfText(item && item.str ? item.str : "");
  if (!text) return null;
  const transform = item.transform || [];
  const x = Number(transform[4] || 0);
  const baselineY = Number(transform[5] || 0);
  const width = Number(item.width || 0);
  const height = Number(item.height || Math.abs(transform[3] || transform[0] || 0) || 0);
  const fontSize = Number(Math.abs(transform[3] || transform[0] || height || 0));
  return {
    pageNumber,
    str: item && item.str ? String(item.str) : "",
    text,
    x: Number(x.toFixed(2)),
    y: Number((pageHeight - baselineY).toFixed(2)),
    baselineY: Number(baselineY.toFixed(2)),
    baselineTopY: Number((pageHeight - baselineY).toFixed(2)),
    width: Number(width.toFixed(2)),
    height: Number(height.toFixed(2)),
    pageWidth: Number((pageWidth || 0).toFixed(2)),
    pageHeight: Number((pageHeight || 0).toFixed(2)),
    fontName: item.fontName || "",
    fontSize: Number(fontSize.toFixed(2)),
    transform: Array.isArray(transform) ? transform.map((value) => Number(value || 0)) : [],
  };
}

function normalizeFormulaScriptText(text) {
  return String(text || "")
    .replace(/[\u2212\u2010-\u2015]/g, "-")
    .replace(/\s+/g, "");
}

function normalizeMergedFormulaLineText(text) {
  return normalizeExtractedPdfText(text || "")
    .replace(/\s*([×x])\s*10\s*\^\s*/g, (_match, sign) => `${sign}10^`)
    .replace(/([×x])\s*10\s*[-−]\s*(\d+)/g, (_match, sign, exponent) => `${sign}10^-${exponent}`)
    .replace(/([×x])\s*10\s+(\d{1,3})(?=\s*erg\b|\s*[A-Za-z])/g, (_match, sign, exponent) => `${sign}10^${exponent}`)
    .replace(/\berg\s+s\s*[-−]\s*1\b/gi, "erg s^-1")
    .replace(/\bcm\s*[-−]\s*2\b/gi, "cm^-2")
    .replace(/\bs\s*[-−]\s*1\b/gi, "s^-1")
    .replace(/([×x])\s+10/g, "$110")
    .replace(/10\s+\^/g, "10^")
    .replace(/\berg\s+s\^/gi, "erg s^")
    .replace(/\bcm\s+\^/gi, "cm^")
    .replace(/\bM\s*⊙/g, "M⊙")
    .replace(/\s+([,.;:!?)]|\^)/g, "$1")
    .replace(/(\()\s+/g, "$1")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function getDominantLineFontSize(items) {
  const buckets = new Map();
  (items || []).forEach((item) => {
    const size = Math.round(Number(item.fontSize || item.height || 0) * 10) / 10;
    if (!size) return;
    const current = buckets.get(size) || { size, width: 0, count: 0 };
    current.width += Math.max(Number(item.width || 0), String(item.text || "").length);
    current.count += 1;
    buckets.set(size, current);
  });
  const ranked = [...buckets.values()].sort((a, b) => (b.width - a.width) || (b.count - a.count) || (b.size - a.size));
  return ranked[0] ? ranked[0].size : 0;
}

function getDominantLineBaselineY(items, dominantFontSize) {
  const normalItems = (items || []).filter((item) => {
    const size = Number(item.fontSize || item.height || 0);
    return !dominantFontSize || size >= dominantFontSize * 0.86;
  });
  const source = normalItems.length ? normalItems : (items || []);
  if (!source.length) return 0;
  return source.reduce((sum, item) => sum + Number(item.baselineY || 0), 0) / source.length;
}

function classifyFormulaScriptItem(item, dominantFontSize, dominantBaselineY) {
  const fontSize = Number(item && (item.fontSize || item.height) || 0);
  const baselineY = Number(item && item.baselineY || 0);
  if (!fontSize || !dominantFontSize || fontSize > dominantFontSize * 0.88) return "normal";
  const baselineDelta = baselineY - Number(dominantBaselineY || 0);
  const threshold = Math.max(1.4, dominantFontSize * 0.16);
  if (baselineDelta > threshold) return "superscript";
  if (baselineDelta < -threshold) return "subscript";
  return "normal";
}

function shouldAttachScriptToPrevious(text) {
  return /(?:10|[A-Za-z]|cm|erg|M|L|R|\)|\])$/.test(String(text || "").trim());
}

function buildLineTextFromPositionedItems(lineItems, dominantFontSize, dominantBaselineY) {
  let text = "";
  let lastEnd = null;
  lineItems.forEach((item) => {
    const itemText = normalizeExtractedPdfText(item.text || item.str || "");
    if (!itemText) return;
    const scriptKind = classifyFormulaScriptItem(item, dominantFontSize, dominantBaselineY);
    if (scriptKind === "superscript" || scriptKind === "subscript") {
      const scriptText = normalizeFormulaScriptText(itemText);
      if (!scriptText) return;
      if (shouldAttachScriptToPrevious(text)) {
        text = text.replace(/\s+$/g, "");
        text += scriptKind === "superscript" ? `^${scriptText}` : `_${scriptText}`;
      } else {
        text += (text && !/\s$/.test(text) ? " " : "") + scriptText;
      }
      lastEnd = item.x + Math.max(item.width, 0);
      return;
    }

    if (!text) {
      text = itemText;
    } else {
      const avgCharWidth = itemText.length ? Math.max(1.5, item.width / itemText.length) : Math.max(2, item.fontSize * 0.35);
      const gap = lastEnd === null ? 0 : item.x - lastEnd;
      const previousLooksFormulaPrefix = /(?:[×x]|10\^?|erg|cm|M)$/.test(text.trim());
      const currentLooksTightFormula = /^(?:10|erg|s|cm|⊙|[+\-−]?\d+|[A-Za-z]?\^)/.test(itemText);
      const needsSpace = gap > avgCharWidth * 0.45 &&
        !previousLooksFormulaPrefix &&
        !currentLooksTightFormula &&
        !/\s$/.test(text) &&
        !/^[,.;:!?)]/.test(itemText);
      text += needsSpace ? ` ${itemText}` : itemText;
    }
    lastEnd = item.x + Math.max(item.width, 0);
  });
  return normalizeMergedFormulaLineText(text);
}

function mergeTextItemsIntoLines(items) {
  const rows = [];
  items.forEach((item) => {
    const baselineTopY = Number(item.baselineTopY || item.y || 0);
    const tolerance = Math.max(4, Number(item.fontSize || item.height || 0) * 0.75);
    let row = rows.find((candidate) => Math.abs(candidate.baselineTopY - baselineTopY) <= Math.max(candidate.tolerance, tolerance));
    if (!row) {
      row = { baselineTopY, centerY: item.y + item.height / 2, tolerance, items: [] };
      rows.push(row);
    }
    row.items.push(item);
    const dominantFontSize = getDominantLineFontSize(row.items);
    const dominantBaselineY = getDominantLineBaselineY(row.items, dominantFontSize);
    row.baselineTopY = row.items[0] && row.items[0].pageHeight
      ? Number(row.items[0].pageHeight || 0) - dominantBaselineY
      : row.items.reduce((sum, part) => sum + Number(part.baselineTopY || part.y || 0), 0) / row.items.length;
    row.centerY = row.items.reduce((sum, part) => sum + part.y + part.height / 2, 0) / row.items.length;
    row.tolerance = Math.max(row.tolerance, tolerance);
  });

  return rows
    .map((row) => {
      const lineItems = row.items.sort((a, b) => a.x - b.x);
      const dominantFontSize = getDominantLineFontSize(lineItems);
      const dominantBaselineY = getDominantLineBaselineY(lineItems, dominantFontSize);
      const text = buildLineTextFromPositionedItems(lineItems, dominantFontSize, dominantBaselineY);
      return {
        pageNumber: lineItems[0] ? lineItems[0].pageNumber : 0,
        column: lineItems[0] ? lineItems[0].column || "single" : "single",
        layoutType: lineItems[0] ? lineItems[0].layoutType || "single_column" : "single_column",
        sourceLanguageHint: lineItems[0] ? lineItems[0].sourceLanguageHint || "unknown" : "unknown",
        text: normalizeExtractedPdfText(text),
        items: lineItems,
        bbox: makeBBox(lineItems),
        centerY: row.centerY,
        avgFontSize: lineItems.reduce((sum, item) => sum + (item.fontSize || 0), 0) / Math.max(1, lineItems.length),
      };
    })
    .filter((line) => line.text)
    .sort((a, b) => {
      if (a.pageNumber !== b.pageNumber) return a.pageNumber - b.pageNumber;
      return a.bbox.y - b.bbox.y;
    });
}

function getPdfLanguageHint(text) {
  const value = String(text || "");
  const nonSpace = value.replace(/\s/g, "").length || 1;
  const cjkCount = (value.match(/[\u3400-\u9fff]/g) || []).length;
  const latinCount = (value.match(/[A-Za-z]/g) || []).length;
  if (cjkCount / nonSpace > 0.3) return "zh";
  if (latinCount / nonSpace > 0.6) return "en";
  return "unknown";
}

function getLinePageSize(lines, fallbackItems) {
  const source = (lines && lines[0] && lines[0].items && lines[0].items[0]) || (fallbackItems && fallbackItems[0]) || {};
  return {
    width: Number(source.pageWidth || 0),
    height: Number(source.pageHeight || 0),
  };
}

function detectPageLayout(pageLineBoxes, pageWidth, pageHeight) {
  const lines = (pageLineBoxes || []).filter((line) => line && line.bbox && normalizeExtractedPdfText(line.text || ""));
  const pageText = lines.map((line) => line.text || "").join("");
  const languageHint = getPdfLanguageHint(pageText);
  const bodyLines = lines.filter((line) => getPdfLineType(line) === "body" && !isNoisePdfLine(line));
  const targetLines = bodyLines.length >= 8 ? bodyLines : lines;
  if (!targetLines.length) {
    return { pageNumber: lines[0] ? lines[0].pageNumber : 0, layoutType: "scanned_or_image", confidence: 0.2, columnCount: 0, leftColumnRange: null, rightColumnRange: null, bodyTextRatio: 0, languageHint };
  }

  const xs = targetLines.map((line) => Number(line.bbox.x || 0)).sort((a, b) => a - b);
  const leftCluster = targetLines.filter((line) => Number(line.bbox.x || 0) < pageWidth * 0.45);
  const rightCluster = targetLines.filter((line) => Number(line.bbox.x || 0) > pageWidth * 0.50);
  const wideLines = targetLines.filter((line) => Number(line.bbox.width || 0) > pageWidth * 0.55);
  const textLineRatio = bodyLines.length / Math.max(1, lines.length);
  const leftRange = leftCluster.length ? {
    x: Math.min(...leftCluster.map((line) => line.bbox.x)),
    right: Math.max(...leftCluster.map((line) => line.bbox.x + line.bbox.width)),
  } : null;
  const rightRange = rightCluster.length ? {
    x: Math.min(...rightCluster.map((line) => line.bbox.x)),
    right: Math.max(...rightCluster.map((line) => line.bbox.x + line.bbox.width)),
  } : null;
  const leftY = leftCluster.map((line) => line.bbox.y).sort((a, b) => a - b);
  const rightY = rightCluster.map((line) => line.bbox.y).sort((a, b) => a - b);
  const overlapY = leftY.length && rightY.length
    ? Math.max(0, Math.min(leftY[leftY.length - 1], rightY[rightY.length - 1]) - Math.max(leftY[0], rightY[0]))
    : 0;
  const leftWidth = leftRange ? leftRange.right - leftRange.x : 0;
  const rightWidth = rightRange ? rightRange.right - rightRange.x : 0;
  const widthSimilarity = leftWidth && rightWidth ? Math.min(leftWidth, rightWidth) / Math.max(leftWidth, rightWidth) : 0;
  const doubleScoreParts = [
    leftCluster.length >= 8 ? 0.18 : 0,
    rightCluster.length >= 8 ? 0.18 : 0,
    leftCluster.length > targetLines.length * 0.25 && rightCluster.length > targetLines.length * 0.25 ? 0.18 : 0,
    overlapY > pageHeight * 0.22 ? 0.18 : 0,
    widthSimilarity > 0.62 ? 0.14 : 0,
    wideLines.length < targetLines.length * 0.35 ? 0.14 : 0,
  ];
  let doubleConfidence = doubleScoreParts.reduce((sum, part) => sum + part, 0);
  if (languageHint === "zh") doubleConfidence -= 0.24;

  const xSpread = xs.length ? xs[Math.floor(xs.length * 0.9)] - xs[Math.floor(xs.length * 0.1)] : 0;
  const singleConfidence = Math.max(
    0.35,
    (languageHint === "zh" ? 0.35 : 0) +
    (xSpread < pageWidth * 0.16 ? 0.25 : 0) +
    (wideLines.length > targetLines.length * 0.35 ? 0.2 : 0) +
    (rightCluster.length < targetLines.length * 0.2 ? 0.2 : 0)
  );

  let layoutType = "single_column";
  let confidence = Math.min(0.98, singleConfidence);
  let columnCount = 1;
  if (doubleConfidence > 0.75) {
    const topWideLines = wideLines.filter((line) => Number(line.bbox.y || 0) < pageHeight * 0.38);
    layoutType = topWideLines.length >= 3 ? "mixed" : "double_column";
    confidence = Math.min(0.98, doubleConfidence);
    columnCount = 2;
  }

  return {
    pageNumber: lines[0] ? lines[0].pageNumber : 0,
    layoutType,
    confidence: Number(confidence.toFixed(2)),
    columnCount,
    leftColumnRange: leftRange,
    rightColumnRange: rightRange,
    bodyTextRatio: Number(textLineRatio.toFixed(2)),
    languageHint,
  };
}

function getPdfLineType(line) {
  const text = normalizeExtractedPdfText(line && line.text || "");
  const noiseType = getPdfNoiseLineType(line);
  if (noiseType) return noiseType;
  const topMatterType = getTopMatterLineType(line);
  if (topMatterType) return topMatterType;
  if (isLikelyChineseTitleLine(line)) return "title";
  if (/^ABSTRACT$/i.test(text)) return "abstract";
  if (/^Keywords:/i.test(text) || /^Key words:/i.test(text)) return "keywords";
  if (/^\d+\.\s+[A-Z][A-Z\s]+$/.test(text)) return "heading";
  if (/^\d{1,2}\.\d{1,2}\.\s+[A-Z]/.test(text)) return "heading";
  if (isReferencesHeadingText(text)) return "heading";
  if (isSectionHeadingText(text)) return "heading";
  if (isTrueCaptionStart(text, { allowNoRegion: true })) return "caption";
  return "body";
}

function isLikelyChineseTitleLine(line) {
  const text = normalizeExtractedPdfText(line && line.text || "");
  if (!text || getPdfLanguageHint(text) !== "zh") return false;
  if (text.length > 22 || /[。！？.!?]$/.test(text)) return false;
  const pageWidth = Number(line && line.items && line.items[0] && line.items[0].pageWidth || 0);
  const pageHeight = Number(line && line.items && line.items[0] && line.items[0].pageHeight || 0);
  const bbox = line && line.bbox || {};
  if (!pageWidth || !pageHeight || !bbox.width) return false;
  const center = Number(bbox.x || 0) + Number(bbox.width || 0) / 2;
  const centered = Math.abs(center - pageWidth / 2) < pageWidth * 0.16;
  const topArea = Number(bbox.y || 0) < pageHeight * 0.10;
  const narrowTitle = Number(bbox.width || 0) < pageWidth * 0.52;
  return Boolean(centered && topArea && narrowTitle);
}

function isPdfHeadingLine(line) {
  return getPdfLineType(line) !== "body";
}

function isCaptionMarkerText(text) {
  const value = normalizeExtractedPdfText(text || "");
  return /^(?:Figure\s+\d+\.?|Fig\.\s*\d+\.?|Table\s+\d+\.?|图\s*\d+[.．、]?|表\s*\d+[.．、]?)/i.test(value);
}

function isInlineFigureReferenceText(text, previousText = "", nextText = "") {
  const value = normalizeExtractedPdfText(text || "");
  const previous = normalizeExtractedPdfText(previousText || "");
  const next = normalizeExtractedPdfText(nextText || "");
  if (!value) return false;
  if (/\b(?:shown in|as shown in|see|are shown in|shown|right panel of|left panel of)\s+Figure\s+\d+\b/i.test(value)) return true;
  if (/^(?:Figure|Fig\.)\s+\d+$/i.test(value) && /\b(?:shown in|as shown in|see|are shown in|shown|shown in|Figure)\s*$/i.test(previous)) return true;
  if (/^(?:Figure|Fig\.)\s+\d+$/i.test(value) && /^[,.;:]?\s*(?:and|where|which|with|for|from|of|the|a|an)\b/i.test(next)) return true;
  if (/\bFigure\s+\d+\b/i.test(value) && !/^\s*(?:Figure|Fig\.|Table)\s+\d+\s*[.:]\s+\S/i.test(value) && /^(?:The|This|These|Those|We|A|An|In|For|From|As|Since)\b/i.test(value)) return true;
  return false;
}

function isTrueCaptionStart(lineOrText, context = {}) {
  const text = typeof lineOrText === "string" ? lineOrText : getSegmentLineText(lineOrText);
  const value = normalizeExtractedPdfText(text || "");
  if (!value) return false;
  if (isInlineFigureReferenceText(value, context.previousText, context.nextText)) return false;
  const startsStrongCaption = /^\s*(?:Figure|Fig\.|Table)\s+\d+\s*[.:]\s+\S/i.test(value);
  const startsCaptionWithWords = /^\s*(?:Figure|Fig\.|Table)\s+\d+\s+(?:Left|Right|Top|Bottom|The|A|An|Image|Spectrum|Spectra|Contours?|Panels?|Source|Flux|Map|Model)\b/i.test(value);
  if (!startsStrongCaption && !startsCaptionWithWords) return false;
  if (isBodyLikeCaptionText(value)) return false;
  const box = context.box || (lineOrText && lineOrText.bbox) || {};
  const inCaptionZone = (context.captionRegions || []).some((region) => bboxOverlapRatio(box, region) > 0.01 || (bboxCrossesRegionY(box, region) && bboxHorizontalOverlapRatio(box, region) > 0.35));
  const nearImage = (context.imageRegions || []).some((region) => {
    const top = Number(box.y || 0);
    const regionBottom = Number(region.y || 0) + Number(region.height || 0);
    const verticalGap = top - regionBottom;
    return verticalGap >= -8 && verticalGap <= 80 && bboxHorizontalOverlapRatio(box, region) > 0.25;
  });
  return Boolean(inCaptionZone || nearImage || context.allowNoRegion);
}

function isBodyStartText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value || isCaptionMarkerText(value) || /^(?:Left|Right|Top|Bottom)\s*:/i.test(value)) return false;
  const words = value.match(/[A-Za-z][A-Za-z'\-]*/g) || [];
  if (words.length < 5 || !/^[A-Z]/.test(value)) return false;
  return /\b(?:is|are|was|were|has|have|had|yields?|shows?|provides?|uses?|used|derived|measured|estimated|performed|generated|analyzed|decomposed|computed|obtained)\b/i.test(value) || /[.!?]$/.test(value);
}

function isReferencesHeadingText(text) {
  return /^(REFERENCES|BIBLIOGRAPHY|WORKS CITED)$/i.test(normalizeExtractedPdfText(text || ""));
}

function isSectionHeadingText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value || value.length > 180) return false;
  const headingProseTail = value.replace(/^\d+(?:\.\d+)*\.?\s+/, "");
  if (/^\d+\.\d+\.\s+[A-Z]/.test(value) && /\b(we|the|this|these|those|was|were|is|are|adopt|derive|derived|shows|show|using|based|within|surrounding)\b/i.test(headingProseTail)) {
    return false;
  }
  if (/^\d+(?:\.\d+){2,}\.?\s+[A-Z]/.test(value) && /\b(we|the|this|these|those|was|were|is|are|adopt|derive|derived|shows|show|using|based|within|surrounding)\b/i.test(headingProseTail)) {
    return false;
  }
  if (/^\d+(?:\.\d+)*\.?\s+[A-Z][A-Za-z0-9]/.test(value)) return true;
  if (/^\d+\s*\|\s+[A-Z][A-Za-z0-9]/.test(value)) return true;
  if (/^[A-Z][A-Z\s]{3,}$/.test(value) && value.length <= 60) return true;
  return /^(Introduction|Roadmap|Conclusion|Conclusions|Discussion|Methods?|Results?|Endnotes?|Notes?|Acknowledg(?:e)?ments?|Conflicts? of Interest|Funding|Data Availability)\b/i.test(value);
}

function isAbstractStopText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value) return false;
  if (isPdfFooterOrWatermarkText(value)) return true;
  if (isReferencesHeadingText(value)) return true;
  if (/^(?:\d+\s*(?:[|.]|:)\s*)/.test(value)) return true;
  return isSectionHeadingText(value);
}

function isPdfFooterOrWatermarkText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value) return false;
  return /^(Ratio,?\s*2025|Downloaded from|Wiley Online Library|Creative Commons|This is an open access article|©|\(c\)|Copyright|DOI\b|https?:\/\/|onlinelibrary\.wiley\.com)/i.test(value) ||
    /\b(open access article|Creative Commons License|properly cited|all use, distribution and reproduction|Downloaded from https?:\/\/onlinelibrary\.wiley\.com)\b/i.test(value);
}

function getPdfNoiseLineType(line) {
  const text = normalizeExtractedPdfText(line && line.text || "");
  if (!text) return "";
  const bbox = line && line.bbox || {};
  const items = line && line.items || [];
  const pageHeight = Number(items[0] && items[0].pageHeight || 0);
  const pageWidth = Number(items[0] && items[0].pageWidth || 0);
  const x = Number(bbox.x || 0);
  const y = Number(bbox.y || 0);
  const width = Number(bbox.width || 0);
  const height = Number(bbox.height || 0);
  const wordCount = (text.match(/[A-Za-z]{2,}/g) || []).length;
  if (/Downloaded from https?:\/\/onlinelibrary\.wiley\.com/i.test(text) || /Wiley Online Library/i.test(text)) return "watermark";
  if (/Creative Commons|open access article|properly cited|all use, distribution and reproduction|©|Copyright/i.test(text)) return "licenseText";
  if (/^Ratio,?\s*2025$/i.test(text)) return "footer";
  if (/^\d+$/.test(text) && pageHeight > 0 && (y < pageHeight * 0.06 || y > pageHeight * 0.92)) return "pageNumber";
  if (pageHeight > 0 && (y < pageHeight * 0.045 || y > pageHeight * 0.94) && (
    /^Ratio\b/i.test(text) ||
    /journal|doi|license|downloaded|wiley|online library/i.test(text) ||
    (text.length <= 28 && wordCount <= 3)
  )) return y < pageHeight * 0.12 ? "header" : "footer";
  if (width > 0 && height > 0 && width < 50 && height > 100 && wordCount <= 6) return "margin";
  if (pageWidth > 0 && (x > pageWidth * 0.95 || x + width > pageWidth * 1.03) && text.length < 120) return "margin";
  return "";
}

function getTopMatterLineType(line) {
  const text = normalizeExtractedPdfText(line && line.text || "");
  if (!text) return "";
  if (/^Funding\s*:/i.test(text)) return "funding";
  if (/^Keywords?\s*:/i.test(text) || /^Key words?\s*:/i.test(text)) return "keywords";
  if (/^(Correspondence|Corresponding author)\s*:/i.test(text) || /\bE-?mail\s*:/i.test(text)) return "correspondence";
  if (/^(Received|Revised|Accepted|Published)\b/i.test(text)) return "receivedDate";
  return "";
}

function isReferenceText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value || value.length < 20) return false;
  const hasYear = /\b(19|20)\d{2}\b/.test(value);
  const hasReferenceToken = /\b(doi:|ApJ|ApJL|ApJS|MNRAS|Nature|PASP|A&A|AJ|ApJL|ApJS|MNRAS|ApJ,|ApJS,|MNRAS,)\b/i.test(value);
  const hasAuthorPattern = /^[A-Z][A-Za-z\u00c0-\u024f\u0300-\u036f'`~ .-]+,\s+[A-Z]/.test(value);
  return Boolean(hasYear && (hasReferenceToken || hasAuthorPattern));
}

function isReferenceStartLineText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value || value.length < 10) return false;
  if (/^(doi:|https?:|www\.|\d{4}[a-z]?\b|et\s+al\.|&\s)/i.test(value)) return false;
  if (/^(Nature|MNRAS|ApJ|ApJL|ApJS|PASP|PASJ|A&A|AJ|Society|Conference|Analysis|Operations|Astrophysics|FAST)\b/i.test(value)) {
    return false;
  }
  return /^[A-Z][A-Za-z\u00c0-\u024f\u0300-\u036f'`´~ .-]{1,80},\s*(?:[A-Z]\.|[A-Z][a-z]|&)/u.test(value);
}

function isImageLabelText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value || value.length > 24) return false;
  if (isCaptionMarkerText(value) || getPdfLineType({ text: value }) === "heading") return false;
  return /\b(keV|kpc|JWST|F200W|WFC|0\.2|43|17)\b/i.test(value) || /^[\d.]+\s*(keV|kpc)$/i.test(value);
}

function isImageInternalTextLine(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value || isCaptionMarkerText(value) || getPdfLineType({ text: value }) === "heading") return false;
  if (/^(Left|Right|Top|Bottom):\s+/i.test(value)) return false;
  if (value.length > 28) return false;
  return isImageLabelText(value);
}

function getImageTextBodyLikeRiskReason(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value) return "";
  const words = value.match(/[A-Za-z][A-Za-z'-]*/g) || [];
  if (value.length > 40) return "image_text_long_text";
  if (words.length > 6) return "image_text_many_words";
  if (/^(The|We|This|Since|Because|Therefore|Estimating|Estimated|These|Those|Our|A|An)\b/i.test(value)) return "image_text_body_like_start";
  if (/\b(is|are|was|were|be|been|being|derived|estimated|provides|reflects|yields|conclude|shows|show|suggests|indicates|applying|using|obtained|computed|measured)\b/i.test(value)) {
    return "image_text_body_like_verb";
  }
  if (/[.!?]\s+[A-Z]/.test(value)) return "image_text_multiple_sentences";
  return "";
}

function isBodyLikeImageText(text) {
  return Boolean(getImageTextBodyLikeRiskReason(text));
}

function getCaptionBodyLikeRiskReason(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value) return "";
  if (/^\s*(?:Figure|Fig\.|Table)\s+\d+\s+(?:shows?|shown|presents?|illustrates?|displays?|contains?|gives?|provides?)\b/i.test(value)) {
    return "caption_marker_body_sentence";
  }
  if (isCaptionMarkerText(value) && /^\s*(?:Figure|Fig\.|Table)\s+\d+\s*[.:]\s+/i.test(value)) return "";
  const words = value.match(/[A-Za-z][A-Za-z'-]*/g) || [];
  if (/^[a-z][a-z'-]+\s+\w+/u.test(value) && words.length >= 3) return "caption_lowercase_fragment_body";
  if (words.length >= 7 && /\b(is|are|was|were|derived|defined|measured|obtained|computed|shown|shows|represents|using|based|therefore|conclude|flux|luminosity|spectrum|spectra|model|fit)\b/i.test(value)) {
    return "caption_body_like_prose";
  }
  if (/^(The|We|This|These|Those|Therefore|Since|Because|Estimating|Using|Based)\b/i.test(value) && words.length >= 4) {
    return "caption_body_like_start";
  }
  if (/\bFigure\s+\d+\b/i.test(value) && !isCaptionMarkerText(value) && words.length >= 6) {
    return "caption_contains_figure_reference_body";
  }
  return "";
}

function isBodyLikeCaptionText(text) {
  return Boolean(getCaptionBodyLikeRiskReason(text));
}

function demoteBodyLikeCaptionSegmentsBeforeTranslation(segments, pipelineConfig) {
  if (!isPaperPdfConfig(pipelineConfig)) return segments || [];
  return (segments || []).map((segment) => {
    if (!segment || String(segment.type || "") !== "caption") return segment;
    const reason = getCaptionBodyLikeRiskReason(segment.sourceText || segment.previewText || "");
    if (!reason) return segment;
    return {
      ...segment,
      type: "body",
      captionBodyLikeDemotedToBody: true,
      captionBodyLikeRiskReason: reason,
      classificationReason: "caption_body_like_demoted_to_body",
      zoneType: String(segment.zoneType || "") === "captionZone" ? "" : segment.zoneType,
      warnings: Array.from(new Set([...(segment.warnings || []), "caption_body_like_demoted_to_body"])),
    };
  });
}

function isStandaloneFigureReferenceCaption(segment) {
  const text = normalizeExtractedPdfText(segment && segment.sourceText || "");
  if (/^(?:Figure|Fig\.|Table)\s+\d+$/i.test(text)) return true;
  // An inline reference fragment reads like "Figure 1, reveals clear tidal debris in the" — a comma
  // (not the period/colon a real caption uses) immediately after the number, followed by a lowercase
  // continuation. That shape only occurs when running body prose ("...shown in the right panel of
  // Figure 1, reveals...") got cut at the figure number and the tail misclassified as a caption start;
  // a genuine caption never continues straight into lowercase prose right after "Figure N,".
  return /^(?:Figure|Fig\.|Table)\s+\d+\s*,\s*[a-z]/.test(text);
}

function segmentLineBoxOverlapExists(a, b) {
  const aBoxes = (a && a.lineBoxes || []).map((line) => ({ x: line.x, y: line.y, width: line.width, height: line.height })).filter(Boolean);
  const bBoxes = (b && b.lineBoxes || []).map((line) => ({ x: line.x, y: line.y, width: line.width, height: line.height })).filter(Boolean);
  return aBoxes.some((abox) => bBoxes.some((bbox) => bboxOverlapArea(abox, bbox) > 0));
}

function isCaptionBodyConflict(caption, body) {
  if (!caption || !body || String(body.type || "") !== "body") return false;
  if (Number(caption.pageNumber || 0) !== Number(body.pageNumber || 0)) return false;
  if (String(caption.column || "single") !== String(body.column || "single")) return false;
  const captionText = normalizeExtractedPdfText(caption.sourceText || "");
  const bodyText = normalizeExtractedPdfText(body.sourceText || "");
  if (!isStandaloneFigureReferenceCaption(caption)) return false;
  if (bodyText.includes(captionText)) return true;
  if (bboxOverlapRatio(caption.bbox, body.bbox) > 0.35) return true;
  if (segmentLineBoxOverlapExists(caption, body)) return true;
  const captionTop = Number(caption.bbox && caption.bbox.y || 0);
  const bodyBottom = Number(body.bbox && body.bbox.y || 0) + Number(body.bbox && body.bbox.height || 0);
  const lineHeight = Math.max(6, getPaperSegmentAverageFontSize(body) || getPaperSegmentAverageFontSize(caption) || 9);
  if (Math.abs(captionTop - bodyBottom) < lineHeight * 1.5) return true;
  const captionIds = new Set(getSegmentSourceLineIds(caption));
  if (getSegmentSourceLineIds(body).some((id) => captionIds.has(id))) return true;
  return /\b(?:shown in|as shown in|see|are shown in|shown)\s*$/i.test(bodyText);
}

function mergeInlineFigureReferenceCaptionIntoBody(body, caption) {
  const sourcePageContract = finalizePaperSourceMergeContract(body, caption);
  if (sourcePageContract.status !== 'ok') return null;
  const captionText = normalizeExtractedPdfText(caption && caption.sourceText || "");
  const bodyText = normalizeExtractedPdfText(body && body.sourceText || "");
  const mergedText = bodyText.includes(captionText) ? bodyText : makeParagraphSourceText([{ text: bodyText }, { text: captionText }]);
  const bodyTranslated = cleanPdfText(body && body.translatedText);
  const captionTranslated = cleanPdfText(caption && caption.translatedText);
  const mergedTranslated = captionTranslated && !bodyTranslated.includes(captionTranslated)
    ? makeParagraphSourceText([{ text: bodyTranslated }, { text: captionTranslated }])
    : bodyTranslated;
  const lineBoxes = (body.lineBoxes || []).concat(caption.lineBoxes || []);
  const lines = (body.lines || []).concat(caption.lines || []);
  return {
    ...body,
    sourceText: mergedText,
    translatedText: mergedTranslated || body.translatedText || "",
    previewText: makePreviewText(mergedText),
    lineBoxes,
    lines,
    items: (body.items || []).concat(caption.items || []),
    bbox: makeBBoxFromLineBoxes(lineBoxes.length ? lineBoxes : [body.bbox, caption.bbox].filter(Boolean)),
    inlineFigureReferenceMerged: true,
    inlineFigureReferenceMergedCount: Number(body.inlineFigureReferenceMergedCount || 0) + 1,
    captionBodyConflictResolved: true,
    captionBodyConflictSegmentIds: Array.from(new Set([...(body.captionBodyConflictSegmentIds || []), String(caption.id || captionText)])),
    captionDemotedToBodyContinuation: true,
    classificationReason: body.classificationReason || "body",
    warnings: Array.from(new Set([...(body.warnings || []), "inline_figure_reference_caption_merged"])),
  };
}

function resolveCaptionBodyConflictsForPaperSegments(segments, pipelineConfig) {
  if (!isPaperPdfConfig(pipelineConfig)) return segments || [];
  const output = [];
  const consumed = new Set();
  (segments || []).forEach((segment, index) => {
    if (consumed.has(index)) return;
    if (String(segment && segment.type || "") !== "caption" || !isStandaloneFigureReferenceCaption(segment)) {
      output.push(segment);
      return;
    }
    let bestBodyIndex = -1;
    let bestDistance = Infinity;
    (segments || []).forEach((candidate, candidateIndex) => {
      if (candidateIndex === index || consumed.has(candidateIndex)) return;
      if (!isCaptionBodyConflict(segment, candidate)) return;
      const distance = Math.abs(Number(segment.bbox && segment.bbox.y || 0) - Number(candidate.bbox && candidate.bbox.y || 0));
      if (distance < bestDistance) {
        bestDistance = distance;
        bestBodyIndex = candidateIndex;
      }
    });
    if (bestBodyIndex < 0) {
      output.push(segment);
      return;
    }
    const existingOutputIndex = output.findIndex((entry) => entry === segments[bestBodyIndex]);
    const merged = mergeInlineFigureReferenceCaptionIntoBody(segments[bestBodyIndex], segment);
    if (!merged) {
      output.push(segment);
      return;
    }
    consumed.add(index);
    consumed.add(bestBodyIndex);
    if (existingOutputIndex >= 0) {
      output[existingOutputIndex] = merged;
    } else {
      output.push(merged);
    }
  });
  (segments || []).forEach((segment, index) => {
    if (consumed.has(index)) return;
    if (!output.includes(segment)) output.push(segment);
  });
  return output.sort((a, b) => {
    const pageDiff = Number(a.pageNumber || 0) - Number(b.pageNumber || 0);
    if (pageDiff) return pageDiff;
    const colDiff = String(a.column || "single").localeCompare(String(b.column || "single"));
    if (colDiff) return colDiff;
    return Number(a.bbox && a.bbox.y || 0) - Number(b.bbox && b.bbox.y || 0);
  });
}

function isTrueImageInternalTextLine(lineOrText, imageRegion = null, _pageContext = null) {
  const text = typeof lineOrText === "string" ? lineOrText : lineOrText && lineOrText.text;
  const value = normalizeExtractedPdfText(text || "");
  if (!value || value.length > 35) return false;
  if (isBodyLikeImageText(value)) return false;
  if (!isImageInternalTextLine(value) && !isImageLabelText(value)) return false;
  if (imageRegion && String(imageRegion.source || "") === "caption-inferred" && !isImageLabelText(value)) return false;
  return true;
}

function getColumnLeftX(lines) {
  const xs = lines.map((line) => Number(line.bbox && line.bbox.x || 0)).filter((value) => value > 0).sort((a, b) => a - b);
  if (!xs.length) return 0;
  return xs[Math.floor(xs.length * 0.1)] || xs[0];
}

function lineEndsSentenceLike(text) {
  return /[.!?。！？:：]$/.test(normalizeExtractedPdfText(text || ""));
}

function lineEndsSentenceStrict(text) {
  return /[.!?:。！？：]$/.test(normalizeExtractedPdfText(text || ""));
}

function makeParagraphSourceText(lines) {
  let text = "";
  (lines || []).forEach((line) => {
    const value = normalizeExtractedPdfText(line && line.text || "");
    if (!value) return;
    if (!text) {
      text = value;
    } else if (/-$/.test(text) && /^[a-z]/.test(value)) {
      text = text.slice(0, -1) + value;
    } else if (/\s$/.test(text) || /^[,.;:!?)]/.test(value)) {
      text += value;
    } else {
      text += ` ${value}`;
    }
  });
  return normalizeExtractedPdfText(text);
}

function getColumnMetrics(lines) {
  const bodyLines = (lines || []).filter((line) => getPdfLineType(line) === "body");
  const targetLines = bodyLines.length >= 3 ? bodyLines : (lines || []);
  const left = Math.min(...targetLines.map((line) => Number(line.bbox && line.bbox.x || 0)));
  const right = Math.max(...targetLines.map((line) => Number(line.bbox && line.bbox.x + line.bbox.width || 0)));
  const width = Math.max(1, right - left);
  const avgLineHeight = targetLines.reduce((sum, line) => {
    return sum + Math.max(line.bbox.height, line.avgFontSize || 0, 10);
  }, 0) / Math.max(1, targetLines.length);
  const avgFontSize = targetLines.reduce((sum, line) => sum + Math.max(line.avgFontSize || 0, line.bbox.height || 0, 8), 0) / Math.max(1, targetLines.length);
  return { left, right, width, avgLineHeight, avgFontSize };
}

function getLineVisualStats(line, metrics) {
  const x = Number(line && line.bbox && line.bbox.x || 0);
  const width = Number(line && line.bbox && line.bbox.width || 0);
  const columnWidth = Math.max(1, metrics.width || 1);
  const lineStartGap = x - metrics.left;
  const lineEndGap = metrics.right - (x + width);
  return {
    lineStartGap,
    lineEndGap,
    columnWidth,
    lineFillRatio: width / columnWidth,
  };
}

function isNoisePdfLine(line) {
  const text = normalizeExtractedPdfText(line && line.text || "");
  if (!text) return true;
  if (getPdfLineType(line) !== "body") return false;
  if (/^\d+$/.test(text)) return true;
  if (text.length < 5) return true;
  if (/^sec\s*=$/i.test(text)) return true;
  if (/^[\d\s:.'′″+\-=]+$/.test(text)) return true;
  if (/^[.,;:)\]′″]/.test(text) && text.length < 40) return true;
  const alphaMatches = text.match(/[A-Za-z]{3,}/g) || [];
  const digitCount = (text.match(/\d/g) || []).length;
  const symbolCount = (text.match(/[^A-Za-z0-9\s]/g) || []).length;
  const hasFormulaNotation =
    /[≈≤≥±×÷∑∫∂∇→←↑↓⊕⊗∞√]/.test(text) ||
    /\[\s*[A-Z]{1,3}\s*(?:I{1,4}|V|VI{0,3}|IX|X)\s*\]/i.test(text) ||
    /\d\s*_\s*[-+\d[\{]|\d\s*\^\s*[-+\d[\{]/.test(text) ||
    /(?:L_?bol|L_?edd|M_?bol|erg\s*s\^|keV\b)/i.test(text);
  if (!hasFormulaNotation && text.length < 26 && alphaMatches.length <= 1 && digitCount / text.length > 0.25 && symbolCount / text.length > 0.18) {
    return true;
  }
  const pageHeight = Number(line.items && line.items[0] && line.items[0].pageHeight || 0);
  if (pageHeight > 0 && (line.bbox.y < pageHeight * 0.035 || line.bbox.y > pageHeight * 0.965) && text.length < 18) {
    return true;
  }
  return false;
}

function isFormulaLikeLine(line) {
  const text = normalizeExtractedPdfText(line && line.text || "");
  if (!text) return false;
  if (/[≈≤≥±×÷∑∫∂∇→←↑↓⊕⊗∞√]/.test(text)) return true;
  if (/\[\s*[A-Z]{1,3}\s*(?:I{1,4}|V|VI{0,3}|IX|X)\s*\]/i.test(text)) return true;
  if (/\d\s*_\s*[-+\d[\{]|\d\s*\^\s*[-+\d[\{]/.test(text)) return true;
  if (/(?:L_?bol|L_?edd|M_?bol|erg\s*s\^|keV\b)/i.test(text)) return true;
  const alphaMatches = text.match(/[A-Za-z]{3,}/g) || [];
  const digitCount = (text.match(/\d/g) || []).length;
  const symbolCount = (text.match(/[^A-Za-z0-9\s]/g) || []).length;
  return text.length < 35 && alphaMatches.length <= 1 && digitCount / text.length > 0.2 && symbolCount / text.length > 0.15;
}

function makeLineBoxFromLine(line, segmentId) {
  const fontSize = Number((line.avgFontSize || Math.max(line.bbox.height || 0, 10)).toFixed(2));
  const topPadding = fontSize * 0.25;
  const bottomPadding = fontSize * 0.25;
  const leftPadding = 1;
  const rightPadding = 1;
  return {
    pageNumber: line.pageNumber,
    x: Number((line.bbox.x - leftPadding).toFixed(2)),
    y: Number((line.bbox.y - topPadding).toFixed(2)),
    width: Number((line.bbox.width + leftPadding + rightPadding).toFixed(2)),
    height: Number((line.bbox.height + topPadding + bottomPadding).toFixed(2)),
    fontSize,
    text: line.text,
    sourceLineText: line.text,
    segmentId,
    column: line.column || "single",
    layoutType: line.layoutType || "single_column",
    sourceLanguageHint: line.sourceLanguageHint || getPdfLanguageHint(line.text || ""),
  };
}

function splitLongParagraph(paragraph) {
  const sourceText = makeParagraphSourceText(paragraph.lines || []);
  if (sourceText.length <= 2000 || isPdfHeadingLine(paragraph.lines && paragraph.lines[0])) return [paragraph];
  const chunks = [];
  let current = { ...paragraph, lines: [], items: [] };
  (paragraph.lines || []).forEach((line) => {
    const nextText = makeParagraphSourceText(current.lines.concat(line));
    if (current.lines.length && nextText.length > 2000 && lineEndsSentenceStrict(current.lines[current.lines.length - 1].text)) {
      chunks.push(current);
      current = { ...paragraph, lines: [], items: [] };
    }
    current.lines.push(line);
    current.items.push(...(line.items || []));
  });
  if (current.lines.length) chunks.push(current);
  return chunks;
}

function splitAndMergeParagraphs(paragraphs) {
  const split = [];
  paragraphs.forEach((paragraph) => {
    split.push(...splitLongParagraph(paragraph));
  });

  const merged = [];
  split.forEach((paragraph) => {
    const text = makeParagraphSourceText(paragraph.lines || []);
    const isHeading = isPdfHeadingLine(paragraph.lines && paragraph.lines[0]);
    const previous = merged[merged.length - 1];
    if (
      previous &&
      previous.type === "abstract" &&
      paragraph.type === "body" &&
      previous.pageNumber === paragraph.pageNumber &&
      previous.column === paragraph.column
    ) {
      paragraph.type = "abstract";
    }
    if (
      previous &&
      !isHeading &&
      text.length < 20 &&
      previous.pageNumber === paragraph.pageNumber &&
      previous.column === paragraph.column &&
      previous.type === "body" &&
      !isPdfHeadingLine(previous.lines && previous.lines[0]) &&
      finalizePaperSourceMergeContract(previous, paragraph).status === 'ok'
    ) {
      previous.lines.push(...paragraph.lines);
      previous.items.push(...paragraph.items);
      return;
    }
    merged.push(paragraph);
  });
  return merged;
}

function mergeLinesIntoParagraphs(lines) {
  const paragraphs = [];
  let current = null;
  const sortedLines = lines.slice().sort((a, b) => {
    if (a.pageNumber !== b.pageNumber) return a.pageNumber - b.pageNumber;
    if ((a.column || "single") !== (b.column || "single")) return String(a.column || "single").localeCompare(String(b.column || "single"));
    return a.bbox.y - b.bbox.y;
  }).filter((line) => {
    if (!isNoisePdfLine(line)) return true;
    if (/^\d+$/.test(normalizeExtractedPdfText(line && line.text || ""))) {
      currentPdfIgnoredPageNumberLines += 1;
    }
    currentPdfIgnoredNoiseLines += 1;
    return false;
  });
  const avgLineHeight = sortedLines.reduce((sum, line) => {
    return sum + Math.max(line.bbox.height, line.avgFontSize || 0, 10);
  }, 0) / Math.max(1, sortedLines.length);
  const columnMetrics = getColumnMetrics(sortedLines);

  sortedLines.forEach((line) => {
    const lineType = getPdfLineType(line);
    if (!current || current.pageNumber !== line.pageNumber || current.column !== line.column) {
      if (current) paragraphs.push(current);
      current = { pageNumber: line.pageNumber, column: line.column || "single", type: lineType, lines: [line], items: line.items.slice() };
      return;
    }

    const previous = current.lines[current.lines.length - 1];
    const gap = line.bbox.y - (previous.bbox.y + previous.bbox.height);
    const lineHeight = Math.max(previous.bbox.height, line.bbox.height, previous.avgFontSize || 0, line.avgFontSize || 0, 10);
    const previousLineType = getPdfLineType(previous);
    const previousIsHeading = previousLineType !== "body" && previousLineType !== "caption";
    const currentIsHeading = lineType !== "body" && lineType !== "caption";
    const previousStats = getLineVisualStats(previous, columnMetrics);
    const lineStats = getLineVisualStats(line, columnMetrics);
    const bodyLineCount = current.type === "body" ? current.lines.length : 0;
    const bodyPair = current.type === "body" && lineType === "body";
    const captionPair = current.type === "caption" && lineType === "body";
    const captionContinuation =
      captionPair &&
      !isBodyStartText(line.text) &&
      !isBodyLikeCaptionText(line.text) &&
      gap <= Math.max(avgLineHeight, lineHeight) * 1.6 &&
      lineStats.lineFillRatio < 0.92 &&
      Math.abs(Number(line.bbox.x || 0) - Number(current.lines[0] && current.lines[0].bbox && current.lines[0].bbox.x || 0)) <= Math.max(24, lineHeight * 4);
    const lineContinuesParagraph =
      bodyPair &&
      gap <= Math.max(avgLineHeight, lineHeight) * 1.5 &&
      previousStats.lineFillRatio >= 0.78 &&
      previousStats.lineEndGap <= previousStats.columnWidth * 0.22;
    const isSingleColumnZh = (line.layoutType === "single_column" || current.lines[0].layoutType === "single_column") &&
      (line.sourceLanguageHint === "zh" || current.lines[0].sourceLanguageHint === "zh");
    const strongGap = gap > Math.max(avgLineHeight, lineHeight) * (isSingleColumnZh ? 1.65 : 2.0);
    const shortSentenceEnd =
      bodyPair &&
      !isSingleColumnZh &&
      previousStats.lineFillRatio < 0.72 &&
      previousStats.lineEndGap > previousStats.columnWidth * 0.25 &&
      lineEndsSentenceStrict(previous.text);
    const strongIndentedParagraph =
      bodyPair &&
      bodyLineCount >= (isSingleColumnZh ? 1 : 3) &&
      lineEndsSentenceStrict(previous.text) &&
      lineStats.lineStartGap > Math.max(line.avgFontSize || columnMetrics.avgFontSize || lineHeight, 8) * 1.8;
    const chineseIndentedParagraph =
      bodyPair &&
      isSingleColumnZh &&
      bodyLineCount >= 1 &&
      lineStats.lineStartGap > Math.max(line.avgFontSize || columnMetrics.avgFontSize || lineHeight, 8) * 1.6 &&
      gap >= Math.max(avgLineHeight, lineHeight) * 0.55;
    const startsNewParagraph =
      (current.type === "caption" && !captionContinuation) ||
      (lineType === "caption" && current.type !== "caption") ||
      previousIsHeading ||
      currentIsHeading ||
      (!lineContinuesParagraph && (strongGap || shortSentenceEnd || strongIndentedParagraph || chineseIndentedParagraph)) ||
      (!isSingleColumnZh && bodyPair && current.lines.length >= 14 && lineEndsSentenceStrict(previous.text));

    if (startsNewParagraph) {
      paragraphs.push(current);
      current = { pageNumber: line.pageNumber, column: line.column || "single", type: lineType, lines: [line], items: line.items.slice() };
    } else {
      current.lines.push(line);
      current.items.push(...line.items);
      if (current.type === "body" && lineType !== "body") current.type = lineType;
    }
  });

  if (current) paragraphs.push(current);

  const expandedParagraphs = splitAndMergeParagraphs(paragraphs);

  return expandedParagraphs.map((paragraph, index) => {
    const sourceText = makeParagraphSourceText(paragraph.lines);
    const bbox = makeBBox(paragraph.items);
    const columns = [...new Set(paragraph.items.map((item) => item.column || "single"))];
    const ySpan = Math.max(...paragraph.items.map((item) => item.y + item.height)) - Math.min(...paragraph.items.map((item) => item.y));
    const avgLineHeight = paragraph.lines.reduce((sum, line) => sum + Math.max(line.bbox.height, line.avgFontSize || 0, 10), 0) / Math.max(1, paragraph.lines.length);
    const ratios = textSuspiciousScore(sourceText);
    const suspiciousReasons = [];
    if (sourceText.length > 3000) suspiciousReasons.push("too_long");
    if (ratios.garbageRatio > 0.02) suspiciousReasons.push("garbage_ratio");
    if (ratios.symbolRatio > 0.18) suspiciousReasons.push("symbol_ratio");
    if (ySpan > avgLineHeight * Math.max(8, paragraph.lines.length * 2.6)) suspiciousReasons.push("large_y_span");
    if (columns.length > 1) suspiciousReasons.push("multiple_columns");
    const segmentId = `p${paragraph.pageNumber}-${index + 1}`;
    const lineBoxes = paragraph.lines.map((line) => makeLineBoxFromLine(line, segmentId));
    const paragraphMetrics = getColumnMetrics(paragraph.lines);
    const firstLineStats = getLineVisualStats(paragraph.lines[0], paragraphMetrics);
    const lastLineStats = getLineVisualStats(paragraph.lines[paragraph.lines.length - 1], paragraphMetrics);
    return {
      id: segmentId,
      pageNumber: paragraph.pageNumber,
      column: paragraph.column || "single",
      layoutType: paragraph.lines[0] ? paragraph.lines[0].layoutType || "single_column" : "single_column",
      sourceLanguageHint: getPdfLanguageHint(sourceText),
      type: paragraph.type || getPdfLineType(paragraph.lines[0]) || "body",
      sourceText,
      previewText: makePreviewText(sourceText),
      lines: paragraph.lines.map((line) => ({
        pageNumber: line.pageNumber,
        x: line.bbox.x,
        y: line.bbox.y,
        width: line.bbox.width,
        height: line.bbox.height,
        fontSize: Number((line.avgFontSize || 0).toFixed(2)),
        sourceLineText: line.text,
        layoutType: line.layoutType || "single_column",
        sourceLanguageHint: line.sourceLanguageHint || getPdfLanguageHint(line.text || ""),
      })),
      lineBoxes,
      items: paragraph.items,
      bbox,
      suspicious: suspiciousReasons.length > 0,
      suspiciousReasons,
      firstLineStartGap: Number(firstLineStats.lineStartGap.toFixed(2)),
      lastLineEndGap: Number(lastLineStats.lineEndGap.toFixed(2)),
    };
  }).filter((paragraph) => paragraph.sourceText);
}

function paragraphsToSegments(paragraphs) {
  return paragraphs.map((paragraph, index) => ({
    id: paragraph.id || `seg-${index + 1}`,
    pageNumber: paragraph.pageNumber,
    column: paragraph.column || "single",
    layoutType: paragraph.layoutType || "single_column",
    sourceLanguageHint: paragraph.sourceLanguageHint || getPdfLanguageHint(paragraph.sourceText || ""),
    type: paragraph.type || "body",
    sourceText: paragraph.sourceText,
    previewText: paragraph.previewText || makePreviewText(paragraph.sourceText),
    translatedText: "",
    bbox: paragraph.bbox,
    lines: paragraph.lines || [],
    lineBoxes: paragraph.lineBoxes || [],
    items: paragraph.items || [],
    status: "pending",
    suspicious: Boolean(paragraph.suspicious),
    suspiciousReasons: paragraph.suspiciousReasons || [],
    firstLineStartGap: paragraph.firstLineStartGap,
    lastLineEndGap: paragraph.lastLineEndGap,
  }));
}

function getPageBounds(items) {
  const bbox = makeBBox(items);
  return {
    ...bbox,
    right: bbox.x + bbox.width,
    bottom: bbox.y + bbox.height,
  };
}

function filterHeaderFooterItems(items) {
  return items.filter((item) => !isMarginTextItem(item));
}

function isMarginTextItem(item) {
  if (!item) return false;
  const pageWidth = Number(item.pageWidth || 0);
  const pageHeight = Number(item.pageHeight || 0);
  const text = normalizeExtractedPdfText(item.text || "");
  if (!text) return true;
  const x = Number(item.x || 0);
  const width = Number(item.width || 0);
  if (/Downloaded from https?:\/\/onlinelibrary\.wiley\.com/i.test(text)) return true;
  if (pageWidth > 0 && (x > pageWidth * 0.98 || x + width > pageWidth * 1.08)) return true;
  if (/arxiv|astro-ph/i.test(text)) {
    return Number(item.x || 0) < pageWidth * 0.2;
  }
  if (/(^|\b)(email|doi)\b/i.test(text) && pageHeight > 0 && Number(item.y || 0) > pageHeight * 0.88) {
    return true;
  }
  const height = Number(item.height || 0);
  const fontSize = Number(item.fontSize || height || 0);
  const leftMargin = pageWidth > 0 && x < pageWidth * 0.08;
  const abnormalShape = height > Math.max(width * 1.8, fontSize * 1.4) || width < fontSize * 0.8;
  return Boolean(leftMargin && abnormalShape);
}

function detectPageColumns(items) {
  const filtered = filterHeaderFooterItems(items);
  if (filtered.length < 24) return [{ name: "single", items: filtered }];

  const bounds = getPageBounds(filtered);
  const pageWidth = Number(filtered[0] && filtered[0].pageWidth) || (bounds.x + bounds.width);
  const pageHeight = Number(filtered[0] && filtered[0].pageHeight) || (bounds.y + bounds.height);
  const preliminaryLines = mergeTextItemsIntoLines(filtered.map((item) => ({ ...item, column: "single" })));
  const pageLayout = detectPageLayout(preliminaryLines, pageWidth, pageHeight);
  if (pageLayout.layoutType === "single_column" && pageLayout.languageHint === "zh") {
    return [{ name: "single", layout: pageLayout, items: filtered.map((item) => ({ ...item, column: "single", layoutType: pageLayout.layoutType, sourceLanguageHint: pageLayout.languageHint })) }];
  }
  const singleItems = [];
  const leftItems = [];
  const rightItems = [];
  const middleItems = [];

  filtered.forEach((item) => {
    const x = Number(item.x || 0);
    const y = Number(item.y || 0);
    const width = Number(item.width || 0);
    const pageHeight = Number(item.pageHeight || 0);
    const center = x + width / 2;
    const firstPageTopMatter = Number(item.pageNumber || 0) === 1 && pageHeight > 0 && y < pageHeight * 0.58;
    if (firstPageTopMatter || width > pageWidth * 0.55) {
      singleItems.push({ ...item, column: "single", layoutType: pageLayout.layoutType, sourceLanguageHint: pageLayout.languageHint });
    } else if (center < pageWidth * 0.45) {
      leftItems.push({ ...item, column: "left", layoutType: pageLayout.layoutType, sourceLanguageHint: pageLayout.languageHint });
    } else if (center > pageWidth * 0.50) {
      rightItems.push({ ...item, column: "right", layoutType: pageLayout.layoutType, sourceLanguageHint: pageLayout.languageHint });
    } else {
      middleItems.push({ ...item, column: "single", layoutType: pageLayout.layoutType, sourceLanguageHint: pageLayout.languageHint });
    }
  });

  const narrowCount = leftItems.length + rightItems.length;
  const hasTwoColumns =
    narrowCount >= 20 &&
    leftItems.length > narrowCount * 0.25 &&
    rightItems.length > narrowCount * 0.25;

  if (!hasTwoColumns) {
    const singleLayout = { ...pageLayout, layoutType: "single_column", columnCount: 1, confidence: Math.max(pageLayout.confidence, 0.78) };
    return [{ name: "single", layout: singleLayout, items: filtered.map((item) => ({ ...item, column: "single", layoutType: singleLayout.layoutType, sourceLanguageHint: singleLayout.languageHint })) }];
  }

  // A legitimate inline tail can cross the conservative column-center threshold even though it
  // remains on the same baseline and is horizontally continuous with the preceding column item
  // (author citations and long terminal formula tokens are common examples).  Resolve only these
  // proven continuations before materializing the middle/single column; spatially isolated center
  // objects keep their existing authority.
  const unresolvedMiddleItems = [];
  middleItems.forEach((item) => {
    const itemLeft = Number(item.x || 0);
    const itemRight = itemLeft + Number(item.width || 0);
    const itemBaseline = Number(item.baselineTopY || item.y || 0);
    const itemFont = Math.max(1, Number(item.fontSize || item.height || 0));
    const candidates = [];
    leftItems.forEach((candidate) => {
      const candidateRight = Number(candidate.x || 0) + Number(candidate.width || 0);
      const baselineDelta = Math.abs(Number(candidate.baselineTopY || candidate.y || 0) - itemBaseline);
      const continuityLimit = Math.max(4, itemFont * 1.25, Number(candidate.fontSize || candidate.height || 0) * 1.25);
      const gap = itemLeft - candidateRight;
      if (baselineDelta <= Math.max(2, itemFont * 0.35) && gap >= -1 && gap <= continuityLimit) {
        candidates.push({ column: 'left', gap, baselineDelta });
      }
    });
    rightItems.forEach((candidate) => {
      const candidateLeft = Number(candidate.x || 0);
      const baselineDelta = Math.abs(Number(candidate.baselineTopY || candidate.y || 0) - itemBaseline);
      const continuityLimit = Math.max(4, itemFont * 1.25, Number(candidate.fontSize || candidate.height || 0) * 1.25);
      const gap = candidateLeft - itemRight;
      if (baselineDelta <= Math.max(2, itemFont * 0.35) && gap >= -1 && gap <= continuityLimit) {
        candidates.push({ column: 'right', gap, baselineDelta });
      }
    });
    candidates.sort((a, b) => (a.baselineDelta - b.baselineDelta) || (a.gap - b.gap));
    const owner = candidates[0] && candidates[0].column;
    if (owner === 'left') leftItems.push({ ...item, column: 'left' });
    else if (owner === 'right') rightItems.push({ ...item, column: 'right' });
    else unresolvedMiddleItems.push(item);
  });
  middleItems.splice(0, middleItems.length, ...unresolvedMiddleItems);

  const columns = [];
  const resolvedLayout = {
    ...pageLayout,
    layoutType: pageLayout.layoutType === "mixed" ? "mixed" : "double_column",
    columnCount: 2,
    confidence: Math.max(pageLayout.confidence || 0, 0.78),
  };
  singleItems.forEach((item) => {
    item.layoutType = resolvedLayout.layoutType;
    item.sourceLanguageHint = resolvedLayout.languageHint;
  });
  middleItems.forEach((item) => {
    item.layoutType = resolvedLayout.layoutType;
    item.sourceLanguageHint = resolvedLayout.languageHint;
  });
  leftItems.forEach((item) => {
    item.layoutType = resolvedLayout.layoutType;
    item.sourceLanguageHint = resolvedLayout.languageHint;
  });
  rightItems.forEach((item) => {
    item.layoutType = resolvedLayout.layoutType;
    item.sourceLanguageHint = resolvedLayout.languageHint;
  });
  const resolvedSingle = singleItems.concat(middleItems);
  if (resolvedSingle.length) columns.push({ name: "single", layout: resolvedLayout, items: resolvedSingle });
  if (leftItems.length) columns.push({ name: "left", layout: resolvedLayout, items: leftItems });
  if (rightItems.length) columns.push({ name: "right", layout: resolvedLayout, items: rightItems });
  return columns;
}

let currentPdfIgnoredNoiseLines = 0;
let currentPdfIgnoredPageNumberLines = 0;
let currentPdfIgnoredImageTextLines = 0;
let currentPdfIgnoredImageTextPreviews = [];
let currentPdfImageRegionsByPage = {};
let currentPdfCaptionRegionsByPage = {};
// Raw visual lines (post text-item-merge, pre-paragraph/segment classification), kept only so the
// 5A-4 caption visual-replacement audit can tell "this raw line falls inside a caption's own bbox
// but was never actually claimed by any sourceMaskBox" apart from "no segment's bbox reaches here at
// all" — the existing uncovered-line recovery pass only checks the latter (bbox containment with
// generous padding), which is exactly why a genuinely un-masked line sitting inside a caption
// segment's own bounding box was never caught before.
let currentPdfAllRawLinesByPage = {};
// Unmerged PDF.js text items are the geometry authority for scientific objects. A displayed
// equation is commonly materialized as independently positioned base glyphs, scripts, fraction
// parts and an equation number; merged visual lines cannot preserve every one of those boxes.
let currentPdfAllRawTextItemsByPage = {};
// Page-level formula protection is finalized from all source segments before export masking.
// It prevents a prose mask owned by one segment from erasing a scientific object owned by its
// neighbour; segment-local protection alone cannot enforce that document-level boundary.
let currentPdfFormulaProtectionByPage = {};
let currentPdfImageRegionsFinalizedBeforeLayoutPlan = false;
let currentPdfImageRegionCounterProofBeforeLayoutCount = 0;
let currentPdfImageRegionChangedAfterLayoutPlanCount = 0;
// 2D-4 instrumentation: proves whether the body-line-density counter-proof in
// inferImageRegionsForPage actually ran and what it did, instead of trusting that it did.
let currentPdfImageRegionBodyCounterProofAttemptCount = 0;
let currentPdfImageRegionBodyCounterProofHitCount = 0;
let currentPdfImageRegionBodyCounterProofShrinkCount = 0;
let currentPdfImageRegionBodyCounterProofDropCount = 0;
let currentPdfImageRegionBodyCounterProofSkippedReasons = [];
let currentPdfImageRegionBeforeAfterBoxesByPage = {};
// 2D-4 round 3: segment-level counter-proof pass (runs after segments exist, complementing the
// raw-line pass above which runs before segmentation and was missing this exact body run).
let currentPdfImageRegionSegmentCounterProofSegmentCandidateCount = 0;
let currentPdfImageRegionSegmentCounterProofLineBoxCandidateCount = 0;
let currentPdfImageRegionSegmentCounterProofCandidateSegmentIds = [];
let currentPdfImageRegionSegmentCounterProofRejectedByColumnCount = 0;
let currentPdfImageRegionSegmentCounterProofRejectedByNoOverlapCount = 0;
let currentPdfImageRegionSegmentCounterProofRejectedByTextPatternCount = 0;

function makeImageRegion(pageNumber, x, y, width, height, source, column = "") {
  return {
    pageNumber,
    x: Number(Math.max(0, x).toFixed(2)),
    y: Number(Math.max(0, y).toFixed(2)),
    width: Number(Math.max(0, width).toFixed(2)),
    height: Number(Math.max(0, height).toFixed(2)),
    source,
    column: String(column || ""),
  };
}

// Page-relative, not document-relative: a fixed point-size threshold would be wrong for a paper set
// in 8pt vs 11pt body text. Used only to judge whether a line inside a candidate image region "looks
// like ordinary paragraph text" for that page.
function computePageMedianLineFontSize(lines) {
  const sizes = (lines || [])
    .map((line) => Number(line && line.avgFontSize || 0))
    .filter((value) => value > 0)
    .sort((a, b) => a - b);
  if (!sizes.length) return 9;
  const mid = Math.floor(sizes.length / 2);
  return sizes.length % 2 ? sizes[mid] : (sizes[mid - 1] + sizes[mid]) / 2;
}

// Body-line density counter-proof (2D-4 target A): a caption-inferred image region is a guess
// ("there's probably a figure above this caption"), not a measurement. If the guessed area actually
// contains a run of several consecutive lines that look like ordinary wrapped paragraph text — wide
// enough to span most of the region's column width, page-typical font size, and made of real prose
// words rather than a sparse chart label or axis tick — that is direct evidence there is no image in
// that span, just body text the guess swallowed. Returns the proven-body [top, bottom] spans inside
// the region so the caller can carve them back out instead of overlapping real translatable content.
// A lone stray line never counts (could legitimately be in-image text); only a run of >=3 does.
function findBodyLikeLineSpansInRegion(lines, region) {
  const candidateLines = (lines || [])
    .filter((line) => line && line.bbox && Number(line.bbox.width || 0) > 0 && Number(line.bbox.height || 0) > 0)
    .filter((line) => bboxOverlapRatio(line.bbox, region) > 0.5)
    .filter((line) => !isCaptionMarkerText(line.text) && !isImageInternalTextLine(line.text))
    .sort((a, b) => Number(a.bbox.y || 0) - Number(b.bbox.y || 0));
  const debugLines = [];
  if (candidateLines.length < 3) {
    return { spans: [], candidateLineCount: candidateLines.length, bodyLikeLineCount: 0, debugLines, skipReason: 'fewer_than_3_candidate_lines' };
  }
  const pageMedianFontSize = computePageMedianLineFontSize(lines);
  const minBodyWidth = Number(region.width || 0) * 0.55;
  const fontLow = pageMedianFontSize * 0.7;
  const fontHigh = pageMedianFontSize * 1.3;
  const classifyLine = (line) => {
    const width = Number(line.bbox.width || 0);
    const fontSize = Number(line.avgFontSize || 0);
    const wordCount = (normalizeExtractedPdfText(line.text || "").match(/[A-Za-z一-鿿][A-Za-z一-鿿'-]*/g) || []).length;
    const reasons = [];
    if (width < minBodyWidth) reasons.push(`width_${width.toFixed(1)}_below_${minBodyWidth.toFixed(1)}`);
    if (fontSize < fontLow || fontSize > fontHigh) reasons.push(`fontSize_${fontSize.toFixed(1)}_outside_${fontLow.toFixed(1)}-${fontHigh.toFixed(1)}`);
    if (wordCount < 3) reasons.push(`wordCount_${wordCount}_below_3`);
    return { isBodyLike: reasons.length === 0, reasons };
  };
  const spans = [];
  let runStart = -1;
  let runEnd = -1;
  let runCount = 0;
  let prevBottom = null;
  let bodyLikeLineCount = 0;
  const flushRun = () => {
    if (runCount >= 3) spans.push([runStart, runEnd]);
    runStart = -1; runEnd = -1; runCount = 0;
  };
  candidateLines.forEach((line) => {
    const top = Number(line.bbox.y || 0);
    const bottom = top + Number(line.bbox.height || 0);
    const lineHeight = Math.max(1, Number(line.bbox.height || 0));
    const gapOk = prevBottom == null || (top - prevBottom) <= lineHeight * 1.8;
    const { isBodyLike, reasons } = classifyLine(line);
    if (isBodyLike) bodyLikeLineCount += 1;
    debugLines.push({
      bbox: { x: Number(line.bbox.x || 0), y: top, width: Number(line.bbox.width || 0), height: Number(line.bbox.height || 0) },
      column: String(line.column || 'single'),
      avgFontSize: Number(line.avgFontSize || 0),
      textPreview: String(line.text || '').slice(0, 60),
      isBodyLike,
      rejectReasons: reasons,
      gapOk,
    });
    if (isBodyLike && gapOk && runCount > 0) {
      runEnd = bottom;
      runCount += 1;
    } else {
      flushRun();
      if (isBodyLike) { runStart = top; runEnd = bottom; runCount = 1; }
    }
    prevBottom = bottom;
  });
  flushRun();
  return { spans, candidateLineCount: candidateLines.length, bodyLikeLineCount, debugLines, skipReason: '' };
}

// Subtracts proven-body spans from a candidate region's vertical extent, returning whatever free
// sub-intervals remain (sorted top-to-bottom). Generic interval math — no segmentId, no page/coord
// hardcoding: works the same for any region and any set of disproving spans.
function subtractSpansFromRange(rangeTop, rangeBottom, spans) {
  const sorted = (spans || []).slice().sort((a, b) => a[0] - b[0]);
  const result = [];
  let cursor = rangeTop;
  sorted.forEach(([spanTop, spanBottom]) => {
    const clippedTop = Math.max(spanTop, rangeTop);
    const clippedBottom = Math.min(spanBottom, rangeBottom);
    if (clippedBottom <= clippedTop) return;
    if (clippedTop > cursor) result.push([cursor, clippedTop]);
    cursor = Math.max(cursor, clippedBottom);
  });
  if (cursor < rangeBottom) result.push([cursor, rangeBottom]);
  return result;
}

function inferImageRegionsForPage(lines, pageItems) {
  const regions = [];
  const pageWidth = Number(pageItems && pageItems[0] && pageItems[0].pageWidth || 0);
  const pageHeight = Number(pageItems && pageItems[0] && pageItems[0].pageHeight || 0);
  if (!pageWidth || !pageHeight) return regions;

  const captionLines = (lines || []).filter((line) => isCaptionMarkerText(line.text));
  captionLines.forEach((line) => {
    const text = normalizeExtractedPdfText(line.text || "");
    if (!isCaptionMarkerText(text)) return;
    const column = line.column || "single";
    const captionX = Number(line.bbox.x || 0);
    const captionY = Number(line.bbox.y || 0);
    const captionWidth = Number(line.bbox.width || 0);
    const maxInferredHeight = Math.max(pageHeight * 0.18, Math.min(pageHeight * 0.28, 180));
    // Rule 4: this is a guess ("there's probably a figure above this caption"), not a measurement
    // — an unbounded fixed-height guess is exactly how an inferred image region ends up swallowing
    // real body text that happens to sit close above the caption. Cap the guess at the actual free
    // gap between the caption and the nearest other content line above it in the same column, and
    // skip inferring a region at all when that gap is too small to plausibly hold an image.
    const safetyGap = 6;
    const nearestContentBottomAbove = (lines || []).reduce((best, other) => {
      if (other === line || !other.bbox) return best;
      if (other.pageNumber !== line.pageNumber) return best;
      const otherColumn = other.column || "single";
      if (column !== "single" && otherColumn !== "single" && otherColumn !== column) return best;
      const otherBottom = Number(other.bbox.y || 0) + Number(other.bbox.height || 0);
      if (otherBottom > captionY - safetyGap) return best;
      return Math.max(best, otherBottom);
    }, 0);
    const inferredHeight = Math.min(maxInferredHeight, Math.max(0, captionY - safetyGap - nearestContentBottomAbove));
    if (inferredHeight < 18) return;
    let x = captionX;
    let width = captionWidth;
    if (column === "single" || captionWidth > pageWidth * 0.55) {
      x = pageWidth * 0.08;
      width = pageWidth * 0.84;
    } else if (column === "left") {
      x = pageWidth * 0.08;
      width = pageWidth * 0.42;
    } else if (column === "right") {
      x = pageWidth * 0.50;
      width = pageWidth * 0.42;
    }
    const y = Math.max(0, captionY - inferredHeight);
    // Counter-proof pass: the gap-capping above still only protects against content immediately
    // touching the caption — a same-column run of ordinary body paragraphs further up inside the
    // guessed span (exactly what an oversized/misjudged gap produces) slips past it untouched. Check
    // the guessed span itself for proven-body line runs and carve them back out before committing to
    // a region, instead of emitting one rectangle that overlaps real translatable text.
    const candidateRegion = { x, y, width, height: inferredHeight };
    const sameColumnLines = (lines || []).filter((other) => {
      if (other === line || !other.bbox) return false;
      if (other.pageNumber !== line.pageNumber) return false;
      const otherColumn = other.column || "single";
      return column === "single" || otherColumn === "single" || otherColumn === column;
    });
    currentPdfImageRegionBodyCounterProofAttemptCount += 1;
    const proof = findBodyLikeLineSpansInRegion(sameColumnLines, candidateRegion);
    const pageKey = String(line.pageNumber || 0);
    if (!currentPdfImageRegionBeforeAfterBoxesByPage[pageKey]) currentPdfImageRegionBeforeAfterBoxesByPage[pageKey] = [];
    const auditEntry = {
      level: 'line',
      pageNumber: Number(line.pageNumber || 0),
      column,
      captionTextPreview: text.slice(0, 60),
      beforeBox: { x: Number(x.toFixed(2)), y: Number(y.toFixed(2)), width: Number(width.toFixed(2)), height: Number(inferredHeight.toFixed(2)) },
      candidateLineCount: proof.candidateLineCount,
      bodyLikeLineCount: proof.bodyLikeLineCount,
      bodyLikeSpans: proof.spans,
      debugLines: proof.debugLines,
      afterBoxes: [],
      reason: '',
    };
    if (!proof.spans.length) {
      auditEntry.reason = proof.skipReason || 'no_body_like_run_found_kept_unchanged';
      currentPdfImageRegionBodyCounterProofSkippedReasons.push(auditEntry.reason);
      auditEntry.afterBoxes.push(auditEntry.beforeBox);
      currentPdfImageRegionBeforeAfterBoxesByPage[pageKey].push(auditEntry);
      regions.push(makeImageRegion(line.pageNumber, x, y, width, inferredHeight, "caption-inferred", column));
      return;
    }
    currentPdfImageRegionBodyCounterProofHitCount += 1;
    const freeSpans = subtractSpansFromRange(y, y + inferredHeight, proof.spans);
    let emittedAny = false;
    freeSpans.forEach(([spanTop, spanBottom]) => {
      const spanHeight = spanBottom - spanTop;
      if (spanHeight < 18) return;
      emittedAny = true;
      const afterBox = { x: Number(x.toFixed(2)), y: Number(spanTop.toFixed(2)), width: Number(width.toFixed(2)), height: Number(spanHeight.toFixed(2)) };
      auditEntry.afterBoxes.push(afterBox);
      regions.push(makeImageRegion(line.pageNumber, x, spanTop, width, spanHeight, "caption-inferred", column));
    });
    if (emittedAny) {
      currentPdfImageRegionBodyCounterProofShrinkCount += 1;
      auditEntry.reason = 'shrunk_by_body_line_density_counter_proof';
    } else {
      currentPdfImageRegionBodyCounterProofDropCount += 1;
      auditEntry.reason = 'dropped_no_remaining_interval_after_body_line_density_counter_proof';
    }
    currentPdfImageRegionBodyCounterProofSkippedReasons.push(auditEntry.reason);
    currentPdfImageRegionBeforeAfterBoxesByPage[pageKey].push(auditEntry);
  });

  const labelLines = captionLines.length
    ? (lines || []).filter((line) => isImageInternalTextLine(line.text))
    : [];
  labelLines.forEach((line) => {
    const pad = Math.max(12, Number(line.avgFontSize || 8) * 2);
    regions.push(makeImageRegion(
      line.pageNumber,
      Number(line.bbox.x || 0) - pad,
      Number(line.bbox.y || 0) - pad,
      Number(line.bbox.width || 0) + pad * 2,
      Number(line.bbox.height || 0) + pad * 2,
      "short-label-cluster",
      String(line.column || "single")
    ));
  });
  return regions;
}

// 2D-4 round 3: the raw-line pass above runs BEFORE segmentation exists, scanning individual
// extracted text lines. That turned out to systematically miss the exact body run that later shows
// up as bodyImageOverlapCount, because line-level >50%-contained matching is stricter than how the
// write loop actually measures overlap (which uses final segment-level boxes and merely-overlapping,
// not fully-contained, geometry). This pass runs AFTER segments exist and re-examines every
// caption-inferred region using the SAME body segments / line geometry the write loop will later
// see, with a relaxed overlap test, so the candidate pool here matches bodyImageOverlapCount's input
// instead of disagreeing with it. Mutates currentPdfImageRegionsByPage in place; never touches a
// non-"caption-inferred" (i.e. real/already-detected) region.
function isBodyLikeSegmentText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value) return false;
  if (isCaptionMarkerText(value) || isImageInternalTextLine(value)) return false;
  const wordCount = (value.match(/[A-Za-z一-鿿][A-Za-z一-鿿'-]*/g) || []).length;
  return wordCount >= 3;
}

function boxOverlapsRegionRelaxed(box, region) {
  if (!box || !region || !Number(box.width || 0) || !Number(box.height || 0)) return false;
  if (bboxOverlapRatio(box, region) > 0.02) return true;
  return bboxHorizontalOverlapRatio(box, region) > 0.35 && bboxCrossesRegionY(box, region);
}

function applyBodySegmentImageRegionCounterProof(segments, pipelineConfig) {
  if (!isPaperPdfConfig(pipelineConfig)) return;
  const minRealImageHeight = 18;
  Object.keys(currentPdfImageRegionsByPage).forEach((pageKey) => {
    const pageRegions = currentPdfImageRegionsByPage[pageKey] || [];
    const pageNumber = Number(pageKey);
    const nextRegions = [];
    pageRegions.forEach((region) => {
      if (String(region.source || "") !== "caption-inferred") {
        nextRegions.push(region);
        return;
      }
      const regionColumn = String(region.column || "single");
      const candidates = [];
      const segmentDecisions = [];
      let rejectedByColumn = 0;
      let rejectedByNoOverlap = 0;
      let rejectedByTextPattern = 0;
      (segments || [])
        .filter((segment) => segment && String(segment.type || "body") === "body" && Number(segment.pageNumber || 0) === pageNumber)
        .forEach((segment) => {
          const segmentId = String(segment.id || "");
          const decision = { segmentId, bbox: segment.bbox || null, lineBoxCount: Array.isArray(segment.lines) ? segment.lines.length : 0 };
          const segColumn = String(segment.column || "single");
          const columnOk = regionColumn === "single" || segColumn === "single" || segColumn === regionColumn;
          if (!columnOk) {
            rejectedByColumn += 1;
            segmentDecisions.push({ ...decision, included: false, reason: `rejected_by_column_segment_${segColumn}_region_${regionColumn}` });
            return;
          }
          const candidateBoxes = (Array.isArray(segment.lines) && segment.lines.length
            ? segment.lines.map((line) => ({ x: Number(line.x || 0), y: Number(line.y || 0), width: Number(line.width || 0), height: Number(line.height || 0) }))
            : (segment.bbox ? [segment.bbox] : []));
          const overlappingBoxes = candidateBoxes.filter((box) => boxOverlapsRegionRelaxed(box, region));
          if (!overlappingBoxes.length) {
            rejectedByNoOverlap += 1;
            const bestRatio = Math.max(0, ...candidateBoxes.map((box) => bboxOverlapRatio(box, region)));
            segmentDecisions.push({ ...decision, included: false, reason: 'rejected_by_no_overlap', bestOverlapRatio: Number(bestRatio.toFixed(4)) });
            return;
          }
          if (!isBodyLikeSegmentText(segment.sourceText || segment.previewText || "")) {
            rejectedByTextPattern += 1;
            segmentDecisions.push({ ...decision, included: false, reason: 'rejected_by_text_pattern' });
            return;
          }
          candidates.push({ segment, overlappingBoxes });
          segmentDecisions.push({ ...decision, included: true, reason: 'candidate_accepted', overlapBoxCount: overlappingBoxes.length });
        });
      currentPdfImageRegionSegmentCounterProofRejectedByColumnCount += rejectedByColumn;
      currentPdfImageRegionSegmentCounterProofRejectedByNoOverlapCount += rejectedByNoOverlap;
      currentPdfImageRegionSegmentCounterProofRejectedByTextPatternCount += rejectedByTextPattern;
      candidates.sort((a, b) => Number(a.segment.bbox && a.segment.bbox.y || 0) - Number(b.segment.bbox && b.segment.bbox.y || 0));
      const runs = [];
      let run = [];
      let prevBottom = null;
      const flushRun = () => {
        if (run.length >= 3) runs.push(run);
        run = [];
      };
      candidates.forEach((candidate) => {
        const top = Number(candidate.segment.bbox && candidate.segment.bbox.y || 0);
        const height = Number(candidate.segment.bbox && candidate.segment.bbox.height || 0);
        const bottom = top + height;
        const gapOk = prevBottom == null || (top - prevBottom) <= Math.max(height, 12) * 2.2;
        if (gapOk) {
          run.push(candidate);
        } else {
          flushRun();
          run.push(candidate);
        }
        prevBottom = bottom;
      });
      flushRun();
      const pageKeyDebug = String(pageNumber);
      if (!currentPdfImageRegionBeforeAfterBoxesByPage[pageKeyDebug]) currentPdfImageRegionBeforeAfterBoxesByPage[pageKeyDebug] = [];
      const auditEntry = {
        level: 'segment',
        pageNumber,
        column: regionColumn,
        beforeBox: { x: region.x, y: region.y, width: region.width, height: region.height },
        candidateSegmentIds: candidates.map((candidate) => String(candidate.segment.id || "")),
        candidateLineBoxCount: candidates.reduce((sum, candidate) => sum + candidate.overlappingBoxes.length, 0),
        bodyLikeRunCount: runs.length,
        rejectedByColumnCount: rejectedByColumn,
        rejectedByNoOverlapCount: rejectedByNoOverlap,
        rejectedByTextPatternCount: rejectedByTextPattern,
        segmentDecisions,
        afterBoxes: [],
        reason: '',
      };
      currentPdfImageRegionSegmentCounterProofSegmentCandidateCount += candidates.length;
      currentPdfImageRegionSegmentCounterProofLineBoxCandidateCount += auditEntry.candidateLineBoxCount;
      currentPdfImageRegionSegmentCounterProofCandidateSegmentIds.push(...auditEntry.candidateSegmentIds);
      if (!runs.length) {
        auditEntry.reason = candidates.length ? 'candidates_found_but_no_run_of_3' : 'no_body_segment_candidates';
        auditEntry.afterBoxes.push(auditEntry.beforeBox);
        currentPdfImageRegionBeforeAfterBoxesByPage[pageKeyDebug].push(auditEntry);
        nextRegions.push(region);
        return;
      }
      currentPdfImageRegionBodyCounterProofHitCount += 1;
      const provenSpans = runs.map((runCandidates) => {
        const tops = runCandidates.map((candidate) => Number(candidate.segment.bbox && candidate.segment.bbox.y || 0));
        const bottoms = runCandidates.map((candidate) => Number(candidate.segment.bbox && candidate.segment.bbox.y || 0) + Number(candidate.segment.bbox && candidate.segment.bbox.height || 0));
        return [Math.min(...tops), Math.max(...bottoms)];
      });
      const freeSpans = subtractSpansFromRange(Number(region.y || 0), Number(region.y || 0) + Number(region.height || 0), provenSpans);
      let emittedAny = false;
      freeSpans.forEach(([spanTop, spanBottom]) => {
        const spanHeight = spanBottom - spanTop;
        if (spanHeight < minRealImageHeight) return;
        emittedAny = true;
        const afterBox = { x: region.x, y: Number(spanTop.toFixed(2)), width: region.width, height: Number(spanHeight.toFixed(2)) };
        auditEntry.afterBoxes.push(afterBox);
        nextRegions.push(makeImageRegion(pageNumber, region.x, spanTop, region.width, spanHeight, "caption-inferred", regionColumn));
      });
      if (emittedAny) {
        currentPdfImageRegionBodyCounterProofShrinkCount += 1;
        auditEntry.reason = 'shrunk_by_segment_level_body_counter_proof';
      } else {
        currentPdfImageRegionBodyCounterProofDropCount += 1;
        auditEntry.reason = 'dropped_no_remaining_interval_after_segment_level_body_counter_proof';
      }
      currentPdfImageRegionBeforeAfterBoxesByPage[pageKeyDebug].push(auditEntry);
    });
    currentPdfImageRegionsByPage[pageKey] = nextRegions;
  });
}

function isInsideImageRegion(lineBox, imageRegions) {
  if (!lineBox || !Array.isArray(imageRegions) || !imageRegions.length) return false;
  const centerX = Number(lineBox.bbox ? lineBox.bbox.x + lineBox.bbox.width / 2 : lineBox.x + lineBox.width / 2);
  const centerY = Number(lineBox.bbox ? lineBox.bbox.y + lineBox.bbox.height / 2 : lineBox.y + lineBox.height / 2);
  return imageRegions.some((region) => (
    centerX >= region.x &&
    centerX <= region.x + region.width &&
    centerY >= region.y &&
    centerY <= region.y + region.height
  ));
}

function getOverlappingImageRegion(lineBox, imageRegions) {
  if (!lineBox || !Array.isArray(imageRegions) || !imageRegions.length) return null;
  const box = lineBox.bbox || lineBox;
  return imageRegions.find((region) => (
    bboxOverlapRatio(box, region) > 0.02 ||
    bboxCrossesRegionY(box, region) && bboxHorizontalOverlapRatio(box, region) > 0.45 ||
    isInsideImageRegion(lineBox, [region])
  )) || null;
}

function filterImageRegionLines(lines, imageRegions) {
  return (lines || []).filter((line) => {
    const text = normalizeExtractedPdfText(line.text || "");
    const imageRegion = getOverlappingImageRegion(line, imageRegions);
    if (!imageRegion) return true;
    if (isCaptionMarkerText(text)) return true;
    if (!isTrueImageInternalTextLine(line, imageRegion)) return true;
    line.type = "imageText";
    currentPdfIgnoredImageTextLines += 1;
    if (currentPdfIgnoredImageTextPreviews.length < 20) {
      currentPdfIgnoredImageTextPreviews.push(text.slice(0, 80));
    }
    return false;
  });
}



function isPaperCoreFunctionAllowed(config) {
  return Boolean(config && (config.mode === "paper_pdf" || config.mode === "legacy_simple_pdf"));
}
function isPaperPdfConfig(config) {
  return Boolean(config && config.mode === "paper_pdf");
}

function pageHasAastexSignal(lines, items) {
  const text = normalizeExtractedPdfText([
    ...(lines || []).map((line) => line.text || ""),
    ...(items || []).slice(0, 40).map((item) => item.text || ""),
  ].join(" "));
  return /Typeset using LATEX twocolumn style|AASTeX|arXiv:|Draft version/i.test(text);
}

function makeZone(type, bbox, reason) {
  return { type, bbox: bbox || null, reason: reason || "", segmentIds: [] };
}

function detectPaperPageZones(pageInfo, lines, imageRegions, config) {
  if (!isPaperPdfConfig(config)) return [];
  const pageWidth = Number(pageInfo && pageInfo.pageWidth || 0);
  const pageHeight = Number(pageInfo && pageInfo.pageHeight || 0);
  const zones = [];
  const hasAastexHeader = pageHasAastexSignal(lines, []);
  if (pageWidth && pageHeight) {
    zones.push(makeZone("footerZone", { x: 0, y: pageHeight * 0.92, width: pageWidth, height: pageHeight * 0.08 }, "page_edge"));
    zones.push(makeZone("marginZone", { x: 0, y: 0, width: pageWidth * 0.06, height: pageHeight }, "page_margin"));
    if (Number(pageInfo.pageNumber || 0) === 1) {
      zones.push(makeZone("fullWidthTopZone", { x: 0, y: 0, width: pageWidth, height: pageHeight * 0.34 }, "first_page_top"));
      zones.push(makeZone("titleZone", { x: 0, y: 0, width: pageWidth, height: pageHeight * 0.22 }, "first_page_title"));
      zones.push(makeZone("abstractZone", { x: 0, y: pageHeight * 0.16, width: pageWidth, height: pageHeight * 0.22 }, "first_page_abstract"));
    }
    zones.push(makeZone("twoColumnBodyZone", { x: pageWidth * 0.06, y: pageHeight * 0.08, width: pageWidth * 0.88, height: pageHeight * 0.82 }, hasAastexHeader ? "aastex_twocolumn" : "paper_twocolumn"));
  }
  (imageRegions || []).forEach((region) => {
    zones.push(makeZone("figureZone", { x: region.x, y: region.y, width: region.width, height: region.height }, region.source || "image_region"));
  });
  const captionBoxes = (lines || []).filter((line) => isCaptionMarkerText(line.text)).map((line) => line.bbox).filter(Boolean);
  captionBoxes.forEach((bbox) => zones.push(makeZone("captionZone", bbox, "caption_marker")));
  if ((lines || []).some((line) => isReferencesHeadingText(line.text))) {
    zones.push(makeZone("referenceZone", null, "references_heading"));
  }
  if (hasAastexHeader) {
    zones.push(makeZone("sideMarkZone", null, "aastex_or_arxiv_signal"));
  }
  return zones;
}

function bboxCenter(box) {
  return {
    x: Number(box && box.x || 0) + Number(box && box.width || 0) / 2,
    y: Number(box && box.y || 0) + Number(box && box.height || 0) / 2,
  };
}

function bboxIntersects(a, b) {
  if (!a || !b) return false;
  return Number(a.x || 0) < Number(b.x || 0) + Number(b.width || 0) &&
    Number(a.x || 0) + Number(a.width || 0) > Number(b.x || 0) &&
    Number(a.y || 0) < Number(b.y || 0) + Number(b.height || 0) &&
    Number(a.y || 0) + Number(a.height || 0) > Number(b.y || 0);
}

function bboxOverlapArea(a, b) {
  if (!bboxIntersects(a, b)) return 0;
  const left = Math.max(Number(a.x || 0), Number(b.x || 0));
  const top = Math.max(Number(a.y || 0), Number(b.y || 0));
  const right = Math.min(Number(a.x || 0) + Number(a.width || 0), Number(b.x || 0) + Number(b.width || 0));
  const bottom = Math.min(Number(a.y || 0) + Number(a.height || 0), Number(b.y || 0) + Number(b.height || 0));
  return Math.max(0, right - left) * Math.max(0, bottom - top);
}

function bboxOverlapRatio(a, b) {
  const area = Math.max(1, Number(a && a.width || 0) * Number(a && a.height || 0));
  return bboxOverlapArea(a, b) / area;
}

function assignSegmentZone(segment, pageZones) {
  if (!segment || !Array.isArray(pageZones)) return "";
  const type = String(segment.type || "body");
  if (type === "reference") return "referenceZone";
  if (type === "caption") return "captionZone";
  if (["header", "footer", "pageNumber", "licenseText", "margin", "noise", "watermark"].includes(type)) return `${type}Zone`;
  if (["title", "author", "affiliation", "abstract-title"].includes(type)) return "titleZone";
  if (type === "abstract") return "abstractZone";
  if (type === "keywords") return "keywordsZone";
  const center = bboxCenter(segment.bbox);
  const matching = pageZones.find((zone) => zone.bbox &&
    center.x >= zone.bbox.x && center.x <= zone.bbox.x + zone.bbox.width &&
    center.y >= zone.bbox.y && center.y <= zone.bbox.y + zone.bbox.height);
  return matching ? matching.type : "twoColumnBodyZone";
}

function detectCaptionSegments(segments, imageRegions) {
  return (segments || []).filter((segment) => segment.type === "caption" || isCaptionMarkerText(segment.sourceText || "")).map((segment) => segment.id).filter(Boolean);
}

function detectImageRegionsForPaperPage(page, lines, items, config) {
  if (!isPaperPdfConfig(config)) return [];
  return inferImageRegionsForPage(lines, items);
}

function avoidImageRegionsForBodySegments(segment, imageRegions) {
  if (!segment || segment.type !== "body" || !Array.isArray(imageRegions) || !imageRegions.length) return segment;
  const overlap = imageRegions.some((region) => bboxIntersects(segment.bbox, region));
  return overlap ? { ...segment, imageRegionOverlap: true, warnings: [...(segment.warnings || []), "body_image_region_overlap"] } : segment;
}

function getSegmentLineText(line) {
  return normalizeExtractedPdfText(line && (line.sourceLineText || line.text) || "");
}

function makeBBoxFromLineBoxes(lineBoxes) {
  if (!lineBoxes || !lineBoxes.length) return { x: 0, y: 0, width: 0, height: 0 };
  const left = Math.min(...lineBoxes.map((line) => Number(line.x || 0)));
  const top = Math.min(...lineBoxes.map((line) => Number(line.y || 0)));
  const right = Math.max(...lineBoxes.map((line) => Number(line.x || 0) + Number(line.width || 0)));
  const bottom = Math.max(...lineBoxes.map((line) => Number(line.y || 0) + Number(line.height || 0)));
  return {
    x: Number(left.toFixed(2)),
    y: Number(top.toFixed(2)),
    width: Number(Math.max(0, right - left).toFixed(2)),
    height: Number(Math.max(0, bottom - top).toFixed(2)),
  };
}

function makeSegmentFromParts(base, lineIndexes, type, column) {
  const lines = lineIndexes.map((index) => base.lines[index]).filter(Boolean);
  const lineBoxes = lineIndexes.map((index) => base.lineBoxes[index]).filter(Boolean).map((line) => ({ ...line, column: column || base.column || "single" }));
  const sourceText = makeParagraphSourceText(lines.map((line) => ({ text: getSegmentLineText(line) })));
  return {
    ...base,
    id: "",
    pageNumber: base.pageNumber,
    column: column || base.column || "single",
    type,
    sourceText,
    previewText: makePreviewText(sourceText),
    lines,
    lineBoxes,
    bbox: makeBBoxFromLineBoxes(lineBoxes),
    items: [],
  };
}

function splitTopMatterSegment(segment) {
  if (!segment || segment.pageNumber !== 1 || segment.column !== "single") return [segment];
  if ((segment.sourceLanguageHint || getPdfLanguageHint(segment.sourceText || "")) === "zh") {
    const firstLineText = getSegmentLineText(segment.lines && segment.lines[0]);
    if ((segment.lines || []).length > 1 && firstLineText && firstLineText.length <= 22) {
      return [
        makeSegmentFromParts(segment, [0], "title", "single"),
        makeSegmentFromParts(segment, segment.lines.slice(1).map((_, index) => index + 1), "body", "single"),
      ].filter((part) => part.sourceText);
    }
    return [segment];
  }
  if (["abstract-title", "abstract", "keywords"].includes(segment.type)) return [segment];
  if (segment.bbox && Number(segment.bbox.y || 0) > 315) return [segment];
  const lines = segment.lines || [];
  if (lines.length < 2) {
    const onlyText = getSegmentLineText(lines[0]) || normalizeExtractedPdfText(segment.sourceText || "");
    if (/draft version|typeset using|aastex|twocolumn/i.test(onlyText)) {
      return [{ ...segment, type: "header", column: "single" }];
    }
    return [segment];
  }
  const buckets = { header: [], title: [], author: [], affiliation: [], funding: [], correspondence: [], receivedDate: [] };
  lines.forEach((line, index) => {
    const text = getSegmentLineText(line);
    if (/draft version|typeset using|aastex|twocolumn/i.test(text)) buckets.header.push(index);
    else if (/^Funding\s*:/i.test(text)) buckets.funding.push(index);
    else if (/^(Correspondence|Corresponding author)\s*:/i.test(text) || /\bE-?mail\s*:/i.test(text)) buckets.correspondence.push(index);
    else if (/^(Received|Revised|Accepted|Published)\b/i.test(text)) buckets.receivedDate.push(index);
    else if (/department|university|usa|institute|observator|laborator|email/i.test(text)) buckets.affiliation.push(index);
    else if (buckets.title.length && text.length < 140 && !/[.!?]$/.test(text)) buckets.author.push(index);
    else buckets.title.push(index);
  });
  const parts = [];
  if (buckets.header.length) parts.push(makeSegmentFromParts(segment, buckets.header, "header", "single"));
  if (buckets.title.length) parts.push(makeSegmentFromParts(segment, buckets.title, "title", "single"));
  if (buckets.author.length) parts.push(makeSegmentFromParts(segment, buckets.author, "author", "single"));
  if (buckets.affiliation.length) parts.push(makeSegmentFromParts(segment, buckets.affiliation, "affiliation", "single"));
  if (buckets.correspondence.length) parts.push(makeSegmentFromParts(segment, buckets.correspondence, "correspondence", "single"));
  if (buckets.receivedDate.length) parts.push(makeSegmentFromParts(segment, buckets.receivedDate, "receivedDate", "single"));
  if (buckets.funding.length) parts.push(makeSegmentFromParts(segment, buckets.funding, "funding", "single"));
  return parts.length ? parts : [segment];
}

function getSegmentFirstLineBox(segment) {
  return segment && segment.lineBoxes && segment.lineBoxes[0] || null;
}

function getSegmentEffectivePageNumber(seg) {
  const firstLB = getSegmentFirstLineBox(seg);
  if (firstLB && Number(firstLB.pageNumber || 0)) return Number(firstLB.pageNumber);
  const lines = Array.isArray(seg && seg.lines) ? seg.lines : [];
  if (lines.length > 0 && Number(lines[0] && lines[0].pageNumber || 0)) return Number(lines[0].pageNumber);
  return Number(seg && seg.pageNumber || 0);
}

// resolveSegmentSourcePage — authoritative page ownership resolver.
// Priority (strongest → weakest):
//   1. lineBoxes[*].pageNumber — actual PDF glyph positions, never wrong
//   2. lines[*].pageNumber     — alternative structure, same reliability
//   3. segment.pageNumber      — extraction tag, can be mis-attributed (fallback only)
// Returns { status, sourcePage, resolvedBy, evidencePages, reason }.
// status='ok': single unambiguous page found.
// status='conflict': lineBox / line data spans multiple pages (cross-page segment — should be split).
// status='missing': no positive page evidence found.
function resolveSegmentSourcePage(seg) {
  if (!seg) return { status: 'missing', sourcePage: 0, resolvedBy: 'none', evidencePages: {}, reason: 'null_segment' };
  const segmentPage = Number(seg.pageNumber || 0);
  const lineBoxes = Array.isArray(seg.lineBoxes) ? seg.lineBoxes : [];
  const lineBoxPages = [...new Set(lineBoxes.map((lb) => Number(lb && lb.pageNumber || 0)).filter((p) => p > 0))];
  const lines = Array.isArray(seg.lines) ? seg.lines : [];
  const linePages = [...new Set(lines.map((l) => Number(l && l.pageNumber || 0)).filter((p) => p > 0))];
  const firstLineBoxPage = lineBoxes.length > 0 ? Number(lineBoxes[0] && lineBoxes[0].pageNumber || 0) : 0;
  const evidencePages = { segmentPage, lineBoxPages, linePages, firstLineBoxPage };
  // Priority 1: lineBoxes
  if (lineBoxPages.length === 1) {
    return { status: 'ok', sourcePage: lineBoxPages[0], resolvedBy: 'lineBoxes', evidencePages, reason: `lineBoxes_all_page_${lineBoxPages[0]}` };
  }
  if (lineBoxPages.length > 1) {
    return { status: 'conflict', sourcePage: lineBoxPages[0], resolvedBy: 'lineBoxes_conflict', evidencePages, reason: `lineBoxes_span_pages_${lineBoxPages.join('_')}` };
  }
  // Priority 2: lines[]
  if (linePages.length === 1) {
    return { status: 'ok', sourcePage: linePages[0], resolvedBy: 'lines', evidencePages, reason: `lines_all_page_${linePages[0]}` };
  }
  if (linePages.length > 1) {
    return { status: 'conflict', sourcePage: linePages[0], resolvedBy: 'lines_conflict', evidencePages, reason: `lines_span_pages_${linePages.join('_')}` };
  }
  // Fallback: segment.pageNumber
  if (segmentPage > 0) {
    return { status: 'ok', sourcePage: segmentPage, resolvedBy: 'segment_pageNumber_fallback', evidencePages, reason: 'no_lineBox_or_line_data' };
  }
  return { status: 'missing', sourcePage: 0, resolvedBy: 'none', evidencePages, reason: 'no_page_evidence' };
}

// Paper Source Page Finalization Contract. Source merges may only use page ownership proven by
// real line / lineBox geometry; historical segment.pageNumber tags are not merge authority.
function finalizePaperSourcePageAuthority(segment) {
  if (!segment) return { status: 'missing', sourcePage: 0, reason: 'null_segment', evidencePages: {} };
  const lineBoxes = Array.isArray(segment.lineBoxes) ? segment.lineBoxes : [];
  const lines = Array.isArray(segment.lines) ? segment.lines : [];
  const lineBoxPages = [...new Set(lineBoxes.map((line) => Number(line && line.pageNumber || 0)).filter((page) => page > 0))];
  const linePages = [...new Set(lines.map((line) => Number(line && line.pageNumber || 0)).filter((page) => page > 0))];
  const realPages = [...new Set([...lineBoxPages, ...linePages])];
  const evidencePages = { segmentPage: Number(segment.pageNumber || 0), lineBoxPages, linePages, realPages };
  if (!realPages.length) return { status: 'missing', sourcePage: 0, reason: 'real_source_page_missing', evidencePages };
  if (realPages.length !== 1) return { status: 'conflict', sourcePage: 0, reason: `real_source_pages_${realPages.join('_')}`, evidencePages };
  const sourcePage = realPages[0];
  segment.pageNumber = sourcePage;
  segment.sourcePageFinalized = true;
  segment.sourcePageFinalizedBy = 'line_lineBox_geometry';
  return { status: 'ok', sourcePage, reason: `real_source_page_${sourcePage}`, evidencePages };
}

function finalizePaperSourceMergeContract(base, incoming) {
  const baseAuthority = finalizePaperSourcePageAuthority(base);
  const incomingAuthority = finalizePaperSourcePageAuthority(incoming);
  if (baseAuthority.status !== 'ok' || incomingAuthority.status !== 'ok') {
    return { status: 'rejected', reason: 'source_page_authority_not_unique', sourcePage: 0, baseAuthority, incomingAuthority };
  }
  if (Number(baseAuthority.sourcePage) !== Number(incomingAuthority.sourcePage)) {
    return { status: 'rejected', reason: 'source_page_authority_mismatch', sourcePage: 0, baseAuthority, incomingAuthority };
  }
  return { status: 'ok', reason: 'source_page_authority_finalized', sourcePage: Number(baseAuthority.sourcePage), baseAuthority, incomingAuthority };
}

function getSegmentLastLineBox(segment) {
  const boxes = segment && segment.lineBoxes || [];
  return boxes.length ? boxes[boxes.length - 1] : null;
}

// Paragraph Boundary Finalization must use source-line geometry, not the union bbox of a
// multi-line segment. A real paragraph's indented first line is otherwise hidden when its
// following lines extend back to the column edge and determine segment.bbox.x.
function resolvePaperParagraphBoundaryEvidence(previous, current, englishBodyFontSize) {
  if (!previous || !current) return { shouldBreak: false, reason: '', source: 'missing_segment' };
  const previousSourceParagraphId = String(previous.sourceParagraphId || previous.sourceParagraphIdentity || '');
  const currentSourceParagraphId = String(current.sourceParagraphId || current.sourceParagraphIdentity || '');
  if (previousSourceParagraphId && currentSourceParagraphId) {
    return previousSourceParagraphId !== currentSourceParagraphId
      ? { shouldBreak: true, reason: 'source_paragraph_identity', source: 'explicit_source_identity', previousSourceParagraphId, currentSourceParagraphId }
      : { shouldBreak: false, reason: '', source: 'explicit_source_identity', previousSourceParagraphId, currentSourceParagraphId };
  }

  const previousText = normalizeExtractedPdfText(previous.sourceText || '');
  const previousEnded = /[.!?。！？]$/.test(previousText.trim());
  if (!previousEnded) return { shouldBreak: false, reason: '', source: 'line_geometry', previousEnded: false };

  const font = Math.max(8, Number(englishBodyFontSize || 9));
  const previousBox = previous.bbox || {};
  const currentBox = current.bbox || {};
  const previousLineBoxes = Array.isArray(previous.lineBoxes) ? previous.lineBoxes.filter(Boolean) : [];
  const currentLineBoxes = Array.isArray(current.lineBoxes) ? current.lineBoxes.filter(Boolean) : [];
  const currentFirstLine = getSegmentFirstLineBox(current);
  const leftCandidates = [
    Number(previousBox.x),
    Number(currentBox.x),
    ...previousLineBoxes.map((line) => Number(line.x)),
    ...currentLineBoxes.map((line) => Number(line.x)),
  ].filter(Number.isFinite);
  const columnLeftX = leftCandidates.length ? Math.min(...leftCandidates) : 0;
  const firstLineX = currentFirstLine && Number.isFinite(Number(currentFirstLine.x))
    ? Number(currentFirstLine.x)
    : Number(currentBox.x || 0);
  const firstLineIndent = firstLineX - columnLeftX;
  const indentThreshold = Math.max(8, font * 0.85);
  const shouldBreak = firstLineIndent > indentThreshold;
  return {
    shouldBreak,
    reason: shouldBreak ? 'first_line_indent_after_sentence' : '',
    source: currentFirstLine ? 'line_box_geometry' : 'segment_bbox_fallback',
    previousEnded: true,
    firstLineX: Number(firstLineX.toFixed(2)),
    columnLeftX: Number(columnLeftX.toFixed(2)),
    firstLineIndent: Number(firstLineIndent.toFixed(2)),
    indentThreshold: Number(indentThreshold.toFixed(2)),
  };
}

function resolvePaperParagraphOverlapContinuationEvidence(previous, current, englishBodyFontSize) {
  if (!previous || !current) return { isContinuation: false, source: 'missing_segment' };
  const previousSourceParagraphId = String(previous.sourceParagraphId || previous.sourceParagraphIdentity || '');
  const currentSourceParagraphId = String(current.sourceParagraphId || current.sourceParagraphIdentity || '');
  if (previousSourceParagraphId && currentSourceParagraphId && previousSourceParagraphId !== currentSourceParagraphId) {
    return {
      isContinuation: false,
      source: 'distinct_source_paragraph_identity',
      previousSourceParagraphId,
      currentSourceParagraphId,
    };
  }
  const previousFirstLine = getSegmentFirstLineBox(previous);
  const currentFirstLine = getSegmentFirstLineBox(current);
  if (!previousFirstLine || !currentFirstLine) return { isContinuation: false, source: 'missing_line_box' };
  if (Number(previousFirstLine.pageNumber || previous.pageNumber || 0) !== Number(currentFirstLine.pageNumber || current.pageNumber || 0)) {
    return { isContinuation: false, source: 'page_mismatch' };
  }
  if (String(previous.column || 'single') !== String(current.column || 'single')) return { isContinuation: false, source: 'column_mismatch' };
  const previousText = normalizeExtractedPdfText(previous.sourceText || '');
  const previousSentenceEnded = /[.!?。！？]$/.test(previousText.trim());
  const previousBox = previous.bbox || {};
  const currentBox = current.bbox || {};
  const font = Math.max(8, Number(englishBodyFontSize || 9));
  const firstLineAdvance = Number(currentFirstLine.y || 0) - Number(previousFirstLine.y || 0);
  const unionVerticalGap = Number(currentBox.y || 0) - (Number(previousBox.y || 0) + Number(previousBox.height || 0));
  const horizontalOverlap = paperBoxHorizontalOverlapRatio(previousBox, currentBox);
  const currentStartsInsidePreviousUnionBox = Number(currentFirstLine.y || 0) < Number(previousBox.y || 0) + Number(previousBox.height || 0);
  const maximumForwardAdvance = Math.max(font * 3, Number(previousBox.height || 0));
  const isContinuation = unionVerticalGap < 0
    && firstLineAdvance > 0
    && firstLineAdvance <= maximumForwardAdvance
    && horizontalOverlap >= 0.5
    && currentStartsInsidePreviousUnionBox;
  return {
    isContinuation,
    source: 'line_box_forward_progress',
    firstLineAdvance: Number(firstLineAdvance.toFixed(2)),
    maximumForwardAdvance: Number(maximumForwardAdvance.toFixed(2)),
    unionVerticalGap: Number(unionVerticalGap.toFixed(2)),
    horizontalOverlap: Number(horizontalOverlap.toFixed(3)),
    currentStartsInsidePreviousUnionBox,
    previousSentenceEnded,
    previousSourceParagraphId,
    currentSourceParagraphId,
  };
}

function resolvePaperParagraphBoundaryArbitration(previous, current, englishBodyFontSize, verticalGap, negativeOverlapFloor) {
  const overlapContinuationEvidence = resolvePaperParagraphOverlapContinuationEvidence(previous, current, englishBodyFontSize);
  const strongNegativeOverlapContinuation = Number(verticalGap) < Number(negativeOverlapFloor)
    && overlapContinuationEvidence.isContinuation;
  const boundaryEvidence = strongNegativeOverlapContinuation
    ? { shouldBreak: false, reason: '', source: 'strong_negative_overlap_continuation' }
    : resolvePaperParagraphBoundaryEvidence(previous, current, englishBodyFontSize);
  return {
    overlapContinuationEvidence,
    strongNegativeOverlapContinuation,
    boundaryEvidence,
  };
}

function getSegmentVerticalGap(previous, segment) {
  const prevLast = getSegmentLastLineBox(previous);
  const currFirst = getSegmentFirstLineBox(segment);
  if (!prevLast || !currFirst) return Number.POSITIVE_INFINITY;
  return Number(currFirst.y || 0) - (Number(prevLast.y || 0) + Number(prevLast.height || 0));
}

function canMergeTitleContinuation(previous, segment) {
  if (!previous || !segment) return false;
  if (Number(previous.pageNumber || 0) !== 1 || Number(segment.pageNumber || 0) !== 1) return false;
  if (previous.column !== "single" || segment.column !== "single") return false;
  if (!["title", "heading", "body"].includes(previous.type) || !["title", "heading", "body"].includes(segment.type)) return false;
  const prevText = normalizeExtractedPdfText(previous.sourceText || "");
  const text = normalizeExtractedPdfText(segment.sourceText || "");
  if (!prevText || !text || /^(Will\s+|Funding\s*:|Keywords?\s*:|ABSTRACT$|Received\b|Revised\b|Accepted\b|Correspondence\b)/i.test(text)) return false;
  if (isLikelyAuthorLineText(text) || /\b(Department|University|Institute|Observatory|Laboratory|College|School|USA|Email)\b/i.test(text)) return false;
  const prevBox = previous.bbox || {};
  const currBox = segment.bbox || {};
  if (Number(prevBox.y || 0) > 170 || Number(currBox.y || 0) > 190) return false;
  if (/[.!?]$/.test(prevText) || /[.!?]$/.test(text)) return false;
  const gap = getSegmentVerticalGap(previous, segment);
  const lineHeight = Math.max(Number(getSegmentLastLineBox(previous) && getSegmentLastLineBox(previous).height || 0), Number(getSegmentFirstLineBox(segment) && getSegmentFirstLineBox(segment).height || 0), 8);
  const xDelta = Math.abs(Number(currBox.x || 0) - Number(prevBox.x || 0));
  return gap >= -2 && gap <= lineHeight * 2.4 && xDelta <= 18 && prevText.length + text.length <= 160;
}

function looksLikeSectionHeadingContinuation(previous, segment) {
  const prevText = normalizeExtractedPdfText(previous && previous.sourceText || "");
  const text = normalizeExtractedPdfText(segment && segment.sourceText || "");
  if (!prevText || !text || text.length > 90) return false;
  if (/[.!?]$/.test(text)) return false;
  if (/^(Funding\s*:|Keywords?\s*:|ABSTRACT$|References$|Endnotes?$)/i.test(text)) return false;
  return /^(?:\d+\s*)?\|\s+[A-Z]|^\d+\s*(?:[|.]|:)\s+[A-Z]/.test(prevText) ||
    (previous && previous.type === "heading" && /^[A-Z][A-Za-z0-9,:'’` -]{2,}$/.test(text));
}

function canMergeSectionHeadingContinuation(previous, segment) {
  if (!previous || !segment) return false;
  if (Number(previous.pageNumber || 0) !== Number(segment.pageNumber || 0)) return false;
  if (String(previous.column || "single") !== String(segment.column || "single")) return false;
  if (!looksLikeSectionHeadingContinuation(previous, segment)) return false;
  const gap = getSegmentVerticalGap(previous, segment);
  const lineHeight = Math.max(Number(getSegmentLastLineBox(previous) && getSegmentLastLineBox(previous).height || 0), Number(getSegmentFirstLineBox(segment) && getSegmentFirstLineBox(segment).height || 0), 8);
  const xDelta = Math.abs(Number(segment.bbox && segment.bbox.x || 0) - Number(previous.bbox && previous.bbox.x || 0));
  return gap >= -2 && gap <= lineHeight * 2.2 && xDelta <= 20;
}

function applyHeadingContinuationMerges(segments) {
  const output = [];
  (segments || []).forEach((segment) => {
    const previous = output[output.length - 1];
    if (canMergeTitleContinuation(previous, segment)) {
      if (mergeSegments(previous, segment, "title", "single")) {
        previous.mergeReason = previous.mergeReason || "title_continuation";
        return;
      }
    }
    if (canMergeSectionHeadingContinuation(previous, segment)) {
      if (mergeSegments(previous, segment, "heading", previous.column || segment.column || "single")) {
        previous.mergeReason = previous.mergeReason || "heading_continuation";
        return;
      }
    }
    output.push(segment);
  });
  return output;
}

function getSegmentText(segment) {
  return normalizeExtractedPdfText(segment && segment.sourceText || "");
}

function startsWithLowercaseWord(text) {
  return /^[a-z]/.test(normalizeExtractedPdfText(text || ""));
}

function startsWithNumericContinuation(text) {
  return /^(?:\d+(?:\.\d+)+\.?|\d+\.\s+(?:We|we|as|which|and|the|The)|\d+(?:\.\d+)?[,)]\s+(?:which|and|as|the)|[≈~]?\d+(?:\.\d+)?[,)]?\s+(?:which|and|as|the))/i.test(normalizeExtractedPdfText(text || ""));
}

function endsWithHyphenatedWord(text) {
  return /[A-Za-z]{2,}-$/.test(normalizeExtractedPdfText(text || ""));
}

function isSentenceLikeBodyText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value) return false;
  if (/^(?:Figure|Table)\s+\d+/i.test(value)) return false;
  return /^(?:The|These|This|We|Our|Assuming|Simulations|Results|Despite|However|In|For|As|Because|Since|To|With|A|An)\b/i.test(value) ||
    /\b(is|are|was|were|be|been|being|has|have|had|can|could|should|would|will|may|might|must|suggest|suggests|provide|provides|adopt|adopts|implies|make|makes|use|using|remain|represents)\b/i.test(value);
}

function getContinuationMergeReason(segment, previous, next) {
  const text = getSegmentText(segment);
  const previousText = getSegmentText(previous);
  if (!text) return "";
  if (endsWithHyphenatedWord(previousText) || startsWithLowercaseWord(text)) return "hyphen_continuation";
  if (startsWithNumericContinuation(text)) return "numeric_continuation";
  if (segment.type === "heading" && isSentenceLikeBodyText(text)) return "body_context_continuation";
  if (previous && next && previous.type === "body" && next.type === "body" && !isSectionHeadingText(text)) return "body_context_continuation";
  return "";
}

function applyBodyContinuationMerges(segments) {
  const output = [];
  (segments || []).forEach((segment, index) => {
    const previous = output[output.length - 1];
    const next = (segments || [])[index + 1];
    const reason = getContinuationMergeReason(segment, previous, next);
    if (previous && previous.type === "body" && reason && (segment.type === "heading" || segment.type === "body")) {
      const wasHeading = segment.type === "heading";
      if (mergeSegments(previous, { ...segment, type: "body" }, "body", previous.column || segment.column)) {
        previous.mergeReason = reason;
        previous.classificationReason = wasHeading ? "body_continuation_demoted_from_heading" : (previous.classificationReason || "body_continuation_merged");
        previous.headingDemotedToBody = Boolean(previous.headingDemotedToBody || wasHeading);
        previous.headingContinuationMerged = Boolean(previous.headingContinuationMerged || wasHeading);
        previous.continuationMergeReasons = Array.from(new Set([...(previous.continuationMergeReasons || []), reason]));
        return;
      }
    }
    if (segment.type === "heading" && reason) {
      output.push({
        ...segment,
        type: "body",
        classificationReason: "body_continuation_demoted_from_heading",
        mergeReason: reason,
        headingDemotedToBody: true,
        continuationMergeReasons: [reason],
      });
      return;
    }
    output.push(segment);
  });
  return output;
}

function splitLongTextSegment(segment) {
  if (!segment || !["body", "abstract"].includes(segment.type)) return [segment];
  const lines = segment.lines || [];
  if (lines.length <= 10 && String(segment.sourceText || "").length <= 1400) return [segment];
  const parts = [];
  let current = [];
  let currentChars = 0;
  const flush = () => {
    if (!current.length) return;
    const part = makeSegmentFromParts(segment, current, segment.type, segment.column);
    part.mergeReason = "natural_paragraph_split";
    parts.push(part);
    current = [];
    currentChars = 0;
  };
  lines.forEach((line, index) => {
    const text = getSegmentLineText(line);
    current.push(index);
    currentChars += text.length;
    const sentenceEnd = /[.!?:。！？：]$/.test(text);
    if ((current.length >= 8 && sentenceEnd) || currentChars >= 1200 || current.length >= 14) {
      flush();
    }
  });
  flush();
  return parts.length > 1 ? parts.filter((part) => part.sourceText) : [segment];
}

function applyNaturalParagraphSplits(segments) {
  const output = [];
  (segments || []).forEach((segment) => output.push(...splitLongTextSegment(segment)));
  return output;
}

function isArticleMetadataLine(text) {
  const value = normalizeExtractedPdfText(text || "");
  return /^(Ratio(?:,?\s*\d{4})?|ORIGINAL ARTICLE|OPEN ACCESS|ARTICLE|RESEARCH ARTICLE|Draft version|Typeset using|DOI\b|Received|Accepted|Published)\b/i.test(value);
}

function isLikelyAuthorLineText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value || value.length > 120) return false;
  if (/\b(Department|University|Institute|Observatory|Laboratory|College|School|USA|Email|Correspondence)\b/i.test(value)) return false;
  if (/\b(AGN|SMBH|Black|Hole|Merger|Galaxy|Cosmic|Noon|Minor|Major|Growth|Secondary|Primary|Accreting|Powering)\b/i.test(value)) return false;
  if (/\b(Grounding|Physicalism|Metaphysical|Exclusion|Problem|Constitutionalist|Response|Causal|Theory)\b/i.test(value)) return false;
  if (/[.!?:]$/.test(value)) return false;
  const words = value.match(/[A-Za-z\u00c0-\u024f\u0300-\u036f'`´~.-]+/gu) || [];
  if (words.length > 6) return false;
  return /^[A-Z][A-Za-z\u00c0-\u024f\u0300-\u036f'`´~ .-]+(?:\s+[A-Z][A-Za-z\u00c0-\u024f\u0300-\u036f'`´~ .-]+)+(?:\s*\^?\d+|\s*\d+)?$/u.test(value);
}

function isObviousPaperTitleLineText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value) return false;
  return /\b(Grounding|Physicalism|Metaphysical|Exclusion|Problem|Constitutionalist|Response|Merger|Growth|AGN|Cosmic|Noon)\b/i.test(value) &&
    !/\b(University|Department|Institute|Correspondence|Email|Received|Accepted|Funding)\b/i.test(value);
}

function splitTitleAuthorMixedText(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value || value.length > 180) return null;
  const match = value.match(/^(.*\b(?:Problem|Merger|Growth|Physicalism|Exclusion|Response|Constitutionalist|AGN|Galaxy|Article|Theory))\s+([A-Z][A-Za-z\u00c0-\u024f\u0300-\u036f'`´~.-]+(?:\s+[A-Z][A-Za-z\u00c0-\u024f\u0300-\u036f'`´~.-]+){1,3}(?:\s*\^?\d+)?)$/u);
  if (!match) return null;
  const titleText = normalizeExtractedPdfText(match[1]);
  const authorText = normalizeExtractedPdfText(match[2]);
  if (!titleText || !authorText || !isLikelyAuthorLineText(authorText)) return null;
  if (isLikelyAuthorLineText(titleText)) return null;
  return { titleText, authorText };
}

function makeSingleLineSegmentFromText(base, lineIndex, type, text, reason, boxPart) {
  const line = base.lines && base.lines[lineIndex] ? { ...base.lines[lineIndex], text } : { pageNumber: base.pageNumber, column: base.column, text };
  const sourceBox = base.lineBoxes && base.lineBoxes[lineIndex] ? base.lineBoxes[lineIndex] : line.bbox || base.bbox || {};
  const totalText = getSegmentLineText(base.lines && base.lines[lineIndex]) || normalizeExtractedPdfText(base.sourceText || "");
  const ratio = Math.max(0.12, Math.min(0.88, text.length / Math.max(1, totalText.length)));
  let lineBox = { ...sourceBox, sourceLineText: text, text };
  if (boxPart === "title") {
    lineBox.width = Number(sourceBox.width || 0) * ratio;
  } else if (boxPart === "author") {
    const titleWidth = Number(sourceBox.width || 0) * (1 - ratio);
    lineBox.x = Number(sourceBox.x || 0) + titleWidth;
    lineBox.width = Number(sourceBox.width || 0) * ratio;
  }
  line.bbox = lineBox;
  line.sourceLineText = text;
  return {
    ...base,
    id: "",
    type,
    sourceText: text,
    previewText: makePreviewText(text),
    lines: [line],
    lineBoxes: [lineBox],
    bbox: makeBBoxFromLineBoxes([lineBox]),
    items: [],
    classificationReason: reason,
  };
}

function getTitleZoneLineType(text, titleStarted) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value) return "";
  if (isArticleMetadataLine(value)) return "header";
  if (/^(Funding|Keywords?|ABSTRACT)\b/i.test(value)) return "";
  if (/^(Correspondence|Corresponding author)\s*:/i.test(value) || /\bE-?mail\s*:/i.test(value)) return "correspondence";
  if (/\b(Department|University|Institute|Observatory|Laboratory|College|School|USA|Email)\b/i.test(value)) return "affiliation";
  if (isObviousPaperTitleLineText(value) && !titleStarted) return "title";
  if (isLikelyAuthorLineText(value)) return "author";
  if (!/[.!?]$/.test(value) && value.length >= 12) return "title";
  return "";
}

function splitTitleZoneSegment(segment) {
  if (!segment || Number(segment.pageNumber || 0) !== 1) return [segment];
  if (["abstract-title", "abstract", "keywords"].includes(segment.type)) return [segment];
  const bbox = segment.bbox || {};
  if (Number(bbox.y || 0) > 190) return [segment];
  const lines = segment.lines || [];
  if (!lines.length) return [segment];
  const parts = [];
  let currentType = "";
  let currentIndexes = [];
  let titleStarted = false;
  const flush = () => {
    if (!currentIndexes.length || !currentType) return;
    parts.push(makeSegmentFromParts(segment, currentIndexes, currentType, segment.column || "single"));
    currentIndexes = [];
    currentType = "";
  };
  lines.forEach((line, index) => {
    const lineText = getSegmentLineText(line);
    const titleAuthorSplit = splitTitleAuthorMixedText(lineText);
    if (titleAuthorSplit) {
      flush();
      parts.push({
        ...makeSingleLineSegmentFromText(segment, index, "title", titleAuthorSplit.titleText, "title_zone_split_title_author", "title"),
        titleAuthorSplitApplied: true,
        titleAuthorSplitReason: "title_tail_author_name",
        retaggedFromType: String(segment.type || ""),
      });
      parts.push({
        ...makeSingleLineSegmentFromText(segment, index, "author", titleAuthorSplit.authorText, "title_zone_split_title_author", "author"),
        titleAuthorSplitApplied: true,
        titleAuthorSplitReason: "title_tail_author_name",
        retaggedFromType: String(segment.type || ""),
      });
      titleStarted = true;
      return;
    }
    const type = getTitleZoneLineType(lineText, titleStarted) || segment.type;
    if (type === "title") titleStarted = true;
    if (type !== currentType) flush();
    currentType = type;
    currentIndexes.push(index);
  });
  flush();
  if (!parts.length) return [segment];
  parts.forEach((part) => {
    if (!part.classificationReason) {
      part.classificationReason = part.type === "title" ? "title_zone_title" : `title_zone_${part.type}`;
    }
  });
  return parts.filter((part) => part.sourceText);
}

function applyTitleZoneClassification(segments) {
  const output = [];
  (segments || []).forEach((segment) => output.push(...splitTitleZoneSegment(segment)));
  return output;
}

function getSegmentNoiseType(segment) {
  if (!segment || segment.type !== "body") return "";
  const text = normalizeExtractedPdfText(segment.sourceText || "");
  const bbox = segment.bbox || {};
  const width = Number(bbox.width || 0);
  const height = Number(bbox.height || 0);
  const wordCount = (text.match(/[A-Za-z]{2,}/g) || []).length;
  if (width > 0 && height > 0 && width < 50 && height > 100 && wordCount <= 8) return "margin";
  if (isPdfFooterOrWatermarkText(text)) return /Downloaded|Wiley/i.test(text) ? "watermark" : "licenseText";
  return "";
}

function applySegmentNoiseTyping(segments) {
  return (segments || []).map((segment) => {
    const noiseType = getSegmentNoiseType(segment);
    return noiseType ? { ...segment, type: noiseType, classificationReason: `${noiseType}_segment_geometry` } : segment;
  });
}

function mergeSegments(base, incoming, type, column) {
  const sourcePageContract = finalizePaperSourceMergeContract(base, incoming);
  if (sourcePageContract.status !== 'ok') return null;
  base.lines.push(...(incoming.lines || []));
  base.lineBoxes.push(...(incoming.lineBoxes || []).map((line) => ({ ...line, column: column || base.column || "single" })));
  base.items.push(...(incoming.items || []));
  base.sourceText = makeParagraphSourceText(base.lines.map((line) => ({ text: getSegmentLineText(line) })));
  base.previewText = makePreviewText(base.sourceText);
  base.bbox = makeBBoxFromLineBoxes(base.lineBoxes);
  base.type = type || base.type;
  base.column = column || base.column;
  return base;
}

function segmentStartsWithBodyText(segment) {
  const first = getSegmentLineText(segment && segment.lines && segment.lines[0]) || normalizeExtractedPdfText(segment && segment.sourceText || "");
  return isBodyStartText(first);
}

function splitContaminatedCaption(segment) {
  if (!segment) return [segment];
  if (segment.type === "body" || segment.type === "heading") {
    const lines = segment.lines || [];
    const lineBoxes = segment.lineBoxes || [];
    const captionAt = lines.findIndex((line) => isCaptionMarkerText(getSegmentLineText(line)));
    if (captionAt < 0) {
      const text = normalizeExtractedPdfText(segment.sourceText || "");
      const match = text.match(/\b(?:Figure\s+\d+\.?|Fig\.\s*\d+\.?|Table\s+\d+\.?|图\s*\d+[.．、]?|表\s*\d+[.．、]?)/i);
      if (!match || !match.index) return [segment];
      const bodyText = normalizeExtractedPdfText(text.slice(0, match.index));
      const captionText = normalizeExtractedPdfText(text.slice(match.index));
      if (!bodyText || !captionText) return [segment];
      const body = makeSingleLineSegmentFromText(segment, 0, segment.type, bodyText, "caption_boundary_split", "title");
      const caption = makeSingleLineSegmentFromText(segment, 0, "caption", captionText, "caption_boundary_split", "author");
      body.splitReason = "caption_boundary_split";
      caption.splitReason = "caption_boundary_split";
      caption.splitFromSegmentId = segment.id || "";
      caption.zoneType = "captionZone";
      caption.classificationReason = "caption_boundary_split";
      return [body, caption].filter((part) => part.sourceText);
    }
    const parts = [];
    if (captionAt > 0) {
      const bodyText = makeParagraphSourceText(lines.slice(0, captionAt).map((line) => ({ text: getSegmentLineText(line) })));
      parts.push({
        ...segment,
        lines: lines.slice(0, captionAt),
        lineBoxes: lineBoxes.slice(0, captionAt),
        sourceText: bodyText,
        previewText: makePreviewText(bodyText),
        bbox: makeBBoxFromLineBoxes(lineBoxes.slice(0, captionAt)),
        type: segment.type,
        splitReason: "caption_boundary_split",
        classificationReason: "caption_boundary_body_prefix",
      });
    }
    const captionText = makeParagraphSourceText(lines.slice(captionAt).map((line) => ({ text: getSegmentLineText(line) })));
    parts.push({
      ...segment,
      lines: lines.slice(captionAt),
      lineBoxes: lineBoxes.slice(captionAt),
      sourceText: captionText,
      previewText: makePreviewText(captionText),
      bbox: makeBBoxFromLineBoxes(lineBoxes.slice(captionAt)),
      type: "caption",
      splitFromSegmentId: segment.id || "",
      splitReason: "caption_boundary_split",
      classificationReason: "caption_boundary_split",
      zoneType: "captionZone",
    });
    return parts.filter((part) => part.sourceText);
  }
  if (segment.type !== "caption") return [segment];
  const lines = segment.lines || [];
  const lineBoxes = segment.lineBoxes || [];
  const splitAt = lines.findIndex((line, index) => {
    if (index === 0) return false;
    const text = getSegmentLineText(line);
    return isBodyStartText(text) || (!isCaptionMarkerText(text) && index > 1 && /^(The|We|This|Since|Estimating|Spectral)\b/i.test(text));
  });
  if (splitAt <= 0) return [segment];
  return [
    {
      ...segment,
      lines: lines.slice(0, splitAt),
      lineBoxes: lineBoxes.slice(0, splitAt),
      sourceText: makeParagraphSourceText(lines.slice(0, splitAt).map((line) => ({ text: getSegmentLineText(line) }))),
      previewText: makePreviewText(makeParagraphSourceText(lines.slice(0, splitAt).map((line) => ({ text: getSegmentLineText(line) })))),
      bbox: makeBBoxFromLineBoxes(lineBoxes.slice(0, splitAt)),
      type: "caption",
    },
    {
      ...segment,
      lines: lines.slice(splitAt),
      lineBoxes: lineBoxes.slice(splitAt),
      sourceText: makeParagraphSourceText(lines.slice(splitAt).map((line) => ({ text: getSegmentLineText(line) }))),
      previewText: makePreviewText(makeParagraphSourceText(lines.slice(splitAt).map((line) => ({ text: getSegmentLineText(line) })))),
      bbox: makeBBoxFromLineBoxes(lineBoxes.slice(splitAt)),
      type: "body",
    },
  ].filter((part) => part.sourceText);
}

function splitHeadingLeadSegment(segment) {
  if (!segment || segment.type !== "heading") return [segment];
  const lines = segment.lines || [];
  if (lines.length < 2) return [segment];
  let headingLineCount = 0;
  for (let index = 0; index < lines.length; index += 1) {
    const text = getSegmentLineText(lines[index]);
    if (!text) break;
    const lineType = getPdfLineType({ ...lines[index], text });
    const headingLike = lineType === "heading" || isSectionHeadingText(text) || (index === 0 && /^[A-Z][A-Za-z0-9,:'’` -]{2,}$/.test(text) && !/[.!?:]$/.test(text));
    if (!headingLike) break;
    headingLineCount += 1;
  }
  if (headingLineCount <= 0 || headingLineCount >= lines.length) return [segment];
  return [
    makeSegmentFromParts(segment, lines.slice(0, headingLineCount).map((_, index) => index), "heading", segment.column),
    makeSegmentFromParts(segment, lines.slice(headingLineCount).map((_, index) => index + headingLineCount), "body", segment.column),
  ].filter((part) => part.sourceText);
}

function applyHeadingLeadSplits(segments) {
  const output = [];
  (segments || []).forEach((segment) => output.push(...splitHeadingLeadSegment(segment)));
  return output;
}

function findPaperHeadingBodyBoundary(text) {
  const value = normalizeExtractedPdfText(text || "");
  if (!value || value.length > 260) return null;
  const bodyStartPattern = /\s+(Non-identity|The|This|These|We|I|In|It|There|Such|For|As|Because|Since|To|With|A|An)\b/;
  const bodyMatch = value.match(bodyStartPattern);
  if (!bodyMatch || typeof bodyMatch.index !== "number") return null;
  const headingText = normalizeExtractedPdfText(value.slice(0, bodyMatch.index));
  const bodyText = normalizeExtractedPdfText(value.slice(bodyMatch.index));
  if (!headingText || !bodyText) return null;
  const headingLike = isSectionHeadingText(headingText) ||
    /^(?:\d+\s*)?\|\s+[A-Z][A-Za-z0-9].{8,120}$/.test(headingText) ||
    /^(?:\d+(?:\.\d+)*\.?\s+)?[A-Z][A-Za-z0-9 ,:'’`-]{8,120}$/.test(headingText);
  if (!headingLike) return null;
  if (!isSentenceLikeBodyText(bodyText)) return null;
  return { headingText, bodyText };
}

function splitHeadingBodyMixedSegment(segment) {
  if (!segment || !["body", "heading"].includes(segment.type || "body")) return [segment];
  const lines = segment.lines || [];
  if (lines.length === 1) {
    const mixed = findPaperHeadingBodyBoundary(getSegmentLineText(lines[0]) || segment.sourceText);
    if (!mixed) return [segment];
    return [
      makeSingleLineSegmentFromText(segment, 0, "heading", mixed.headingText, "paper_heading_body_split", "title"),
      makeSingleLineSegmentFromText(segment, 0, "body", mixed.bodyText, "paper_heading_body_split", "author"),
    ].filter((part) => part.sourceText);
  }
  const firstText = getSegmentLineText(lines[0]);
  const secondText = getSegmentLineText(lines[1]);
  if (isSectionHeadingText(firstText) && isSentenceLikeBodyText(secondText)) {
    const heading = makeSegmentFromParts(segment, [0], "heading", segment.column);
    const body = makeSegmentFromParts(segment, lines.slice(1).map((_, index) => index + 1), "body", segment.column);
    heading.classificationReason = "paper_heading_body_split";
    body.classificationReason = "paper_heading_body_split";
    return [heading, body].filter((part) => part.sourceText);
  }
  return [segment];
}

function applyHeadingBodyMixedSplits(segments) {
  const output = [];
  (segments || []).forEach((segment) => output.push(...splitHeadingBodyMixedSegment(segment)));
  return output;
}

function getAbstractBoundarySplitIndex(segment) {
  if (!segment || segment.type !== "abstract") return -1;
  const lines = segment.lines || [];
  if (lines.length < 2) return -1;
  for (let index = 1; index < lines.length; index += 1) {
    const text = getSegmentLineText(lines[index]);
    if (isAbstractStopText(text) || isPdfFooterOrWatermarkText(text)) return index;
    if (/^It is stan-?$/i.test(normalizeExtractedPdfText(text || ""))) return index;
    if (index >= 2 && isSentenceLikeBodyText(text) && /-$/.test(normalizeExtractedPdfText(text))) return index;
  }
  return -1;
}

function trimAbstractBoundarySegment(segment) {
  const splitIndex = getAbstractBoundarySplitIndex(segment);
  if (splitIndex <= 0) return [segment];
  const lines = segment.lines || [];
  const abstractPart = makeSegmentFromParts(segment, lines.slice(0, splitIndex).map((_, index) => index), "abstract", segment.column);
  abstractPart.classificationReason = "abstract_boundary_trim";
  const tailIndexes = lines.slice(splitIndex).map((_, index) => index + splitIndex);
  const firstTailText = getSegmentLineText(lines[splitIndex]);
  const tailType = isPdfFooterOrWatermarkText(firstTailText) ? "licenseText" : (isSectionHeadingText(firstTailText) ? "heading" : "body");
  const tailPart = makeSegmentFromParts(segment, tailIndexes, tailType, segment.column);
  tailPart.classificationReason = "abstract_boundary_trim";
  return [abstractPart, tailPart].filter((part) => part.sourceText);
}

function applyAbstractBoundaryTrims(segments) {
  const output = [];
  (segments || []).forEach((segment) => output.push(...trimAbstractBoundarySegment(segment)));
  return output;
}

function applyFirstPageAbstractContinuationRepair(segments, config) {
  if (!isPaperPdfConfig(config)) return segments || [];
  const pageOne = (segments || []).filter((segment) => Number(segment && segment.pageNumber || 0) === 1);
  const abstractLines = pageOne.filter((segment) => ["abstract", "abstract-title"].includes(String(segment && segment.type || "")));
  if (!abstractLines.length) return segments || [];
  const abstractStartY = Math.min(...abstractLines.map((segment) => Number(segment && segment.bbox && segment.bbox.y || 0)).filter((value) => value >= 0));
  const stopCandidates = pageOne.filter((segment) => {
    const text = normalizeExtractedPdfText(segment && segment.sourceText || "");
    if (!text) return false;
    if (String(segment && segment.type || "") === "keywords") return true;
    return /^(?:\d+\s*(?:[|.]|:)\s*)?(?:INTRODUCTION|Introduction)\b/.test(text) || isSectionHeadingText(text);
  }).map((segment) => Number(segment && segment.bbox && segment.bbox.y || 0)).filter((value) => value > abstractStartY);
  const abstractStopY = stopCandidates.length ? Math.min(...stopCandidates) : Number.POSITIVE_INFINITY;
  return (segments || []).map((segment) => {
    if (!segment || Number(segment.pageNumber || 0) !== 1 || String(segment.type || "") !== "body") return segment;
    const y = Number(segment.bbox && segment.bbox.y || 0);
    const text = normalizeExtractedPdfText(segment.sourceText || "");
    if (!text || isCaptionMarkerText(text) || isReferencesHeadingText(text)) return segment;
    if (y <= abstractStartY || y >= abstractStopY) return segment;
    return {
      ...segment,
      type: "abstract",
      column: "single",
      zoneType: segment.zoneType || "abstractZone",
      classificationReason: [segment.classificationReason, "first_page_abstract_continuation"].filter(Boolean).join("|"),
    };
  });
}

function repairPaperSourceTextSpacingValue(text) {
  let value = normalizeExtractedPdfText(text || "");
  let softHyphenMergeCount = 0;
  let joinedWordRepairCount = 0;
  value = value.replace(/\b([A-Za-z]{3,})-\s+([a-z]{2,})\b/g, (_match, left, right) => {
    softHyphenMergeCount += 1;
    return `${left}${right}`;
  });
  const joinedPatterns = [
    { pattern: /\bthe(strengthened)\b/gi, replacement: "the strengthened" },
    { pattern: /\baccept(indeterministic)\b/gi, replacement: "accept indeterministic" },
    { pattern: /\baccept(deterministic)\b/gi, replacement: "accept deterministic" },
  ];
  joinedPatterns.forEach(({ pattern, replacement }) => {
    value = value.replace(pattern, (match) => {
      joinedWordRepairCount += 1;
      return match[0] === match[0].toUpperCase() ? replacement.replace(/^./, (char) => char.toUpperCase()) : replacement;
    });
  });
  return {
    text: normalizeExtractedPdfText(value),
    softHyphenMergeCount,
    joinedWordRepairCount,
    sourceSpacingRepairCount: softHyphenMergeCount + joinedWordRepairCount,
  };
}

function isPaperDanglingHyphenSegment(segment) {
  if (!segment || !["body", "abstract"].includes(String(segment.type || ""))) return false;
  return /[A-Za-z]{3,}-\s*$/.test(normalizeExtractedPdfText(segment.sourceText || ""));
}

function canMergePaperDanglingHyphenSegments(previous, next) {
  if (!isPaperDanglingHyphenSegment(previous) || !next) return false;
  if (!["body", "abstract"].includes(String(next.type || ""))) return false;
  if (finalizePaperSourceMergeContract(previous, next).status !== 'ok') return false;
  if (String(previous.column || "single") !== String(next.column || "single")) return false;
  const head = normalizeExtractedPdfText(next.sourceText || "");
  return /^[a-z]/.test(head);
}

function applyPaperSourceTextRepairs(segments, config) {
  if (!isPaperPdfConfig(config)) return segments || [];
  const merged = [];
  (segments || []).forEach((segment) => {
    const previous = merged[merged.length - 1];
    if (canMergePaperDanglingHyphenSegments(previous, segment)) {
      const previousText = normalizeExtractedPdfText(previous.sourceText || "").replace(/-\s*$/, "");
      const nextText = normalizeExtractedPdfText(segment.sourceText || "");
      previous.sourceText = normalizeExtractedPdfText(`${previousText}${nextText}`);
      previous.previewText = makePreviewText(previous.sourceText);
      previous.lines = [...(previous.lines || []), ...(segment.lines || [])];
      previous.lineBoxes = [...(previous.lineBoxes || []), ...(segment.lineBoxes || [])];
      previous.items = [...(previous.items || []), ...(segment.items || [])];
      previous.bbox = makeBBoxFromLineBoxes(previous.lineBoxes);
      previous.softHyphenMergeCount = Number(previous.softHyphenMergeCount || 0) + 1;
      previous.mergeReason = previous.mergeReason || "paper_soft_hyphen_segment_merge";
      previous.classificationReason = [previous.classificationReason, "paper_soft_hyphen_segment_merge"].filter(Boolean).join("|");
      return;
    }
    const repaired = repairPaperSourceTextSpacingValue(segment && segment.sourceText || "");
    if (repaired.sourceSpacingRepairCount > 0) {
      merged.push({
        ...segment,
        sourceText: repaired.text,
        previewText: makePreviewText(repaired.text),
        softHyphenMergeCount: Number(segment && segment.softHyphenMergeCount || 0) + repaired.softHyphenMergeCount,
        sourceSpacingRepairCount: Number(segment && segment.sourceSpacingRepairCount || 0) + repaired.sourceSpacingRepairCount,
        joinedWordRepairCount: Number(segment && segment.joinedWordRepairCount || 0) + repaired.joinedWordRepairCount,
        classificationReason: [segment && segment.classificationReason, "paper_source_spacing_repair"].filter(Boolean).join("|"),
      });
      return;
    }
    merged.push(segment);
  });
  return merged;
}

function getPaperSegmentLineBoxes(segment) {
  const lines = Array.isArray(segment && segment.lines) ? segment.lines : [];
  const lineBoxes = Array.isArray(segment && segment.lineBoxes) ? segment.lineBoxes : [];
  return lines.map((line, index) => {
    const box = lineBoxes[index] || makeLineBoxFromLine(line, segment && segment.id || "");
    return { line, box, index };
  }).filter((entry) => entry.line && entry.box);
}

function getPaperLineColumn(entry, segment) {
  const explicit = String(entry && entry.box && entry.box.column || entry && entry.line && entry.line.column || "");
  if (["left", "right", "single"].includes(explicit) && explicit !== "single") return explicit;
  const bbox = segment && segment.bbox || {};
  const width = Number(bbox.width || 0);
  const x = Number(entry && entry.box && entry.box.x || entry && entry.line && entry.line.bbox && entry.line.bbox.x || 0);
  if (width > 420) {
    const midpoint = Number(bbox.x || 0) + width / 2;
    return x < midpoint ? "left" : "right";
  }
  return String(segment && segment.column || explicit || "single");
}

function inferPaperPageContextsFromSegments(segments) {
  const byPage = new Map();
  (segments || []).forEach((segment) => {
    const pageNumber = Number(segment && segment.pageNumber || 0);
    if (!pageNumber) return;
    if (!byPage.has(pageNumber)) byPage.set(pageNumber, []);
    byPage.get(pageNumber).push(segment);
  });
  const contexts = new Map();
  byPage.forEach((pageSegments, pageNumber) => {
    const lines = pageSegments.flatMap((segment) => Array.isArray(segment.lines) ? segment.lines : []);
    const items = pageSegments.flatMap((segment) => Array.isArray(segment.items) ? segment.items : []);
    const pageWidth = Number(items.find((item) => Number(item && item.pageWidth || 0)) && items.find((item) => Number(item && item.pageWidth || 0)).pageWidth || 0) ||
      Math.max(612, ...pageSegments.map((segment) => Number(segment && segment.bbox && segment.bbox.x || 0) + Number(segment && segment.bbox && segment.bbox.width || 0)));
    const pageHeight = Number(items.find((item) => Number(item && item.pageHeight || 0)) && items.find((item) => Number(item && item.pageHeight || 0)).pageHeight || 0) ||
      Math.max(792, ...pageSegments.map((segment) => Number(segment && segment.bbox && segment.bbox.y || 0) + Number(segment && segment.bbox && segment.bbox.height || 0)));
    const imageRegions = currentPdfImageRegionsByPage[String(pageNumber)] || [];
    const captionRegions = pageSegments
      .filter((segment) => segment.type === "caption" || isCaptionMarkerText(segment.sourceText || ""))
      .map((segment) => segment.bbox)
      .filter(Boolean);
    contexts.set(pageNumber, {
      pageNumber,
      pageWidth,
      pageHeight,
      imageRegions,
      captionRegions,
      figurePageDetected: imageRegions.length > 0 || captionRegions.length > 0,
    });
  });
  return contexts;
}

function isPaperFullWidthSegmentType(segment) {
  const type = String(segment && segment.type || "body");
  return ["title", "abstract", "abstract-title", "keywords"].includes(type) || (type === "caption" && Number(segment && segment.bbox && segment.bbox.width || 0) > 420);
}

function getPaperColumnGeometry(pageWidth) {
  const policy = paperLayoutAuthority.GLOBAL_LAYOUT_POLICY;
  const width = Number(pageWidth || 0) || policy.defaultPageWidth;
  const margin = Math.max(policy.columnMarginMinimum, width * policy.columnMarginWidthRatio);
  const gutter = Math.max(policy.columnGutterMinimum, width * policy.columnGutterWidthRatio);
  const columnWidth = Math.max(1, (width - margin * 2 - gutter) / 2);
  return {
    margin,
    gutter,
    columnWidth,
    left: { name: "left", x: margin, width: columnWidth, center: margin + columnWidth / 2 },
    right: { name: "right", x: margin + columnWidth + gutter, width: columnWidth, center: margin + columnWidth + gutter + columnWidth / 2 },
  };
}

function getPaperPageWidthFromSegment(segment, fallbackWidth) {
  const fromItem = segment && Array.isArray(segment.items) && segment.items.find((item) => Number(item && item.pageWidth || 0));
  if (fromItem) return Number(fromItem.pageWidth || fallbackWidth || 0);
  const fromLine = segment && Array.isArray(segment.lines) && segment.lines.find((line) => line && line.items && line.items[0] && Number(line.items[0].pageWidth || 0));
  if (fromLine) return Number(fromLine.items[0].pageWidth || fallbackWidth || 0);
  return Number(fallbackWidth || paperLayoutAuthority.GLOBAL_LAYOUT_POLICY.defaultPageWidth);
}

function getPaperPageHeightFromSegment(segment, fallbackHeight) {
  const fromItem = segment && Array.isArray(segment.items) && segment.items.find((item) => Number(item && item.pageHeight || 0));
  if (fromItem) return Number(fromItem.pageHeight || fallbackHeight || 0);
  const fromLine = segment && Array.isArray(segment.lines) && segment.lines.find((line) => line && line.items && line.items[0] && Number(line.items[0].pageHeight || 0));
  if (fromLine) return Number(fromLine.items[0].pageHeight || fallbackHeight || 0);
  return Number(fallbackHeight || paperLayoutAuthority.GLOBAL_LAYOUT_POLICY.defaultPageHeight);
}

function inferPaperColumnFromBbox(segment, pageWidth) {
  if (!segment || !segment.bbox) return String(segment && segment.column || "single");
  if (isPaperFullWidthSegmentType(segment)) return "single";
  const type = String(segment.type || "body");
  if (!["body", "heading", "caption"].includes(type)) return String(segment.column || "single");
  const width = getPaperPageWidthFromSegment(segment, pageWidth);
  const geometry = getPaperColumnGeometry(width);
  const box = segment.bbox || {};
  const centerX = Number(box.x || 0) + Number(box.width || 0) / 2;
  const leftDistance = Math.abs(centerX - geometry.left.center);
  const rightDistance = Math.abs(centerX - geometry.right.center);
  return leftDistance <= rightDistance ? "left" : "right";
}

function isWriteBoxTooNarrow(writeBox) {
  return Boolean(writeBox && Number(writeBox.width || 0) <= paperLayoutAuthority.GLOBAL_LAYOUT_POLICY.writeBoxTooNarrowWidth);
}

function repairPaperSegmentColumnByBbox(segment, pageWidth, reason) {
  if (!segment || !segment.bbox || isPaperFullWidthSegmentType(segment)) return segment;
  const currentColumn = String(segment.column || "single");
  const inferredColumn = inferPaperColumnFromBbox(segment, pageWidth);
  if (!['left', 'right'].includes(inferredColumn)) {
    return {
      ...segment,
      inferredColumnFromBbox: inferredColumn,
      bboxColumnMismatch: false,
    };
  }
  const mismatch = currentColumn !== inferredColumn;
  if (!mismatch) {
    return {
      ...segment,
      inferredColumnFromBbox: inferredColumn,
      bboxColumnMismatch: false,
    };
  }
  return {
    ...segment,
    previousColumn: currentColumn,
    column: inferredColumn,
    inferredColumnFromBbox: inferredColumn,
    columnReassignedByBbox: true,
    columnReassignReason: reason || (inferredColumn === 'right' ? 'bbox_center_in_right_column' : 'bbox_center_in_left_column'),
    bboxColumnMismatch: true,
    warnings: [...(segment.warnings || []), 'paper_column_repaired_before_clip'],
    lineBoxes: (segment.lineBoxes || []).map((line) => ({ ...line, column: inferredColumn })),
    lines: (segment.lines || []).map((line) => ({ ...line, column: inferredColumn })),
  };
}

function repairPaperSegmentColumnsByBbox(segments, config) {
  if (!isPaperPdfConfig(config)) return segments || [];
  return (segments || []).map((segment) => {
    const pageWidth = getPaperPageWidthFromSegment(segment, 612);
    return repairPaperSegmentColumnByBbox(segment, pageWidth, 'bbox_column_mismatch');
  });
}

function bboxHorizontalOverlapRatio(a, b) {
  if (!a || !b) return 0;
  const left = Math.max(Number(a.x || 0), Number(b.x || 0));
  const right = Math.min(Number(a.x || 0) + Number(a.width || 0), Number(b.x || 0) + Number(b.width || 0));
  return Math.max(0, right - left) / Math.max(1, Math.min(Number(a.width || 0), Number(b.width || 0)));
}

function bboxCrossesRegionY(box, region) {
  if (!box || !region) return false;
  const top = Number(box.y || 0);
  const bottom = top + Number(box.height || 0);
  const regionTop = Number(region.y || 0);
  const regionBottom = regionTop + Number(region.height || 0);
  return top < regionBottom && bottom > regionTop;
}

function shouldSplitByImageRegion(segment, imageRegions, captionRegions) {
  if (!segment || !["body", "heading"].includes(String(segment.type || "body"))) return false;
  const box = segment.bbox || {};
  const regions = [...(imageRegions || []), ...(captionRegions || [])].filter(Boolean);
  return regions.some((region) => {
    if (bboxOverlapRatio(box, region) > 0.01) return true;
    return bboxCrossesRegionY(box, region) && bboxHorizontalOverlapRatio(box, region) > 0.25;
  });
}

function getPaperImageCaptionRegionLineKind(entry, imageRegions, captionRegions) {
  const text = getSegmentLineText(entry && entry.line);
  const box = entry && entry.box || {};
  if (isInlineFigureReferenceText(text, entry && entry.previousText, entry && entry.nextText)) return "";
  if (isTrueCaptionStart(text, {
    box,
    imageRegions,
    captionRegions,
    previousText: entry && entry.previousText,
    nextText: entry && entry.nextText,
  })) return "caption";
  if ((captionRegions || []).some((region) => bboxOverlapRatio(box, region) > 0.02)) {
    return isTrueCaptionStart(text, {
      box,
      imageRegions,
      captionRegions,
      previousText: entry && entry.previousText,
      nextText: entry && entry.nextText,
    }) ? "caption" : "";
  }
  const overlappingImageRegion = (imageRegions || []).find((region) => (
    bboxOverlapRatio(box, region) > 0.02 ||
    bboxCrossesRegionY(box, region) && bboxHorizontalOverlapRatio(box, region) > 0.45
  ));
  if (overlappingImageRegion && isTrueImageInternalTextLine(text, overlappingImageRegion)) return "imageText";
  return "";
}

function isBodyLikeImageTextChunk(segment, indexes) {
  const entries = getPaperSegmentLineBoxes(segment).filter((entry) => (indexes || []).includes(entry.index));
  const text = makeParagraphSourceText(entries.map((entry) => entry.line));
  if (entries.length > 1 && text.length > 35) return true;
  return isBodyLikeImageText(text);
}

function splitSegmentByImageCaptionRegions(segment, pageContext) {
  if (!segment || !["body", "heading"].includes(String(segment.type || "body"))) return [segment];
  const imageRegions = pageContext && pageContext.imageRegions || [];
  const captionRegions = pageContext && pageContext.captionRegions || [];
  if (!imageRegions.length && !captionRegions.length) return [segment];
  const entries = getPaperSegmentLineBoxes(segment);
  if (entries.length < 1) return [segment];
  const chunks = [];
  let current = null;
  const flush = () => {
    if (current && current.indexes.length) chunks.push(current);
    current = null;
  };
  entries.forEach((entry, entryIndex) => {
    entry.previousText = entryIndex > 0 ? getSegmentLineText(entries[entryIndex - 1].line) : "";
    entry.nextText = entryIndex < entries.length - 1 ? getSegmentLineText(entries[entryIndex + 1].line) : "";
    const regionKind = getPaperImageCaptionRegionLineKind(entry, imageRegions, captionRegions);
    const type = regionKind === "caption" ? "caption" : (regionKind === "imageText" ? "imageText" : String(segment.type || "body"));
    const column = getPaperLineColumn(entry, segment);
    if (!current || current.type !== type || current.column !== column) {
      flush();
      current = { type, column, indexes: [] };
    }
    current.indexes.push(entry.index);
  });
  flush();
  const hasRegionSplit = chunks.some((chunk) => chunk.type === "caption" || chunk.type === "imageText") || chunks.length > 1;
  if (!hasRegionSplit) return [segment];
  return chunks.map((chunk, index) => {
    const chunkText = makeParagraphSourceText(getPaperSegmentLineBoxes(segment).filter((entry) => chunk.indexes.includes(entry.index)).map((entry) => entry.line));
    const captionBodyLikeReason = chunk.type === "caption" ? getCaptionBodyLikeRiskReason(chunkText) : "";
    const safeType = chunk.type === "caption" && captionBodyLikeReason
      ? String(segment.type || "body")
      : (chunk.type === "imageText" && isBodyLikeImageTextChunk(segment, chunk.indexes)
      ? String(segment.type || "body")
      : chunk.type);
    const part = makeSegmentFromParts(segment, chunk.indexes, safeType, chunk.column);
    if (segment.id && chunks.length > 1) {
      part.id = `${String(segment.id)}-region-${index + 1}`;
      part.lineBoxes = (part.lineBoxes || []).map((line) => ({ ...line, segmentId: part.id }));
    }
    part.splitFromSegmentId = segment.id || "";
    part.splitReason = "image_caption_region_boundary_split";
    part.splitIndex = index + 1;
    part.splitCount = chunks.length;
    part.imageRegionSegmentationApplied = true;
    part.bodySplitByImageRegion = safeType !== String(segment.type || "body") || chunks.length > 1;
    part.imageRegionSplitReason = "body_split_by_image_or_caption_region";
    part.classificationReason = safeType === "caption" ? "caption_boundary_split" : (safeType === "imageText" ? "image_region_preserve_split" : (part.classificationReason || "image_caption_region_boundary_split"));
    if (chunk.type === "imageText" && safeType !== "imageText") {
      part.classificationReason = "image_text_body_like_demoted_to_body";
      part.imageTextDemotedToBody = true;
      part.imageTextDemoteReason = getImageTextBodyLikeRiskReason(part.sourceText || "") || "image_text_chunk_body_like";
    }
    if (chunk.type === "caption" && safeType !== "caption") {
      part.classificationReason = "caption_body_like_demoted_to_body";
      part.captionBodyLikeDemotedToBody = true;
      part.captionBodyLikeRiskReason = captionBodyLikeReason || "caption_chunk_body_like";
    }
    if (safeType === "caption") part.zoneType = "captionZone";
    if (safeType === "imageText") {
      part.zoneType = "imageZone";
      part.status = "preserved";
      part.skipReason = "image_text_preserve_original";
      part.translatedText = "";
    }
    return part;
  }).filter((part) => part.sourceText);
}

function makeFallbackPaperOversizedChunks(entries, segment, reasons) {
  const ordered = (entries || []).slice().sort((a, b) => {
    const colA = getPaperLineColumn(a, segment);
    const colB = getPaperLineColumn(b, segment);
    if (colA !== colB) return ["left", "right", "single"].indexOf(colA) - ["left", "right", "single"].indexOf(colB);
    return Number(a.box.y || 0) - Number(b.box.y || 0);
  });
  if (ordered.length < 2) return [];
  const maxLines = reasons && reasons.includes("overlaps_image_or_caption_region") ? 2 : 3;
  const chunks = [];
  let current = [];
  const flush = () => {
    if (!current.length) return;
    const column = getPaperLineColumn(current[0], segment);
    chunks.push({ column, entries: current });
    current = [];
  };
  ordered.forEach((entry) => {
    const text = getSegmentLineText(entry.line);
    const previous = current[current.length - 1];
    const previousText = previous ? getSegmentLineText(previous.line) : "";
    const column = getPaperLineColumn(entry, segment);
    const previousColumn = previous ? getPaperLineColumn(previous, segment) : column;
    const isBoundary = current.length > 0 && (
      column !== previousColumn ||
      isSectionHeadingText(text) ||
      isTrueCaptionStart(text, { allowNoRegion: true, previousText }) ||
      isFormulaProtectedLineBox({ text, sourceLineText: text }, { mode: "paper_pdf", enableFormulaLinePreserve: "equation_block_only" }) ||
      (current.length >= maxLines && !/-\s*$/.test(previousText))
    );
    if (isBoundary) flush();
    current.push(entry);
  });
  flush();
  return chunks.length > 1 ? chunks : [];
}

function getPaperOversizedSplitReasons(segment, pageContext) {
  const reasons = [];
  if (!segment || !["body", "heading"].includes(String(segment.type || "body"))) return reasons;
  const lineCount = Array.isArray(segment.lineBoxes) ? segment.lineBoxes.length : (segment.lines || []).length;
  const text = cleanPdfText(segment.sourceText || "");
  const bbox = segment.bbox || {};
  const lineEntries = getPaperSegmentLineBoxes(segment);
  const inferredColumns = new Set(lineEntries.map((entry) => getPaperLineColumn(entry, segment)).filter(Boolean));
  const width = Number(bbox.width || 0);
  const height = Number(bbox.height || 0);
  const pageWidth = Number(pageContext && pageContext.pageWidth || 0) || getPaperPageWidthFromSegment(segment, 612);
  const pageHeight = Number(pageContext && pageContext.pageHeight || 0) || getPaperPageHeightFromSegment(segment, 792);
  const geometry = getPaperColumnGeometry(pageWidth);
  const columnWidth = inferredColumns.has("left") && inferredColumns.has("right") ? Math.max(1, width / 2) : geometry.columnWidth;
  if (lineCount > 8) reasons.push("line_count_gt_8");
  if (height > 120) reasons.push("bbox_height_gt_120");
  if (pageHeight && height > pageHeight * 0.6) reasons.push("bbox_height_gt_page_60_percent");
  if (lineCount >= 7 && height > 200) reasons.push("line_count_7_and_bbox_height_gt_200");
  if (width > columnWidth * 1.35) reasons.push("bbox_width_crosses_column");
  if (pageWidth && (width > pageWidth * 0.95 && !isNormalFullWidthSegment(segment))) reasons.push("oversized_segment_bbox_equivalent_width");
  if (segment.crossedColumnBoundary) reasons.push("crossed_column_boundary");
  if (String(segment.column || "single") === "single" && width > 420) reasons.push("single_segment_on_double_column_width");
  if ((segment.warnings || []).includes("oversized_segment_bbox")) reasons.push("oversized_segment_bbox_warning");
  if (segment.columnReassignedByBbox && height > 80) reasons.push("column_reassigned_high_body");
  if (segment.writeBoxTooNarrowBeforeRepair) reasons.push("writebox_too_narrow_before_repair");
  if ((segment.lines || []).some((line) => isSectionHeadingText(getSegmentLineText(line)))) reasons.push("contains_section_heading");
  if ((segment.lines || []).some((line) => isFormulaProtectedLineBox({ text: getSegmentLineText(line), sourceLineText: getSegmentLineText(line) }, { mode: "paper_pdf", enableFormulaLinePreserve: "equation_block_only" }))) reasons.push("contains_formula_block");
  if (/\b(?:doi|data availability|mast|archive)\b/i.test(text)) reasons.push("contains_doi_or_data_line");
  const avoidRegions = [...(pageContext && pageContext.imageRegions || []), ...(pageContext && pageContext.captionRegions || [])];
  if (avoidRegions.some((region) => shouldSplitByImageRegion(segment, [region], []))) reasons.push("overlaps_image_or_caption_region");
  return Array.from(new Set(reasons));
}

function shouldSplitOversizedPaperSegment(segment, pageContext) {
  return getPaperOversizedSplitReasons(segment, pageContext).length > 0;
}

function splitOversizedPaperBodySegment(segment, pageContext) {
  const reasons = getPaperOversizedSplitReasons(segment, pageContext);
  if (!reasons.length) return [segment];
  const entries = getPaperSegmentLineBoxes(segment);
  if (entries.length < 2) return [segment];
  const avoidRegions = [...(pageContext && pageContext.imageRegions || []), ...(pageContext && pageContext.captionRegions || [])];
  const orderedColumns = ["left", "right", "single"];
  const columnGroups = new Map();
  entries.forEach((entry) => {
    const column = getPaperLineColumn(entry, segment);
    if (!columnGroups.has(column)) columnGroups.set(column, []);
    columnGroups.get(column).push(entry);
  });
  const chunks = [];
  orderedColumns.forEach((column) => {
    const group = (columnGroups.get(column) || []).sort((a, b) => Number(a.box.y || 0) - Number(b.box.y || 0));
    let current = [];
    const flush = () => {
      if (current.length) chunks.push({ column, entries: current });
      current = [];
    };
    group.forEach((entry, groupIndex) => {
      const text = getSegmentLineText(entry.line);
      const previousEntry = current.length ? current[current.length - 1] : null;
      const previousText = previousEntry ? getSegmentLineText(previousEntry.line) : "";
      const gap = previousEntry
        ? Number(entry.box.y || 0) - (Number(previousEntry.box.y || 0) + Number(previousEntry.box.height || 0))
        : 0;
      const lineHeight = Math.max(6, Number(entry.box.height || entry.box.fontSize || 8));
      const overlapsAvoidRegion = avoidRegions.some((region) => bboxOverlapRatio(entry.box, region) > 0.05);
      const previousHyphenContinuation = /-\s*$/.test(previousText);
      const startsNewParagraph = current.length > 0 && !previousHyphenContinuation && (
        groupIndex === 0 ||
        overlapsAvoidRegion ||
        gap > lineHeight * 1.7 ||
        isSectionHeadingText(text) ||
        isTrueCaptionStart(text, { allowNoRegion: true, previousText }) ||
        isFormulaProtectedLineBox({ text, sourceLineText: text }, { mode: "paper_pdf", enableFormulaLinePreserve: "equation_block_only" }) ||
        /^\s*(?:doi|Data Availability)\b/i.test(text) ||
        (current.length >= 5 && lineEndsSentenceStrict(previousText) && /^[A-Z]/.test(text) && !startsWithNumericContinuation(text))
      );
      if (startsNewParagraph || (overlapsAvoidRegion && current.length)) flush();
      current.push(entry);
      if (overlapsAvoidRegion) flush();
      if (current.length >= 8 && lineEndsSentenceStrict(text)) flush();
    });
    flush();
  });
  if (chunks.length <= 1) {
    const fallbackChunks = makeFallbackPaperOversizedChunks(entries, segment, reasons);
    if (fallbackChunks.length > 1) chunks.splice(0, chunks.length, ...fallbackChunks);
  }
  if (chunks.length <= 1) {
    return [{
      ...segment,
      oversizedSplitCandidateReasons: reasons,
      oversizedSplitSkippedReason: "single_chunk_after_fallback",
    }];
  }
  return chunks.map((chunk, index) => {
    const indexes = chunk.entries.map((entry) => entry.index);
    const firstText = getSegmentLineText(chunk.entries[0] && chunk.entries[0].line);
    const partType = isCaptionMarkerText(firstText) ? "caption" : (isSectionHeadingText(firstText) ? "heading" : "body");
    const part = makeSegmentFromParts(segment, indexes, partType, chunk.column);
    part.splitFromSegmentId = segment.id || "";
    part.splitReason = "paper_oversized_body_second_pass";
    part.splitIndex = index + 1;
    part.splitCount = chunks.length;
    part.oversizedSplitCandidateReasons = reasons;
    part.paperSecondPassSplitApplied = true;
    part.finalOversizedSplitApplied = true;
    part.finalOversizedSplitReason = reasons.join("|");
    part.classificationReason = part.classificationReason || "paper_oversized_body_second_pass";
    if (avoidRegions.some((region) => bboxOverlapRatio(part.bbox, region) > 0.02)) {
      part.imageRegionOverlap = true;
      part.bodySplitByImageRegion = true;
      part.imageRegionSegmentationApplied = true;
      part.imageRegionSplitReason = "split_around_image_or_caption_region";
      part.warnings = [...(part.warnings || []), "body_image_region_overlap_after_split"];
    }
    return part;
  }).filter((part) => part.sourceText);
}

function applyOversizedPaperBodySplits(segments, config) {
  if (!isPaperPdfConfig(config)) return segments || [];
  const pageContexts = inferPaperPageContextsFromSegments(segments);
  const output = [];
  (segments || []).forEach((segment) => {
    const context = pageContexts.get(Number(segment && segment.pageNumber || 0));
    output.push(...splitOversizedPaperBodySegment(segment, context));
  });
  return output;
}

function applyImageRegionSegmentationConstraints(segments, config, options) {
  if (!isPaperPdfConfig(config)) return segments || [];
  options = options || {};
  const pageContexts = inferPaperPageContextsFromSegments(segments);
  const output = [];
  const enforceSegmentIdentity = options.enforceSegmentIdentity === true;
  const identityAllocator = enforceSegmentIdentity ? createSegmentIdAllocator(segments) : null;
  const identityOriginByObject = enforceSegmentIdentity ? new WeakMap() : null;
  const emittedSegmentIds = new Set();
  const appendSegment = (segment, origin) => {
    if (!enforceSegmentIdentity) {
      output.push(segment);
      return;
    }
    identityOriginByObject.set(segment, String(origin || "image_region_constraint"));
    output.push(segment);
  };
  const materializeFinalIdentity = (segment) => {
    const requestedId = String(segment && segment.id || "");
    const segmentId = requestedId && !emittedSegmentIds.has(requestedId)
      ? requestedId
      : identityAllocator.next();
    emittedSegmentIds.add(segmentId);
    identityAllocator.reserve(segmentId);
    return materializeSegmentIdentity(segment, segmentId, identityOriginByObject.get(segment) || "post_image_region_source_finalization");
  };
  (segments || []).forEach((segment) => {
    const context = pageContexts.get(Number(segment && segment.pageNumber || 0));
    const imageRegions = context && context.imageRegions || [];
    const captionRegions = context && context.captionRegions || [];
    if (!shouldSplitByImageRegion(segment, imageRegions, captionRegions)) {
      appendSegment(segment, "image_region_constraint_passthrough");
      return;
    }
    const regionParts = splitSegmentByImageCaptionRegions(segment, context);
    if (regionParts.length > 1 || (regionParts[0] && regionParts[0] !== segment)) {
      regionParts.forEach((part) => appendSegment(part, "image_region_boundary_split"));
      return;
    }
    const splitParts = splitOversizedPaperBodySegment(segment, context);
    if (splitParts.length <= 1 && splitParts[0] === segment) {
      appendSegment({
        ...segment,
        imageRegionOverlap: true,
        imageRegionSegmentationApplied: false,
        imageRegionSplitReason: "image_region_overlap_single_line",
        warnings: [...(segment.warnings || []), "body_image_region_overlap"],
      });
      return;
    }
    splitParts.forEach((part) => {
      appendSegment({
        ...part,
        bodySplitByImageRegion: Boolean(part.splitFromSegmentId || part.bodySplitByImageRegion),
        imageRegionOverlap: true,
        imageRegionSegmentationApplied: true,
        imageRegionSplitReason: part.imageRegionSplitReason || "image_region_segmentation_constraint",
        warnings: [...(part.warnings || []), "body_split_by_image_region"],
      }, "oversized_image_region_split");
    });
  });
  if (!enforceSegmentIdentity) return output;
  // Image/caption-region splitting is the last operation allowed to create new source fragments.
  // Finalize split-word continuity after that geometry pass and before immutable segment identity is
  // materialized, otherwise a repaired "bolomet-ric" can be split back into two invalid translation
  // inputs. materializeSegmentIdentity then rewrites every lineBox owner to the surviving identity.
  const sourceFinalizedOutput = applyPaperSourceTextRepairs(output, config);
  return sourceFinalizedOutput.map(materializeFinalIdentity);
}

function auditPaperImageTextPreserveRisk(segments, options = {}) {
  const demote = options.demote !== false;
  const risks = [];
  const output = (segments || []).map((segment) => {
    if (!segment || String(segment.type || "") !== "imageText") return segment;
    const text = normalizeExtractedPdfText(segment.sourceText || segment.text || "");
    const reason = getImageTextBodyLikeRiskReason(text);
    if (!reason) return segment;
    risks.push({
      segmentId: String(segment.id || ""),
      pageNumber: Number(segment.pageNumber || 0),
      type: "imageText",
      reason,
      textPreview: text.slice(0, 120),
    });
    if (!demote) return segment;
    return {
      ...segment,
      type: "body",
      status: "pending",
      skipReason: "",
      preserveReasonLabel: "",
      classificationReason: "image_text_body_like_demoted_to_body",
      imageTextDemotedToBody: true,
      imageTextDemoteReason: reason,
      translatedText: segment.translatedText || "",
      zoneType: segment.zoneType === "imageZone" ? "" : segment.zoneType,
    };
  });
  return {
    segments: output,
    risks,
  };
}

function detectReferenceStart(segments) {
  return (segments || []).find((segment) => segment.referenceHeading || isPaperReferenceHeadingText(segment.sourceText || ""));
}

function isPaperReferenceHeadingText(text) {
  const value = normalizeExtractedPdfText(text || "");
  return isReferencesHeadingText(value) || /^(References|Bibliography|Works Cited)\b/i.test(value);
}
function detectReferenceHeadingSegment(segments) {
  return (segments || []).filter((segment) => segment && (segment.referenceHeading || isPaperReferenceHeadingText(segment.sourceText || "")))
    .sort((a, b) => Number(a.pageNumber || 0) - Number(b.pageNumber || 0) || Number(a.bbox && a.bbox.y || 0) - Number(b.bbox && b.bbox.y || 0))[0] || null;
}

function isReferenceModeExemptSegment(segment) {
  return ["footer", "pageNumber", "margin", "header", "noise", "watermark", "licenseText"].includes(String(segment && segment.type || ""));
}

function retagSegmentAsReference(segment, trigger) {
  if (!segment || isReferenceModeExemptSegment(segment)) return segment;
  if (segment.type === "reference" && segment.referenceModeApplied) return segment;
  return {
    ...segment,
    retaggedFromType: String(segment.type || ""),
    retaggedFromStatus: String(segment.status || ""),
    type: "reference",
    status: "preserved",
    translatedText: "",
    translatedPreview: "",
    hasTranslatedText: false,
    referenceModeApplied: true,
    referenceModeTriggerSegmentId: String(trigger && trigger.id || `reference-start-p${Number(trigger && trigger.pageNumber || 0)}-y${Math.round(Number(trigger && trigger.bbox && trigger.bbox.y || 0))}`),
    referenceModeTriggerY: Number(trigger && trigger.bbox && trigger.bbox.y || 0),
    classificationReason: segment.referenceHeading || isPaperReferenceHeadingText(segment.sourceText || "") ? "reference_mode_heading" : "reference_mode_page_y_coordinate",
  };
}

function applyReferenceMode(segments, config) {
  if (!isPaperPdfConfig(config) || !config.enableReferencePreserve) return segments || [];
  const referenceStart = detectReferenceHeadingSegment(segments);
  if (!referenceStart) return segments || [];
  const startPage = Number(referenceStart.pageNumber || 0);
  const triggerY = Number(referenceStart.bbox && referenceStart.bbox.y || 0);
  const tolerance = 12;
  const retaggedIds = [];
  const mapped = (segments || []).map((segment) => {
    const pageNumber = Number(segment && segment.pageNumber || 0);
    const y = Number(segment && segment.bbox && segment.bbox.y || 0);
    const samePageAfterHeading = pageNumber === startPage && y >= triggerY - tolerance;
    const laterPage = pageNumber > startPage;
    const heading = segment === referenceStart || segment.referenceHeading || isPaperReferenceHeadingText(segment.sourceText || "");
    if (heading || samePageAfterHeading || laterPage) {
      const next = retagSegmentAsReference(segment, referenceStart);
      if (next !== segment) retaggedIds.push(String(segment.id || `p${pageNumber}-y${Math.round(y)}`));
      return next;
    }
    return segment;
  });
  return mapped.map((segment) => segment.referenceModeApplied ? { ...segment, referenceModeRetaggedSegmentIds: retaggedIds } : segment);
}
function applyCaptionBoundaryCleanup(segments) {
  let cleaned = [];
  (segments || []).forEach((segment) => {
    cleaned.push(...splitContaminatedCaption(segment));
  });
  const secondPass = [];
  cleaned.forEach((segment) => {
    secondPass.push(...splitContaminatedCaption(segment));
  });
  return secondPass;
}

function isImageTextNoiseSegment(segment) {
  if (!segment || segment.type !== "body") return false;
  const text = normalizeExtractedPdfText(segment.sourceText || "");
  if (!text) return true;
  if (/^(Left|Right|Top|Bottom):\s+/i.test(text) && !isBodyStartText(text)) return true;
  if (/^[a-z].{0,180}$/.test(text) && !isBodyStartText(text) && (isImageLabelText(text) || isImageInternalTextLine(text))) {
    return true;
  }
  return false;
}

function canMergeBodyIntoCaption(previous, segment) {
  if (!previous || !segment) return false;
  if (previous.type !== "caption" || segment.type !== "body") return false;
  if (previous.pageNumber !== segment.pageNumber || previous.column !== segment.column) return false;
  const text = normalizeExtractedPdfText(segment.sourceText || "");
  if (!text || isBodyStartText(text)) return false;
  if ((segment.lineBoxes || []).length > 3 || text.length > 180) return false;
  const prevLast = previous.lineBoxes && previous.lineBoxes[previous.lineBoxes.length - 1];
  const currFirst = segment.lineBoxes && segment.lineBoxes[0];
  if (!prevLast || !currFirst) return false;
  const gap = Number(currFirst.y || 0) - (Number(prevLast.y || 0) + Number(prevLast.height || 0));
  const lineHeight = Math.max(Number(prevLast.height || 0), Number(currFirst.height || 0), Number(currFirst.fontSize || 0), 8);
  const xDelta = Math.abs(Number(currFirst.x || 0) - Number(previous.lineBoxes[0] && previous.lineBoxes[0].x || 0));
  return gap <= lineHeight * 2.2 && xDelta <= Math.max(18, lineHeight * 4);
}

function applyCaptionFragmentMerges(segments) {
  const output = [];
  segments.forEach((segment) => {
    if (isImageTextNoiseSegment(segment)) {
      currentPdfIgnoredNoiseLines += Math.max(1, (segment.lineBoxes || []).length);
      return;
    }
    const previous = output[output.length - 1];
    if (canMergeBodyIntoCaption(previous, segment)) {
      if (mergeSegments(previous, segment, "caption", previous.column)) return;
    }
    output.push(segment);
  });
  return output;
}

function applyReferenceTypingAndOrdering(segments) {
  let referencesStarted = false;
  const typed = segments.map((segment) => {
    const text = normalizeExtractedPdfText(segment.sourceText || "");
    const isReferencesHeading = segment.type === "heading" && isReferencesHeadingText(text);
    if (isReferencesHeading) {
      referencesStarted = true;
      return { ...segment, type: "reference", referenceHeading: true };
    }
    if (referencesStarted && segment.type === "body") {
      return { ...segment, type: "reference" };
    }
    return segment;
  });

  const pages = new Map();
  typed.forEach((segment) => {
    const key = Number(segment.pageNumber || 0);
    if (!pages.has(key)) pages.set(key, []);
    pages.get(key).push(segment);
  });

  const reordered = [];
  [...pages.keys()].sort((a, b) => a - b).forEach((pageNumber) => {
    const pageSegments = pages.get(pageNumber) || [];
    const referenceHeadingIndex = pageSegments.findIndex((segment) => segment.referenceHeading);
    if (referenceHeadingIndex < 0) {
      reordered.push(...pageSegments);
      return;
    }
    const beforeReferences = [];
    const references = [];
    let referenceHeading = null;
    pageSegments.forEach((segment) => {
      if (segment.referenceHeading) {
        referenceHeading = segment;
      } else if (segment.type === "reference") {
        references.push(segment);
      } else {
        beforeReferences.push(segment);
      }
    });
    reordered.push(...beforeReferences);
    if (referenceHeading) reordered.push(referenceHeading);
    reordered.push(...references);
  });
  return splitReferenceSegmentsInOrder(reordered);
}

function makeReferenceSegmentFromEntries(entries) {
  const filtered = (entries || []).filter((entry) => entry && entry.line);
  if (!filtered.length) return null;
  const base = filtered[0].segment || {};
  const lines = filtered.map((entry) => entry.line);
  const lineBoxes = filtered.map((entry) => entry.lineBox).filter(Boolean);
  const sourceText = makeParagraphSourceText(lines.map((line) => ({ text: getSegmentLineText(line) })));
  if (!sourceText) return null;
  return {
    ...base,
    id: "",
    pageNumber: filtered[0].pageNumber || lines[0].pageNumber || base.pageNumber,
    column: filtered[0].column || lines[0].column || base.column || "single",
    type: "reference",
    sourceText,
    previewText: makePreviewText(sourceText),
    lines,
    lineBoxes,
    bbox: makeBBoxFromLineBoxes(lineBoxes),
    items: [],
    referenceLike: true,
  };
}

function splitReferenceSegmentsInOrder(segments) {
  const output = [];
  let referencesMode = false;
  let currentEntries = [];

  const flushReference = () => {
    const segment = makeReferenceSegmentFromEntries(currentEntries);
    if (segment) output.push(segment);
    currentEntries = [];
  };

  segments.forEach((segment) => {
    const text = normalizeExtractedPdfText(segment.sourceText || "");
    if (segment.referenceHeading || isReferencesHeadingText(text)) {
      flushReference();
      referencesMode = true;
      output.push({ ...segment, type: "reference", referenceHeading: true });
      return;
    }

    if (!referencesMode || segment.type !== "reference") {
      flushReference();
      output.push(segment);
      return;
    }

    const lines = segment.lines || [];
    const lineBoxes = segment.lineBoxes || [];
    lines.forEach((line, index) => {
      const lineText = getSegmentLineText(line);
      const previousEntry = currentEntries.length ? currentEntries[currentEntries.length - 1] : null;
      const previousLineText = previousEntry ? getSegmentLineText(previousEntry.line) : "";
      const sameReferenceFlow =
        previousEntry &&
        Number(previousEntry.pageNumber || 0) === Number(line.pageNumber || segment.pageNumber || 0) &&
        String(previousEntry.column || "single") === String((lineBoxes[index] && lineBoxes[index].column) || line.column || segment.column || "single");
      const previousNeedsAuthorContinuation = sameReferenceFlow && /&$/.test(normalizeExtractedPdfText(previousLineText));
      if (isReferenceStartLineText(lineText) && currentEntries.length && !previousNeedsAuthorContinuation) {
        flushReference();
      }
      currentEntries.push({
        segment,
        line,
        lineBox: lineBoxes[index],
        pageNumber: line.pageNumber || segment.pageNumber,
        column: (lineBoxes[index] && lineBoxes[index].column) || line.column || segment.column || "single",
      });
    });
  });

  flushReference();
  return output;
}

function applyCrossPageContinuations(segments) {
  return segments.map((segment, index) => {
    if (index === 0 || segment.type !== "body") return segment;
    const previous = segments[index - 1];
    if (!previous || previous.type !== "body") return segment;
    if (Number(segment.pageNumber || 0) !== Number(previous.pageNumber || 0) + 1) return segment;
    const previousText = normalizeExtractedPdfText(previous.sourceText || "");
    const currentText = normalizeExtractedPdfText(segment.sourceText || "");
    if (!/[A-Za-z]{2,}-$/.test(previousText) || !/^[a-z]/.test(currentText)) return segment;
    if ((segment.lineBoxes || []).length > 3) return segment;
    return {
      ...segment,
      continuation: true,
      continuationFrom: previous.id,
      sourceText: currentText,
      previewText: makePreviewText(currentText),
    };
  });
}

function splitSegmentByPageAndColumn(segment) {
  const lines = Array.isArray(segment && segment.lines) ? segment.lines : [];
  if (!segment || lines.length <= 1) return [segment];
  const buckets = new Map();
  lines.forEach((line, index) => {
    const lineBox = segment.lineBoxes && segment.lineBoxes[index] || null;
    const pageNumber = Number(line.pageNumber || lineBox && lineBox.pageNumber || segment.pageNumber || 0);
    const column = String(lineBox && lineBox.column || line.column || segment.column || "single");
    const key = `${pageNumber}|${column}`;
    if (!buckets.has(key)) buckets.set(key, { pageNumber, column, lines: [], lineBoxes: [] });
    buckets.get(key).lines.push(line);
    if (lineBox) buckets.get(key).lineBoxes.push(lineBox);
  });
  if (buckets.size <= 1) return [segment];
  return [...buckets.values()].map((bucket) => {
    const sourceText = makeParagraphSourceText(bucket.lines.map((line) => ({ text: getSegmentLineText(line) })));
    return {
      ...segment,
      id: "",
      pageNumber: bucket.pageNumber,
      column: bucket.column,
      sourceText,
      previewText: makePreviewText(sourceText),
      lines: bucket.lines,
      lineBoxes: bucket.lineBoxes,
      bbox: makeBBoxFromLineBoxes(bucket.lineBoxes),
      items: [],
      splitReason: "page_or_column_boundary",
    };
  }).filter((part) => part.sourceText && part.bbox && Number(part.bbox.width || 0) > 0);
}

function enforcePageAndColumnBoundaries(segments) {
  const output = [];
  (segments || []).forEach((segment) => {
    output.push(...splitSegmentByPageAndColumn(segment));
  });
  return output;
}

function groupRawItemsIntoVisualLines(items) {
  const rows = [];
  (items || []).slice().sort((a, b) => {
    const yDiff = Number(b.y || 0) - Number(a.y || 0);
    if (Math.abs(yDiff) > 2.5) return yDiff;
    return Number(a.x || 0) - Number(b.x || 0);
  }).forEach((item) => {
    const y = Number(item.y || 0);
    let row = rows.find((candidate) => Math.abs(candidate.centerY - y) <= Math.max(2.5, Number(item.fontSize || 0) * 0.35));
    if (!row) {
      row = { centerY: y, items: [] };
      rows.push(row);
    }
    row.items.push(item);
    row.centerY = row.items.reduce((sum, entry) => sum + Number(entry.y || 0), 0) / Math.max(1, row.items.length);
  });

  return rows.map((row) => {
    const lineItems = row.items.slice().sort((a, b) => Number(a.x || 0) - Number(b.x || 0));
    const text = normalizeExtractedPdfText(lineItems.map((item) => item.text).join(" "));
    return {
      pageNumber: lineItems[0] ? lineItems[0].pageNumber : 0,
      column: "single",
      text,
      items: lineItems,
      bbox: makeBBox(lineItems),
      centerY: row.centerY,
      avgFontSize: lineItems.reduce((sum, item) => sum + (item.fontSize || 0), 0) / Math.max(1, lineItems.length),
    };
  }).filter((line) => line.text);
}

function recoverCaptionSegmentsFromPageItems(segments, pageItemsByPage) {
  return (segments || []).map((segment) => {
    const text = normalizeExtractedPdfText(segment && segment.sourceText || "");
    if (!segment || segment.type !== "caption" || !isCaptionMarkerText(text) || !segment.bbox) return segment;
    const pageItems = pageItemsByPage.get(Number(segment.pageNumber || 0)) || [];
    const marker = pageItems.find((item) => {
      const itemText = normalizeExtractedPdfText(item.text || "");
      return itemText === text || (isCaptionMarkerText(itemText) && Math.abs(Number(item.y || 0) - Number(segment.bbox.y || 0)) <= 4);
    });
    if (!marker) return segment;
    const markerY = Number(marker.y || 0);
    const markerX = Number(marker.x || segment.bbox.x || 0);
    const markerRight = markerX + Math.max(Number(marker.width || 0), Number(segment.bbox.width || 0));
    const averageFontSize = Math.max(7, Number(marker.height || 0), getPaperSegmentAverageFontSize(segment) || 9);
    const maxCaptionDistance = Math.max(48, averageFontSize * 9);
    // A column-local caption marker (bbox not already spanning ~a full column-and-a-half) must never
    // absorb raw items from the OTHER column: the x-window below (markerRight + up to ~85pt of slack)
    // is wide enough to reach across a typical two-column gutter, which previously let a same-Y body
    // line from the opposite column get merged into the caption's recovered text (garbled, interleaved
    // source). Clamp candidate items to the marker's own column geometry unless the marker itself is
    // already a genuine full-width/cross-column caption (real full-width figures still recover normally).
    const pageWidthForColumns = Number(pageItems[0] && pageItems[0].pageWidth || 0) || getPaperPageWidthFromSegment(segment, 612);
    const columnGeometry = getPaperColumnGeometry(pageWidthForColumns);
    const markerIsFullWidth = Number(segment.bbox.width || 0) > columnGeometry.columnWidth * 1.3;
    let ownColumnBounds = null;
    if (!markerIsFullWidth) {
      const inferredMarkerColumn = inferPaperColumnFromBbox({ ...segment, bbox: { x: markerX, y: markerY, width: Number(marker.width || segment.bbox.width || 0), height: Number(marker.height || segment.bbox.height || 0) } }, pageWidthForColumns);
      if (inferredMarkerColumn === "left") {
        ownColumnBounds = { min: columnGeometry.left.x - 10, max: columnGeometry.left.x + columnGeometry.left.width + 10 };
      } else if (inferredMarkerColumn === "right") {
        ownColumnBounds = { min: columnGeometry.right.x - 10, max: columnGeometry.right.x + columnGeometry.right.width + 10 };
      }
    }
    const captionItems = pageItems.filter((item) => {
      const itemText = normalizeExtractedPdfText(item.text || "");
      const y = Number(item.y || 0);
      const x = Number(item.x || 0);
      const right = x + Number(item.width || 0);
      if (!itemText) return false;
      if (y < markerY - 3 || y - markerY > maxCaptionDistance) return false;
      if (right < markerX - 8 || x > markerRight + Math.max(80, Number(segment.bbox.width || 0) * 0.35)) return false;
      if (ownColumnBounds) {
        const itemCenterX = x + Number(item.width || 0) / 2;
        if (itemCenterX < ownColumnBounds.min || itemCenterX > ownColumnBounds.max) return false;
      }
      if (isImageLabelText(itemText)) return false;
      return true;
    });
    const orderedLines = groupRawItemsIntoVisualLines(captionItems).sort((a, b) => Number(a.centerY || a.bbox && a.bbox.y || 0) - Number(b.centerY || b.bbox && b.bbox.y || 0));
    const lines = [];
    let previousBottom = null;
    for (const line of orderedLines) {
      const lineText = normalizeExtractedPdfText(line.text || "");
      const top = Number(line.bbox && line.bbox.y || line.centerY || 0);
      const bottom = top + Number(line.bbox && line.bbox.height || averageFontSize);
      const gap = previousBottom == null ? 0 : top - previousBottom;
      const cue = isCaptionMarkerText(lineText) || /^(?:Left|Right|Top|Bottom)\s*:/i.test(lineText) || /^[a-z][a-z'\-]*\b/u.test(lineText);
      if (!lines.length && !isCaptionMarkerText(lineText)) continue;
      if (lines.length && (gap > Math.max(16, averageFontSize * 2.0) || !cue)) break;
      lines.push(line);
      previousBottom = Math.max(previousBottom == null ? bottom : previousBottom, bottom);
    }
    const sourceText = makeParagraphSourceText(lines);
    if (sourceText.length <= text.length) return segment;
    const lineBoxes = lines.map((line) => makeLineBoxFromLine({ ...line, column: segment.column || "left" }, segment.id));
    return {
      ...segment,
      column: segment.column || "left",
      lines,
      lineBoxes,
      items: captionItems,
      sourceText,
      previewText: makePreviewText(sourceText),
      bbox: makeBBoxFromLineBoxes(lineBoxes),
    };
  });
}

// Two originally-independent caption segments can end up describing the exact same physical caption
// after recovery (both anchored to the same marker text, e.g. one classified straight from the raw
// paragraph and one re-derived by recoverCaptionSegmentsFromPageItems above). Left alone, both compete
// for the same captionRegion at layout time and the loser gets shoved to an arbitrary position by the
// write planner instead of being recognized as a redundant extraction artifact. Keep exactly one
// authoritative segment per duplicate group — preferring whichever one's column already agrees with
// its own bbox — and drop the rest before they ever reach translation/layout planning.
function suppressDuplicateCaptionSegments(segments, pipelineConfig) {
  if (!isPaperPdfConfig(pipelineConfig)) return segments || [];
  const list = segments || [];
  const suppressed = new Set();
  const byPage = new Map();
  list.forEach((segment, index) => {
    if (!segment || String(segment.type || '') !== 'caption' || !segment.bbox) return;
    const pageNumber = Number(segment.pageNumber || 0);
    if (!byPage.has(pageNumber)) byPage.set(pageNumber, []);
    byPage.get(pageNumber).push(index);
  });
  byPage.forEach((indexes) => {
    for (let i = 0; i < indexes.length; i += 1) {
      if (suppressed.has(indexes[i])) continue;
      const a = list[indexes[i]];
      for (let j = i + 1; j < indexes.length; j += 1) {
        if (suppressed.has(indexes[j])) continue;
        const b = list[indexes[j]];
        const smallerArea = Math.min(
          Math.max(1, Number(a.bbox.width || 0) * Number(a.bbox.height || 0)),
          Math.max(1, Number(b.bbox.width || 0) * Number(b.bbox.height || 0))
        );
        const overlapRatio = bboxOverlapArea(a.bbox, b.bbox) / smallerArea;
        if (overlapRatio < 0.75) continue;
        const textOverlap = getRecoveryTextOverlapRatio(a.sourceText || a.previewText || '', b.sourceText || b.previewText || '');
        if (textOverlap < 0.6) continue;
        const pageWidth = getPaperPageWidthFromSegment(a, 612);
        const aColumnOk = !['left', 'right'].includes(inferPaperColumnFromBbox(a, pageWidth)) || inferPaperColumnFromBbox(a, pageWidth) === String(a.column || '');
        const bColumnOk = !['left', 'right'].includes(inferPaperColumnFromBbox(b, pageWidth)) || inferPaperColumnFromBbox(b, pageWidth) === String(b.column || '');
        let dropIndex;
        if (aColumnOk && !bColumnOk) dropIndex = indexes[j];
        else if (!aColumnOk && bColumnOk) dropIndex = indexes[i];
        else {
          const aLen = String(a.sourceText || '').length;
          const bLen = String(b.sourceText || '').length;
          dropIndex = bLen > aLen ? indexes[i] : indexes[j];
        }
        suppressed.add(dropIndex);
        if (dropIndex === indexes[i]) break;
      }
    }
  });
  if (!suppressed.size) return list;
  return list.filter((_, index) => !suppressed.has(index));
}

function buildRecoveryBodySegment(lines, segId) {
  const pageNumber = Number((lines[0] && lines[0].pageNumber) || 0);
  const column = (lines[0] && lines[0].column) || "single";
  const lineBoxes = lines.map((line) => makeLineBoxFromLine(line, segId));
  const bbox = makeBBoxFromLineBoxes(lineBoxes);
  const sourceText = makeParagraphSourceText(lines);
  const sourceLineIds = (lines || []).map((line) => makeSourceLineId(line)).filter(Boolean);
  return {
    id: segId,
    type: "body",
    status: "pending",
    pageNumber,
    firstLinePageNumber: pageNumber,
    lastLinePageNumber: pageNumber,
    column,
    sourceText,
    previewText: makePreviewText(sourceText),
    lines,
    lineBoxes,
    items: lines.flatMap((l) => l.items || []),
    bbox,
    uncoveredLineRecovery: true,
    uncoveredLineRecoveryReason: "source_line_coverage_audit",
    recoveredFormulaLine: lines.some((l) => isFormulaLikeLine(l)),
    sourceLineIds,
    classificationReason: "uncovered_source_line_recovery",
    mergeReason: "",
    continuation: false,
    continuationFrom: "",
    previousSegmentId: "",
    nextSegmentId: "",
    crossedPageBoundary: false,
    crossedColumnBoundary: false,
    sourceLineNumbers: [],
    zoneType: "",
    imageRegionOverlap: false,
    referenceModeApplied: false,
    warnings: ["recovered_from_coverage_audit"],
  };
}

function createSegmentIdAllocator(existingSegments) {
  const usedIds = new Set();
  let maxNum = 0;
  (existingSegments || []).forEach((seg) => {
    const id = String(seg.id || '');
    if (id) usedIds.add(id);
    const m = id.match(/^seg-(\d+)$/);
    if (m) maxNum = Math.max(maxNum, parseInt(m[1], 10));
  });
  const maxBefore = maxNum;
  let allocated = 0;
  return {
    reserve(id) {
      const value = String(id || "");
      if (!value) return false;
      const wasUnused = !usedIds.has(value);
      usedIds.add(value);
      const match = value.match(/^seg-(\d+)$/);
      if (match) maxNum = Math.max(maxNum, parseInt(match[1], 10));
      return wasUnused;
    },
    next() {
      let id;
      do {
        maxNum += 1;
        id = `seg-${maxNum}`;
      } while (usedIds.has(id));
      usedIds.add(id);
      allocated += 1;
      return id;
    },
    get maxBefore() { return maxBefore; },
    get maxAfter() { return maxNum; },
    get allocatedCount() { return allocated; },
  };
}

function isPaperCaptionOwnershipContinuationText(text) {
  const value = normalizeExtractedPdfText(text || '');
  if (!value || isBodyStartText(value)) return false;
  if (/^(?:Left|Right|Top|Bottom)\s*:/i.test(value)) return true;
  if (/^(?:the\s+)?(?:black|red|white)\s+(?:circle|contour|line|curve|solid|dashed)/i.test(value)) return true;
  if (/^(?:the\s+)?(?:primary|secondary)\b/i.test(value) || /^smaller,?\s+secondary\b/i.test(value)) return true;
  if (/^(?:right|left|top|bottom)\s+(?:panel|image|spectrum|zoom)/i.test(value)) return true;
  if (/^local\s+\S*\s*(?:error\s+)?envelope\b/i.test(value)) return true;
  if (/^(?:which|that)\s+(?:is|are|shows?|indicates?|marks?)\b/i.test(value)) return true;
  if (/^(?:showing|indicating|marking|corresponding\s+to)\b/i.test(value)) return true;
  if (/^(?:represents?|represented|denotes?|denoted|indicates?|indicated|marks?|marked|traces?|traced|illustrates?|illustrated|displays?|displayed)\b/i.test(value)) return true;
  if (/^(?:″|''|″)/.test(value)) return true;
  return false;
}

function isPaperRawLineOwnedByCaptionSource(line, captions) {
  if (!line || !line.bbox) return false;
  const lineText = normalizeExtractedPdfText(line.text || '');
  if (!lineText) return false;
  const lineBox = { x: Number(line.bbox.x || 0), y: Number(line.bbox.y || 0), width: Number(line.bbox.width || 0), height: Number(line.bbox.height || 0) };
  return (captions || []).some((caption) => {
    if (!caption || !caption.bbox || String(caption.type || '') !== 'caption') return false;
    const finalizedRawLines = caption.captionGroupArtifact && caption.captionGroupArtifact.value &&
      Array.isArray(caption.captionGroupArtifact.value.rawLines) ? caption.captionGroupArtifact.value.rawLines : [];
    if (finalizedRawLines.some((owned) => {
      const ownedBox = owned && (owned.bbox || owned);
      const ownedText = normalizeExtractedPdfText(owned && owned.text || '');
      if (!ownedBox || !ownedText) return false;
      const textMatches = ownedText.toLowerCase() === lineText.toLowerCase() ||
        getRecoveryTextOverlapRatio(lineText, ownedText) > 0.82 || getRecoveryTextOverlapRatio(ownedText, lineText) > 0.82;
      return textMatches && (bboxOverlapRatio(lineBox, ownedBox) > 0.72 || bboxOverlapRatio(ownedBox, lineBox) > 0.72);
    })) return true;
    const captionText = normalizeExtractedPdfText(caption.sourceText || caption.previewText || '');
    if (getRecoveryTextOverlapRatio(lineText, captionText) > 0.82) return true;
    if ((caption.lineBoxes || []).some((box) => bboxOverlapRatio(lineBox, box) > 0.72 || bboxOverlapRatio(box, lineBox) > 0.72)) return true;
    if (!isPaperCaptionOwnershipContinuationText(lineText)) return false;
    const captionBottom = Number(caption.bbox.y || 0) + Number(caption.bbox.height || 0);
    const lineCenterY = lineBox.y + lineBox.height / 2;
    const averageFont = Math.max(7, getPaperSegmentAverageFontSize(caption) || lineBox.height || 9);
    if (lineCenterY < Number(caption.bbox.y || 0) - 2 || lineCenterY > captionBottom + averageFont * 1.8) return false;
    return bboxHorizontalOverlapRatio(lineBox, caption.bbox) > 0.2 || Number(caption.bbox.width || 0) > 420;
  });
}

function eliminateCaptionOwnedBodySourceLineDuplicates(segments) {
  const list = Array.isArray(segments) ? segments : [];
  const ownedLines = [];
  list.forEach((segment) => {
    const group = segment && segment.captionGroupArtifact && segment.captionGroupArtifact.value;
    if (!group || String(group.canonicalSegmentId || '') !== String(segment.id || '')) return;
    (Array.isArray(group.rawLines) ? group.rawLines : []).forEach((line) => {
      const box = line && (line.bbox || line);
      const text = normalizeExtractedPdfText(line && line.text || '');
      if (!box || !text) return;
      ownedLines.push({
        captionGroupId: String(group.groupId || ''),
        canonicalSegmentId: String(group.canonicalSegmentId || ''),
        text,
        box: { x: Number(box.x || 0), y: Number(box.y || 0), width: Number(box.width || 0), height: Number(box.height || 0) },
      });
    });
  });
  const matchesOwnedCaptionLine = (text, box) => {
    const value = normalizeExtractedPdfText(text || '');
    if (!value || !box) return null;
    return ownedLines.find((owned) => {
      const textMatches = owned.text.toLowerCase() === value.toLowerCase() ||
        getRecoveryTextOverlapRatio(value, owned.text) > 0.82 || getRecoveryTextOverlapRatio(owned.text, value) > 0.82;
      return textMatches && (bboxOverlapRatio(box, owned.box) > 0.72 || bboxOverlapRatio(owned.box, box) > 0.72);
    }) || null;
  };
  const eliminatedSegmentIds = [];
  const trimmedSegmentIds = [];
  let eliminatedLineCount = 0;
  const output = [];
  list.forEach((segment) => {
    if (!segment || String(segment.type || '') === 'caption' || segment.captionGroupArtifact) {
      output.push(segment);
      return;
    }
    const lineBoxes = Array.isArray(segment.lineBoxes) ? segment.lineBoxes : [];
    const lines = Array.isArray(segment.lines) ? segment.lines : [];
    const entries = lineBoxes.length ? lineBoxes.map((box, index) => ({
      index,
      box,
      text: getSegmentLineText(lines[index]) || normalizeExtractedPdfText(box && (box.sourceLineText || box.text) || ''),
    })) : [{ index: 0, box: segment.bbox, text: normalizeExtractedPdfText(segment.sourceText || segment.previewText || '') }];
    const ownedIndexes = new Set(entries.filter((entry) => matchesOwnedCaptionLine(entry.text, entry.box)).map((entry) => entry.index));
    if (!ownedIndexes.size) {
      output.push(segment);
      return;
    }
    eliminatedLineCount += ownedIndexes.size;
    const remainingIndexes = entries.filter((entry) => !ownedIndexes.has(entry.index)).map((entry) => entry.index);
    if (!remainingIndexes.length) {
      eliminatedSegmentIds.push(String(segment.id || ''));
      return;
    }
    const remainingLines = lines.length ? remainingIndexes.map((index) => lines[index]).filter(Boolean) : [];
    const remainingLineBoxes = lineBoxes.length ? remainingIndexes.map((index) => lineBoxes[index]).filter(Boolean) : [];
    const sourceText = remainingLines.length
      ? makeParagraphSourceText(remainingLines.map((line) => ({ text: getSegmentLineText(line) })))
      : makeParagraphSourceText(remainingLineBoxes.map((line) => ({ text: normalizeExtractedPdfText(line && (line.sourceLineText || line.text) || '') })));
    if (!sourceText || !remainingLineBoxes.length) {
      eliminatedSegmentIds.push(String(segment.id || ''));
      return;
    }
    trimmedSegmentIds.push(String(segment.id || ''));
    output.push({
      ...segment,
      sourceText,
      previewText: makePreviewText(sourceText),
      lines: remainingLines,
      lineBoxes: remainingLineBoxes,
      bbox: makeBBoxFromLineBoxes(remainingLineBoxes),
      captionOwnedSourceLineDuplicateTrimmed: true,
    });
  });
  return { segments: output, eliminatedSegmentIds, trimmedSegmentIds, eliminatedLineCount };
}

// PDF.js reports extracted text-line y at the text baseline, while drawRectangle expects a
// top-origin visual box. Raw recovered lines intentionally preserve the extraction geometry for
// source identity and caption-region authority, so convert that baseline geometry only at the
// source-mask boundary. This keeps the authoritative artifacts immutable while ensuring the mask
// covers the glyph ascent and descent instead of starting below most of the visible characters.
function makeRawSourceGlyphMaskBox(box) {
  const source = box || {};
  const fontSize = Math.max(1, Number(source.fontSize || source.height || 0));
  const ascent = fontSize * 0.85;
  const descent = fontSize * 0.25;
  const horizontalPad = Math.max(0.75, fontSize * 0.08);
  return {
    x: Number((Number(source.x || 0) - horizontalPad).toFixed(3)),
    y: Number((Number(source.y || 0) - ascent).toFixed(3)),
    width: Number((Number(source.width || 0) + horizontalPad * 2).toFixed(3)),
    height: Number((ascent + descent).toFixed(3)),
  };
}

const PDF_SEGMENT_IDENTITY_SCHEMA_VERSION = "pdf-segment-identity-v1";

function materializeSegmentIdentity(segment, segmentId, origin) {
  const id = String(segmentId || "");
  return {
    ...segment,
    id,
    segmentIdentity: Object.freeze({
      schemaVersion: PDF_SEGMENT_IDENTITY_SCHEMA_VERSION,
      segmentId: id,
      origin: String(origin || "unknown"),
      parentSegmentId: String(segment && segment.splitFromSegmentId || ""),
    }),
    lineBoxes: (segment && segment.lineBoxes || []).map((line) => ({ ...line, segmentId: id })),
  };
}

function assertUniqueSegmentIds(segments) {
  const seen = new Map();
  const seenObjects = new Map();
  const duplicates = [];
  const missingSegmentIds = [];
  const duplicateObjectReferences = [];
  const identityMismatches = [];
  const lineBoxIdentityMismatches = [];
  (segments || []).forEach((seg, index) => {
    const id = String(seg.id || '');
    if (seg && typeof seg === "object") {
      if (seenObjects.has(seg)) duplicateObjectReferences.push({ firstIndex: seenObjects.get(seg), secondIndex: index, id });
      else seenObjects.set(seg, index);
    }
    if (!id) {
      missingSegmentIds.push({ index, pageNumber: seg && seg.pageNumber, textPreview: String(seg && seg.sourceText || "").slice(0, 80) });
      return;
    }
    if (seg.segmentIdentity && (String(seg.segmentIdentity.segmentId || "") !== id || String(seg.segmentIdentity.schemaVersion || "") !== PDF_SEGMENT_IDENTITY_SCHEMA_VERSION)) {
      identityMismatches.push({ index, id, segmentIdentity: seg.segmentIdentity });
    }
    (seg.lineBoxes || []).forEach((line, lineIndex) => {
      if (String(line && line.segmentId || "") !== id) lineBoxIdentityMismatches.push({ index, lineIndex, id, lineSegmentId: String(line && line.segmentId || "") });
    });
    if (seen.has(id)) {
      duplicates.push({
        id,
        first: seen.get(id),
        second: { pageNumber: seg.pageNumber, type: seg.type, bbox: seg.bbox, textPreview: String(seg.sourceText || '').slice(0, 80) },
      });
    } else {
      seen.set(id, { pageNumber: seg.pageNumber, type: seg.type, bbox: seg.bbox, textPreview: String(seg.sourceText || '').slice(0, 80) });
    }
  });
  return {
    unique: duplicates.length === 0 && missingSegmentIds.length === 0 && duplicateObjectReferences.length === 0 && identityMismatches.length === 0 && lineBoxIdentityMismatches.length === 0,
    duplicateSegmentIdCount: duplicates.length,
    duplicateSegmentIds: [...new Set(duplicates.map((d) => d.id))],
    duplicateSegmentDetails: duplicates,
    missingSegmentIdCount: missingSegmentIds.length,
    missingSegmentIds,
    duplicateObjectReferenceCount: duplicateObjectReferences.length,
    duplicateObjectReferences,
    identityMismatchCount: identityMismatches.length,
    identityMismatches,
    lineBoxIdentityMismatchCount: lineBoxIdentityMismatches.length,
    lineBoxIdentityMismatches,
  };
}

function assertSegmentIdentityContractOrThrow(segments, stage) {
  const audit = assertUniqueSegmentIds(segments);
  if (audit.unique) return audit;
  const error = new Error(`PDF segment identity contract failed at ${String(stage || "unknown")}.`);
  error.code = "PDF_SEGMENT_IDENTITY_CONTRACT_FAILED";
  error.stage = String(stage || "unknown");
  error.details = audit;
  throw error;
}

function makeSourceLineId(line) {
  if (!line) return "";
  const box = line.bbox || {};
  return [
    Number(line.pageNumber || 0),
    String(line.column || "single"),
    Number(box.x || 0).toFixed(2),
    Number(box.y || 0).toFixed(2),
    normalizeExtractedPdfText(line.text || "").slice(0, 80),
  ].join("|");
}

function normalizeRecoveryCompareText(text) {
  return normalizeExtractedPdfText(text || "")
    .toLowerCase()
    .replace(/[\u00ad]/g, "")
    .replace(/([a-z])-\s+([a-z])/g, "$1$2")
    .replace(/[^a-z0-9\u3400-\u9fff]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function makeRecoveryNgrams(text, size = 5) {
  const words = normalizeRecoveryCompareText(text).split(/\s+/).filter(Boolean);
  if (words.length < size) return new Set(words.length ? [words.join(" ")] : []);
  const grams = new Set();
  for (let i = 0; i <= words.length - size; i += 1) {
    grams.add(words.slice(i, i + size).join(" "));
  }
  return grams;
}

function getRecoveryTextOverlapRatio(candidateText, segmentText) {
  const candidate = makeRecoveryNgrams(candidateText);
  const existing = makeRecoveryNgrams(segmentText);
  if (!candidate.size || !existing.size) return 0;
  let hits = 0;
  candidate.forEach((gram) => { if (existing.has(gram)) hits += 1; });
  return hits / Math.max(1, candidate.size);
}

function getRecoveryBboxOverlapRatio(candidateBox, segmentBox) {
  if (!candidateBox || !segmentBox) return 0;
  const candidateArea = Math.max(1, Number(candidateBox.width || 0) * Number(candidateBox.height || 0));
  return bboxOverlapArea(candidateBox, segmentBox) / candidateArea;
}

function getSegmentSourceLineIds(segment) {
  const ids = new Set(Array.isArray(segment && segment.sourceLineIds) ? segment.sourceLineIds : []);
  (segment && segment.lines || []).forEach((line) => ids.add(makeSourceLineId(line)));
  (segment && segment.lineBoxes || []).forEach((line) => ids.add(makeSourceLineId({
    pageNumber: line.pageNumber || segment.pageNumber,
    column: line.column || segment.column,
    bbox: { x: line.x, y: line.y, width: line.width, height: line.height },
    text: line.sourceLineText || line.text,
  })));
  return Array.from(ids).filter(Boolean);
}

function isDuplicateRecoveryCandidate(candidate, pageSegments) {
  const candidateIds = new Set(getSegmentSourceLineIds(candidate));
  const duplicateLineIds = [];
  for (const segment of (pageSegments || [])) {
    const existingIds = getSegmentSourceLineIds(segment);
    const sharedIds = existingIds.filter((id) => candidateIds.has(id));
    if (sharedIds.length) {
      duplicateLineIds.push(...sharedIds);
      return { duplicate: true, reason: "source_line_id_overlap", duplicateLineIds, duplicateWithSegmentId: String(segment.id || "") };
    }
    if (String(segment.type || "") !== "body" && String(segment.type || "") !== "abstract") continue;
    const textOverlap = getRecoveryTextOverlapRatio(candidate.sourceText || "", segment.sourceText || "");
    const boxOverlap = getRecoveryBboxOverlapRatio(candidate.bbox, segment.bbox);
    if (textOverlap > 0.55 || boxOverlap > 0.35) {
      return {
        duplicate: true,
        reason: textOverlap > 0.55 ? "normalized_ngram_overlap" : "bbox_overlap",
        textOverlap: Number(textOverlap.toFixed(4)),
        bboxOverlap: Number(boxOverlap.toFixed(4)),
        duplicateWithSegmentId: String(segment.id || ""),
      };
    }
  }
  return { duplicate: false };
}

// Returns {inZone: bool, reason: string} — true if a recovery candidate's bbox falls inside
// a reference/licenseText/preserve-type zone on the same page. Checked against surrounding
// segment types and their spatial proximity (1.5 lineHeight tolerance).
function isRecoveryCandidateInPreserveZone(candidate, pageSegs) {
  const cbbox = candidate.bbox || {};
  const cy0 = Number(cbbox.y || 0);
  const cy1 = cy0 + Number(cbbox.height || 0);
  const cx0 = Number(cbbox.x || 0);
  const cx1 = cx0 + Number(cbbox.width || 0);
  const lineH = Math.max(8, Number(cbbox.height || 12));
  const preserveTypes = new Set(['reference', 'licenseText', 'footer', 'header', 'pageNumber']);
  const preserveSegs = (pageSegs || []).filter((s) =>
    preserveTypes.has(String(s.type || '')) || Boolean(s.referenceModeApplied)
  );
  if (!preserveSegs.length) return { inZone: false };

  // Direct spatial overlap with a preserve segment (with generous tolerance)
  for (const s of preserveSegs) {
    const sb = s.bbox || {};
    const sy0 = Number(sb.y || 0) - lineH * 1.5;
    const sy1 = sy0 + Number(sb.height || 0) + lineH * 3;
    const sx0 = Number(sb.x || 0) - 12;
    const sx1 = sx0 + Number(sb.width || 0) + 24;
    if (cy0 < sy1 && cy1 > sy0 && cx1 > sx0 && cx0 < sx1) {
      return { inZone: true, reason: 'overlaps_preserve_segment', preserveType: String(s.type || '') };
    }
  }

  // Neighbor density: if >= 50% of nearby segs (within 3 lineHeights) are preserve types, reject
  const nearbySegs = (pageSegs || []).filter((s) => {
    const sb = s.bbox || {};
    return Math.abs(Number(sb.y || 0) - cy0) <= lineH * 3;
  });
  if (nearbySegs.length >= 2) {
    const preserveNearby = nearbySegs.filter((s) =>
      preserveTypes.has(String(s.type || '')) || Boolean(s.referenceModeApplied)
    );
    if (preserveNearby.length / nearbySegs.length >= 0.5) {
      // Determine dominant preserve type for split reporting
      const typeCounts = {};
      preserveNearby.forEach((s) => {
        const t = s.referenceModeApplied ? 'reference' : String(s.type || '');
        typeCounts[t] = (typeCounts[t] || 0) + 1;
      });
      const dominantType = Object.keys(typeCounts).reduce((a, b) => typeCounts[a] >= typeCounts[b] ? a : b, '');
      return { inZone: true, reason: 'neighbor_density_preserve', preserveType: dominantType };
    }
  }
  return { inZone: false };
}

// True if text is a DOI citation line or pure numeric DOI fragment not worth standalone recovery.
function isDoiLikeOrDanglingRecoveryText(text) {
  if (!text) return false;
  const t = String(text).trim();
  if (/^doi:/i.test(t)) return true;
  // Full DOI with slash: 10.XXXX/...
  if (/10\.\d{4,9}\//.test(t)) return true;
  // Dangling numeric-only fragment shorter than 20 chars (e.g. "10.25574." without alpha)
  if (t.length <= 20 && /^[\d\.\-\/:\s]+$/.test(t) && /^10\./.test(t)) return true;
  return false;
}

function isSimplePdfConfig(config) {
  return Boolean(config && (config.mode === "simple_pdf" || config.mode === "legacy_simple_pdf"));
}

function isSimplePdfV2Config(config) {
  return Boolean(config && config.mode === "simple_pdf" && config.pipelineBranch === "simple_pdf_simplified_core");
}

function isLegacySimplePdfConfig(config) {
  return Boolean(config && config.mode === "legacy_simple_pdf");
}

function isSimplePdfAllowedPreserveType(type) {
  return ["header", "footer", "pageNumber", "noise"].includes(String(type || ""));
}

function getSimpleLineTextLength(text) {
  const value = normalizeExtractedPdfText(text || "").replace(/\s+/g, "");
  const cjkCount = (value.match(/[\u3400-\u9fff]/g) || []).length;
  return cjkCount ? cjkCount : value.length;
}

function isSimpleStrongSentenceEnd(text) {
  return /[。！？；：.!?;:]$/.test(normalizeExtractedPdfText(text || ""));
}

function isSimpleFirstPageTitleCandidate(segment) {
  if (!segment || Number(segment.pageNumber || 0) !== 1 || isSimplePdfAllowedPreserveType(segment.type)) return false;
  const lines = segment.lines || [];
  if (!lines.length) return false;
  const firstLine = lines[0];
  const firstText = getSegmentLineText(firstLine);
  const nextText = getSegmentLineText(lines[1]) || "";
  if (!firstText || isSimpleStrongSentenceEnd(firstText)) return false;
  if (getSimpleLineTextLength(firstText) > 24 && !/^[A-Za-z0-9 ,:'"()-]{1,120}$/.test(firstText)) return false;
  const firstBox = segment.lineBoxes && segment.lineBoxes[0] || firstLine.bbox || {};
  const y = Number(firstBox.y || 0);
  if (y > 180) return false;
  if (!nextText || getSimpleLineTextLength(nextText) < 18) return false;
  return true;
}

function splitSimpleFirstPageTitle(segments) {
  let titleApplied = false;
  const output = [];
  (segments || []).forEach((segment) => {
    if (!titleApplied && isSimpleFirstPageTitleCandidate(segment)) {
      titleApplied = true;
      const title = makeSegmentFromParts(segment, [0], "title", "single");
      title.classificationReason = "simple_first_page_title";
      title.simpleParagraphSplitReason = "simple_first_page_title";
      title.simpleFirstLineTitleCandidate = true;
      const restIndexes = (segment.lines || []).slice(1).map((_, index) => index + 1);
      output.push(title);
      if (restIndexes.length) {
        const body = makeSegmentFromParts(segment, restIndexes, "body", "single");
        body.classificationReason = "simple_pdf_document_flow";
        body.simpleParagraphSplitReason = "simple_title_body_remainder";
        output.push(body);
      }
      return;
    }
    output.push(segment);
  });
  return output.filter((segment) => segment && segment.sourceText);
}

function isSimpleNewSectionStart(text) {
  const value = normalizeExtractedPdfText(text || "");
  return /^(第[一二三四五六七八九十\d]+[章节篇]|[一二三四五六七八九十]+[、.]|\d+(?:\.\d+)*\s+|Chapter\b|Section\b)/i.test(value);
}

function hasSimpleParagraphIndent(segment) {
  const lineBoxes = segment && segment.lineBoxes || [];
  if (lineBoxes.length < 2) return false;
  const firstX = Number(lineBoxes[0].x || 0);
  const nextX = Number(lineBoxes[1].x || 0);
  return firstX - nextX > 12;
}

function shouldMergeSimpleCrossPageParagraph(previous, next) {
  if (!previous || !next) return false;
  if (previous.type !== "body" || next.type !== "body") return false;
  if (Number(previous.pageNumber || 0) + 1 !== Number(next.pageNumber || 0)) return false;
  const previousLines = previous.lines || [];
  const nextLines = next.lines || [];
  const previousText = getSegmentLineText(previousLines[previousLines.length - 1]) || normalizeExtractedPdfText(previous.sourceText || "");
  const nextText = getSegmentLineText(nextLines[0]) || normalizeExtractedPdfText(next.sourceText || "");
  if (!previousText || !nextText) return false;
  if (isSimpleStrongSentenceEnd(previousText)) return false;
  if (isSimpleNewSectionStart(nextText)) return false;
  if (hasSimpleParagraphIndent(next)) return false;
  return true;
}

function mergeSimpleCrossPageParagraphs(segments) {
  const output = [];
  (segments || []).forEach((segment) => {
    const previous = output[output.length - 1];
    if (shouldMergeSimpleCrossPageParagraph(previous, segment)) {
      if (mergeSegments(previous, segment, "body", "single")) {
        previous.crossedPageBoundary = true;
        previous.mergeReason = "simple_cross_page_paragraph_continuation";
        previous.simpleParagraphSplitReason = "simple_cross_page_paragraph_continuation";
        previous.simpleCrossPageContinuationCandidate = true;
        previous.firstLinePageNumber = previous.firstLinePageNumber || Number(previous.pageNumber || 0);
        previous.lastLinePageNumber = Number(segment.pageNumber || 0);
        previous.pageNumber = previous.firstLinePageNumber;
        return;
      }
    }
    output.push(segment);
  });
  return output;
}




function assertSimpleBlockClean(blocks) {
  var forbidden = ["bbox","writeBox","writeBbox","lineBoxes","lines","column","layoutType","maskApplied","writeApplied","zoneType","referenceMode","referenceModeApplied","imageRegion","imageRegionOverlap","formulaLinePreserve","captionRegion","paperSecondPassSplit","columnReassignedByBbox"];
  (blocks || []).forEach(function(block) {
    forbidden.forEach(function(f) { if (f in block) throw new Error("simple block has forbidden field: " + f + " in " + (block.id || "?")); });
  });
}

function assertSimpleMainBoundary(blocks) {
  // Boundary contract for simple_pdf main path:
  // - runSimplePdfSimplifiedCore may use shared text extraction/line building helpers only.
  // - It must not call paper helpers: detectPageColumns, inferImageRegionsForPage,
  //   filterImageRegionLines, detectPaperPageZones, applyReferenceMode,
  //   applyOversizedPaperBodySplits, applyImageRegionSegmentationConstraints,
  //   repairPaperSegmentColumnsByBbox, clipPaperWriteBoxByImageRegions.
  // - simpleExportDocumentFlowPdf must not read bbox, lineBoxes, column, writeBox,
  //   maskApplied, zoneType, referenceMode, formulaLinePreserve, or imageRegion.
  assertSimpleBlockClean(blocks || []);
  return true;
}
function simpleAssertSimpleBlockBoundary(blocks) {
  const forbidden = ["bbox", "column", "writeBox", "writeBbox", "maskApplied", "writeApplied", "zoneType", "referenceMode", "referenceModeApplied", "imageRegion", "imageRegionOverlap", "formulaLinePreserve", "paperSecondPassSplit", "writeBoxClippedByColumn", "captionRegion", "oversizedBody", "bodyCrossColumn"];
  const offendingBlockIds = [];
  (blocks || []).forEach((block) => {
    if (forbidden.some((field) => Object.prototype.hasOwnProperty.call(block, field))) offendingBlockIds.push(String(block.id || ""));
  });
  return { simpleBoundaryViolation: offendingBlockIds.length > 0, offendingBlockIds };
}

function postProcessSimplePdfSegments(segments, pipelineConfig) {
  if (!isSimplePdfConfig(pipelineConfig)) return segments || [];
  const splitSegments = mergeSimpleCrossPageParagraphs(splitSimpleFirstPageTitle(applyNaturalParagraphSplits(segments || [])));
  const output = [];
  splitSegments.forEach((segment) => {
    const sourceType = String(segment && segment.type || "body");
    const type = sourceType === "title" ? "title" : (isSimplePdfAllowedPreserveType(sourceType) ? sourceType : "body");
    if (type === "body" && isNoisePdfLine({ text: segment.sourceText, bbox: segment.bbox, avgFontSize: 8, items: segment.items || [] })) {
      if (/^\d+$/.test(normalizeExtractedPdfText(segment.sourceText || ""))) currentPdfIgnoredPageNumberLines += 1;
      currentPdfIgnoredNoiseLines += 1;
      return;
    }
    output.push({
      ...segment,
      type,
      column: "single",
      classificationReason: String(segment && segment.classificationReason || "simple_pdf_document_flow"),
      status: "pending",
      simpleModePipelineBranch: "simple_document_flow",
    });
  });
  return output.map((segment, index) => {
    const id = `seg-${index + 1}`;
    return {
      ...segment,
      id,
      lineBoxes: (segment.lineBoxes || []).map((line) => ({ ...line, segmentId: id, column: "single" })),
      lines: (segment.lines || []).map((line) => ({ ...line, column: "single" })),
    };
  });
}

function postProcessPdfSegments(segments, pipelineConfig) {
  if (isSimplePdfV2Config(pipelineConfig)) {
    throw new Error("simple_pdf_v2 must use runSimplePdfPipeline, not postProcessPdfSegments");
  }
  if (isLegacySimplePdfConfig(pipelineConfig)) {
    return postProcessSimplePdfSegments(segments, pipelineConfig);
  }

  const expanded = [];
  segments.forEach((segment) => expanded.push(...splitTopMatterSegment(segment)));

  const output = [];
  let abstractBuffer = null;
  expanded.forEach((segment) => {
    const firstText = getSegmentLineText(segment.lines && segment.lines[0]) || normalizeExtractedPdfText(segment.sourceText || "");
    if (segment.type === "abstract" && /^ABSTRACT$/i.test(firstText)) {
      if (abstractBuffer) {
        output.push(abstractBuffer);
        abstractBuffer = null;
      }
      output.push({ ...segment, type: "abstract-title", column: "single" });
      abstractBuffer = { ...segment, id: "", type: "abstract", column: "single", sourceText: "", previewText: "", lines: [], lineBoxes: [], items: [], bbox: { x: 0, y: 0, width: 0, height: 0 } };
      return;
    }
    if (segment.type === "keywords") {
      if (abstractBuffer && abstractBuffer.lines.length) output.push(abstractBuffer);
      abstractBuffer = null;
      output.push({ ...segment, type: "keywords", column: "single" });
      return;
    }
    if (abstractBuffer) {
      const crossedPage = abstractBuffer.pageNumber && segment.pageNumber !== abstractBuffer.pageNumber;
      const crossedColumn = abstractBuffer.column && segment.column !== abstractBuffer.column;
      const shortHyphenatedColumnBody = segment.type === "body" &&
        (abstractBuffer.lines || []).length >= 5 &&
        firstText.length < 90 &&
        /-$/.test(firstText) &&
        segment.bbox &&
        Number(segment.bbox.width || 0) < 280;
      if (crossedPage || crossedColumn || shortHyphenatedColumnBody || segment.type === "heading" || segment.type === "caption" || isAbstractStopText(firstText)) {
        if (abstractBuffer.lines.length) output.push(abstractBuffer);
        abstractBuffer = null;
        output.push(segment);
      } else {
        if (!mergeSegments(abstractBuffer, segment, "abstract", "single")) {
          if (abstractBuffer.lines.length) output.push(abstractBuffer);
          abstractBuffer = null;
          output.push(segment);
        }
      }
      return;
    }
    output.push(segment);
  });
  if (abstractBuffer && abstractBuffer.lines.length) output.push(abstractBuffer);

  let paperSegments = output;
  if (pipelineConfig && pipelineConfig.enableTitleZoneClassification) {
    paperSegments = applyTitleZoneClassification(paperSegments);
  }
  paperSegments = applyHeadingLeadSplits(paperSegments);
  paperSegments = applyHeadingBodyMixedSplits(paperSegments);
  paperSegments = applyHeadingContinuationMerges(paperSegments);
  paperSegments = applyBodyContinuationMerges(paperSegments);
  paperSegments = applyNaturalParagraphSplits(paperSegments);
  paperSegments = applyAbstractBoundaryTrims(paperSegments);
  paperSegments = applyFirstPageAbstractContinuationRepair(paperSegments, pipelineConfig);
  paperSegments = applyOversizedPaperBodySplits(paperSegments, pipelineConfig);
  if (pipelineConfig && pipelineConfig.enableCaptionClassification) {
    paperSegments = applyCaptionBoundaryCleanup(paperSegments);
    paperSegments = applyCaptionFragmentMerges(paperSegments);
  }
  paperSegments = applyImageRegionSegmentationConstraints(paperSegments, pipelineConfig);
  paperSegments = applyOversizedPaperBodySplits(paperSegments, pipelineConfig);
  paperSegments = applySegmentNoiseTyping(paperSegments);
  if (pipelineConfig && pipelineConfig.enableReferencePreserve) {
    paperSegments = applyReferenceTypingAndOrdering(paperSegments);
    paperSegments = applyReferenceMode(paperSegments, pipelineConfig);
  }
  let cleaned = enforcePageAndColumnBoundaries(applyCrossPageContinuations(paperSegments));
  cleaned = repairPaperSegmentColumnsByBbox(cleaned, pipelineConfig);
  cleaned = applyImageRegionSegmentationConstraints(cleaned, pipelineConfig);
  cleaned = applyOversizedPaperBodySplits(cleaned, pipelineConfig).map((segment) => ({
    ...segment,
    finalSplitPass: Boolean(segment.splitReason === "paper_oversized_body_second_pass" || segment.paperSecondPassSplitApplied),
    finalOversizedSplitApplied: Boolean(segment.splitReason === "paper_oversized_body_second_pass" || segment.paperSecondPassSplitApplied),
    finalOversizedSplitReason: segment.splitReason === "paper_oversized_body_second_pass" ? "final_column_repair_oversized_split" : String(segment.finalOversizedSplitReason || ""),
  }));
  cleaned = repairPaperSegmentColumnsByBbox(cleaned, pipelineConfig);
  cleaned = applyPaperSourceTextRepairs(cleaned, pipelineConfig);
  cleaned = auditPaperImageTextPreserveRisk(cleaned, { demote: true }).segments;

  return cleaned.map((segment, index) => {
    const id = `seg-${index + 1}`;
    return materializeSegmentIdentity({
      ...segment,
      continuationFrom: segment.continuation && index > 0 ? `seg-${index}` : segment.continuationFrom,
      status: "pending",
    }, id, "post_process_finalization");
  }).filter((segment) => {
    if (segment.type !== "body") return true;
    if (isNoisePdfLine({ text: segment.sourceText, bbox: segment.bbox, avgFontSize: 8, items: segment.items || [] })) {
      if (/^\d+$/.test(normalizeExtractedPdfText(segment.sourceText || ""))) {
        currentPdfIgnoredPageNumberLines += 1;
      }
      currentPdfIgnoredNoiseLines += 1;
      return false;
    }
    return true;
  });
}

function logPdfSegmentationDebug(totalPages, lines, segments, marginIgnoredLines, ignoredNoiseLines, ignoredPageNumberLines, imageRegionsByPage, ignoredImageTextLines, ignoredImageTextPreviews) {
  const perPage = {};
  const bodySegments = segments.filter((segment) => (segment.type || "body") === "body");
  const headerSegments = segments.filter((segment) => segment.type === "header").length;
  const titleSegments = segments.filter((segment) => segment.type === "title").length;
  const authorSegments = segments.filter((segment) => segment.type === "author").length;
  const affiliationSegments = segments.filter((segment) => segment.type === "affiliation").length;
  const headingSegments = segments.filter((segment) => segment.type === "heading").length;
  const abstractSegments = segments.filter((segment) => segment.type === "abstract").length;
  const keywordSegments = segments.filter((segment) => segment.type === "keywords").length;
  const captionSegments = segments.filter((segment) => segment.type === "caption").length;
  const referenceSegments = segments.filter((segment) => segment.type === "reference").length;
  const referenceHeading = segments.find((segment) => segment.referenceHeading || isPaperReferenceHeadingText(segment.sourceText || ""));
  const referenceModeStartPage = referenceHeading ? referenceHeading.pageNumber : null;
  const continuationSegments = segments.filter((segment) => segment.continuation).length;
  const bodyLineBoxCounts = bodySegments.map((segment) => Array.isArray(segment.lineBoxes) ? segment.lineBoxes.length : 0);
  const bodySegmentsLessThan3Lines = bodyLineBoxCounts.filter((count) => count < 3).length;
  const bodySegmentsMoreThan12Lines = bodyLineBoxCounts.filter((count) => count > 12).length;
  const singleColumnSegments = segments.filter((segment) => (segment.column || "single") === "single").length;
  const leftColumnSegments = segments.filter((segment) => segment.column === "left").length;
  const rightColumnSegments = segments.filter((segment) => segment.column === "right").length;
  const averageLineBoxesPerBodySegment = bodyLineBoxCounts.length
    ? Number((bodyLineBoxCounts.reduce((sum, count) => sum + count, 0) / bodyLineBoxCounts.length).toFixed(2))
    : 0;
  segments.forEach((segment) => {
    const key = String(segment.pageNumber || 0);
    perPage[key] = (perPage[key] || 0) + 1;
  });
  const summary = {
    totalPages,
    totalLineBoxes: lines.length,
    totalSegments: segments.length,
    headerSegments,
    titleSegments,
    authorSegments,
    affiliationSegments,
    headingSegments,
    bodySegments: bodySegments.length,
    abstractSegments,
    keywordSegments,
    captionSegments,
    referenceSegments,
    marginIgnoredLines,
    ignoredNoiseLines,
    ignoredPageNumberLines,
    imageRegionsPerPage: imageRegionsByPage || {},
    ignoredImageTextLines,
    ignoredImageTextPreviews,
    referenceModeStartPage,
    continuationSegments,
    averageLineBoxesPerBodySegment,
    bodySegmentsLessThan3Lines,
    bodySegmentsMoreThan12Lines,
    singleColumnSegments,
    leftColumnSegments,
    rightColumnSegments,
    perPage,
  };
  debugPdfLog("[pdf-segments]", JSON.stringify(summary));
  if (bodySegments.length && bodySegmentsLessThan3Lines / bodySegments.length > 0.3) {
    debugPdfWarn("PDF segmentation too fragmented.", JSON.stringify(summary));
  }
  segments.slice(0, 40).forEach((segment) => {
    debugPdfLog("[pdf-segment]", JSON.stringify({
      id: segment.id,
      pageNumber: segment.pageNumber,
      column: segment.column,
      type: segment.type || "body",
      preview: String(segment.sourceText || "").slice(0, 80),
      lineBoxes: Array.isArray(segment.lineBoxes) ? segment.lineBoxes.length : 0,
      sourceTextLength: String(segment.sourceText || "").length,
    }));
  });
  bodySegments.forEach((segment) => {
    debugPdfLog("[pdf-body-segment]", JSON.stringify({
      id: segment.id,
      pageNumber: segment.pageNumber,
      column: segment.column,
      lineBoxes: Array.isArray(segment.lineBoxes) ? segment.lineBoxes.length : 0,
      sourceTextLength: String(segment.sourceText || "").length,
      firstLineStartGap: segment.firstLineStartGap,
      lastLineEndGap: segment.lastLineEndGap,
      preview: String(segment.sourceText || "").slice(0, 80),
    }));
  });
  segments
    .filter((segment) => [3, 5, 6].includes(Number(segment.pageNumber || 0)))
    .forEach((segment) => {
      debugPdfLog("[pdf-page-focus-segment]", JSON.stringify({
        id: segment.id,
        pageNumber: segment.pageNumber,
        column: segment.column,
        type: segment.type || "body",
        lineBoxes: Array.isArray(segment.lineBoxes) ? segment.lineBoxes.length : 0,
        preview: String(segment.sourceText || "").slice(0, 100),
      }));
    });
}

function buildStructuredPdfText(pageItemsByPage, pipelineConfig, imageGeometryByPage = new Map()) {
  currentPdfIgnoredNoiseLines = 0;
  currentPdfIgnoredPageNumberLines = 0;
  currentPdfIgnoredImageTextLines = 0;
  currentPdfIgnoredImageTextPreviews = [];
  currentPdfImageRegionsByPage = {};
  currentPdfCaptionRegionsByPage = {};
  currentPdfAllRawLinesByPage = {};
  currentPdfAllRawTextItemsByPage = {};
  currentPdfFormulaProtectionByPage = {};
  currentPdfImageRegionsFinalizedBeforeLayoutPlan = false;
  currentPdfImageRegionCounterProofBeforeLayoutCount = 0;
  currentPdfImageRegionChangedAfterLayoutPlanCount = 0;
  currentPdfImageRegionBodyCounterProofAttemptCount = 0;
  currentPdfImageRegionBodyCounterProofHitCount = 0;
  currentPdfImageRegionBodyCounterProofShrinkCount = 0;
  currentPdfImageRegionBodyCounterProofDropCount = 0;
  currentPdfImageRegionBodyCounterProofSkippedReasons = [];
  currentPdfImageRegionBeforeAfterBoxesByPage = {};
  currentPdfImageRegionSegmentCounterProofSegmentCandidateCount = 0;
  currentPdfImageRegionSegmentCounterProofLineBoxCandidateCount = 0;
  currentPdfImageRegionSegmentCounterProofCandidateSegmentIds = [];
  currentPdfImageRegionSegmentCounterProofRejectedByColumnCount = 0;
  currentPdfImageRegionSegmentCounterProofRejectedByNoOverlapCount = 0;
  currentPdfImageRegionSegmentCounterProofRejectedByTextPatternCount = 0;
  if (isSimplePdfV2Config(pipelineConfig)) {
    return runSimplePdfSimplifiedCore(pageItemsByPage, pipelineConfig);
  }
  const allLines = [];
  const allParagraphs = [];
  const pipelinePages = [];
  let marginIgnoredLines = 0;

  pageItemsByPage.forEach((items, pageNumber) => {
    marginIgnoredLines += items.filter((item) => isMarginTextItem(item)).length;
    const authoritativePageGeometry = imageGeometryByPage.get(pageNumber);
    const pageWidth = Number(items && items[0] && items[0].pageWidth || authoritativePageGeometry && authoritativePageGeometry.pageWidth || 0);
    const pageHeight = Number(items && items[0] && items[0].pageHeight || authoritativePageGeometry && authoritativePageGeometry.pageHeight || 0);
    const columns = isPaperPdfConfig(pipelineConfig)
      ? detectPageColumns(items)
      : [{ name: "single", items, layout: { layoutType: "simple_document_flow", languageHint: "" } }];
    const rawTextItems = [];
    columns.forEach((column) => {
      (Array.isArray(column.items) ? column.items : []).forEach((item) => {
        if (!item) return;
        rawTextItems.push({
          pageNumber: Number(pageNumber),
          text: String(item.text || item.str || ''),
          x: Number(item.x || 0),
          y: Number(item.y || item.baselineTopY || 0),
          width: Number(item.width || 0),
          height: Number(item.height || 0),
          fontSize: Number(item.fontSize || item.height || 0),
          pageWidth: Number(item.pageWidth || 0),
          pageHeight: Number(item.pageHeight || 0),
          column: String(column.name || 'single'),
        });
      });
    });
    currentPdfAllRawTextItemsByPage[String(pageNumber)] = rawTextItems;
    const columnLines = columns.map((column) => ({
      column,
      lines: mergeTextItemsIntoLines(column.items)
        .map((line) => ({ ...line, column: column.name })),
    }));
    const pageLines = columnLines.flatMap((entry) => entry.lines);
    const imageGeometry = isPaperPdfConfig(pipelineConfig) ? imageGeometryByPage.get(pageNumber) : null;
    if (isPaperPdfConfig(pipelineConfig) && (!imageGeometry || imageGeometry.schemaVersion !== PDF_IMAGE_GEOMETRY_SCHEMA_VERSION)) {
      const error = new Error(`Authoritative PDF image geometry is missing for page ${pageNumber}.`);
      error.code = "PDF_IMAGE_GEOMETRY_MISSING";
      throw error;
    }
    const imageRegions = imageGeometry ? imageGeometry.artifacts : [];
    currentPdfImageRegionsByPage[String(pageNumber)] = imageRegions;
    const collectedPageLines = [];

    columnLines.forEach((entry) => {
      const lines = filterImageRegionLines(entry.lines, imageRegions);
      const paragraphs = mergeLinesIntoParagraphs(lines);
      allLines.push(...lines);
      collectedPageLines.push(...lines);
      allParagraphs.push(...paragraphs);
    });
    const pageParagraphs = allParagraphs.filter((paragraph) => Number(paragraph.pageNumber || 0) === Number(pageNumber));
    const layout = columns.find((column) => column.layout)?.layout || detectPageLayout(collectedPageLines, pageWidth, pageHeight);
    const zones = isPaperPdfConfig(pipelineConfig)
      ? detectPaperPageZones({ pageNumber, pageWidth, pageHeight }, collectedPageLines, imageRegions, pipelineConfig)
      : [];
    pipelinePages.push({
      pageNumber,
      pageIndex: pageNumber - 1,
      pageWidth,
      pageHeight,
      rawTextItemCount: items.length,
      lineCount: collectedPageLines.length,
      blockCount: pageParagraphs.length,
      segmentCount: 0,
      layoutType: layout.layoutType || "single_column",
      columns: columns.map((column) => column.name),
      textItemBboxRange: makeBboxRange(items),
      lineBboxRange: makeBboxRange(collectedPageLines.map((line) => line.bbox)),
      segmentBboxRange: null,
      zones,
      imageRegions,
      imageGeometrySchemaVersion: imageGeometry ? imageGeometry.schemaVersion : "",
      imageGeometryCoordinateSpace: imageGeometry ? imageGeometry.coordinateSpace : "",
      imageGeometrySource: imageGeometry ? imageGeometry.source : "",
      imageGeometryHash: imageGeometry ? imageGeometry.pageGeometryHash : "",
      unsupportedImageOperators: imageGeometry ? imageGeometry.unsupportedImageOperators : [],
      captionSegments: [],
      figurePageDetected: isPaperPdfConfig(pipelineConfig) && (imageRegions.length > 0 || collectedPageLines.some((line) => isCaptionMarkerText(line.text))),
      defaultWriteStrategySegments: [],
      bodyCrossColumnSegments: [],
      oversizedBodySegments: [],
      referenceModeActive: false,
      hasAastexHeader: isPaperPdfConfig(pipelineConfig) && pageHasAastexSignal(collectedPageLines, items),
      warnings: [],
    });
  });

  const processedSegments = postProcessPdfSegments(paragraphsToSegments(allParagraphs), pipelineConfig);
  let segments = !isPaperPdfConfig(pipelineConfig) || pipelineConfig.enableCaptionClassification === false
    ? processedSegments
    : recoverCaptionSegmentsFromPageItems(processedSegments, pageItemsByPage);
  let pretranslationCaptionGroupFinalization = { plan: new Map(), groupArtifacts: [] };
  let captionOwnedDuplicateElimination = { segments, eliminatedSegmentIds: [], trimmedSegmentIds: [], eliminatedLineCount: 0 };
  const pretranslationRawLinesByPage = {};
  if (isPaperPdfConfig(pipelineConfig)) {
    segments = suppressDuplicateCaptionSegments(segments, pipelineConfig);
    segments = auditPaperImageTextPreserveRisk(segments, { demote: true }).segments;
    segments = demoteBodyLikeCaptionSegmentsBeforeTranslation(segments, pipelineConfig);
    segments = resolveCaptionBodyConflictsForPaperSegments(segments, pipelineConfig);
    // PDF.js paint operators are the sole image-geometry authority. Caption/body heuristics are not
    // allowed to create, shrink, drop, or replace these artifacts.
    segments = mergeImageAdjacentCaptionContinuations(segments, currentPdfImageRegionsByPage, pipelineConfig);
    allLines.forEach((line) => {
      if (!line || !line.bbox) return;
      const pageNumber = Number(line.pageNumber || 0);
      if (!pageNumber) return;
      const key = String(pageNumber);
      if (!pretranslationRawLinesByPage[key]) pretranslationRawLinesByPage[key] = [];
      pretranslationRawLinesByPage[key].push({
        pageNumber,
        bbox: { x: Number(line.bbox.x || 0), y: Number(line.bbox.y || 0), width: Number(line.bbox.width || 0), height: Number(line.bbox.height || 0) },
        text: String(line.text || ''),
        column: String(line.column || 'single'),
      });
    });
    currentPdfAllRawLinesByPage = pretranslationRawLinesByPage;
    // Caption source identity must exist before the last source-fragment identity pass. Otherwise
    // image-region splitting can materialize a Body identity for a line already owned by Caption.
    pretranslationCaptionGroupFinalization = finalizePretranslationCaptionGroups(segments, pretranslationRawLinesByPage);
    captionOwnedDuplicateElimination = eliminateCaptionOwnedBodySourceLineDuplicates(segments);
    segments = captionOwnedDuplicateElimination.segments;
    segments = applyImageRegionSegmentationConstraints(segments, pipelineConfig, { enforceSegmentIdentity: true });
    assertSegmentIdentityContractOrThrow(segments, "post_image_region_segmentation");
    currentPdfImageRegionsFinalizedBeforeLayoutPlan = true;
    pipelinePages.forEach((page) => {
      page.imageRegions = currentPdfImageRegionsByPage[String(page.pageNumber)] || [];
    });
  }
  const lineNumberByKey = new Map();
  allLines.forEach((line, index) => {
    lineNumberByKey.set(`${line.pageNumber}|${line.column || "single"}|${line.bbox.x}|${line.bbox.y}|${line.text}`, index + 1);
  });
  const segmentsByPage = new Map();
  segments.forEach((segment, index) => {
    const pageNumber = Number(segment.pageNumber || 0);
    if (!segmentsByPage.has(pageNumber)) segmentsByPage.set(pageNumber, []);
    const pages = getSegmentPageNumbers(segment);
    const columns = getSegmentColumns(segment);
    const sourceLineNumbers = (segment.lineBoxes && segment.lineBoxes.length ? segment.lineBoxes : (segment.lines || [])).map((line) => {
      return lineNumberByKey.get(`${line.pageNumber}|${line.column || segment.column || "single"}|${line.x || line.bbox && line.bbox.x}|${line.y || line.bbox && line.bbox.y}|${line.sourceLineText || line.text}`) || null;
    }).filter(Boolean);
    segment.firstLinePageNumber = pages[0] || pageNumber;
    segment.lastLinePageNumber = pages[pages.length - 1] || pageNumber;
    segment.crossedPageBoundary = pages.length > 1 || (segment.firstLinePageNumber && segment.lastLinePageNumber && segment.firstLinePageNumber !== segment.lastLinePageNumber);
    segment.crossedColumnBoundary = columns.length > 1;
    segment.sourceLineNumbers = sourceLineNumbers;
    segment.mergeReason = segment.continuation ? "cross_page_hyphen_continuation_marker" : "";
    segment.classificationReason = segment.referenceHeading ? "references_heading" : (segment.classificationReason || segment.type || "body");
    const pipelinePage = pipelinePages.find((page) => Number(page.pageNumber || 0) === pageNumber);
    segment.warnings = [...(segment.warnings || []), "diag:forEach:id=" + segment.id + ":pg=" + pageNumber];
    if (pipelinePage && isPaperPdfConfig(pipelineConfig)) {
      const pageImageRegions = currentPdfImageRegionsByPage[String(pageNumber)] || pipelinePage.imageRegions || [];
      const zoneType = assignSegmentZone(segment, pipelinePage.zones || []);
      segment.zoneType = zoneType;
      const diagW = ["diag:irCount=" + pageImageRegions.length, "diag:bboxY=" + (segment.bbox && segment.bbox.y), "diag:bboxH=" + (segment.bbox && segment.bbox.height)];
      if (segment.type === "body" && pageImageRegions.length > 0) {
        pageImageRegions.forEach((region, ri) => {
          diagW.push("diag:r" + ri + "y=" + region.y + ",h=" + region.height + ",intersect=" + bboxIntersects(segment.bbox, region));
        });
      }
      segment.warnings = [...(segment.warnings || []), ...diagW];
      segment.imageRegionOverlap = Boolean(segment.type === "body" && pageImageRegions.some((region) => bboxIntersects(segment.bbox, region)));
      if (segment.imageRegionOverlap) segment.warnings = [...(segment.warnings || []), "body_image_region_overlap"];
    }
    segment.previousSegmentId = index > 0 ? segments[index - 1].id : "";
    segment.nextSegmentId = index < segments.length - 1 ? segments[index + 1].id : "";
    segmentsByPage.get(pageNumber).push(segment);
  });

  // === paper_pdf source-line coverage audit & segment recovery ===
  const sourceCoverageAuditSummary = {
    totalUncoveredLines: 0,
    totalRecoveredSegments: 0,
    totalFormulaLinesUncovered: 0,
    recoveredDuplicateRejectedCount: 0,
    recoveredDuplicateRejectedSegmentIds: [],
    recoveredRejectedByPreserveZoneCount: 0,
    recoveredRejectedByPreserveZoneSegmentIds: [],
    recoveredRejectedByReferenceZoneCount: 0,
    recoveredRejectedByReferenceZoneSegmentIds: [],
    recoveredRejectedByLicenseZoneCount: 0,
    recoveredRejectedByLicenseZoneSegmentIds: [],
    recoveredRejectedDoiLikeCount: 0,
    recoveredRejectedDoiLikeSegmentIds: [],
    recoveredRejectedNeighborPreserveZoneCount: 0,
    recoveredRejectedNeighborPreserveZoneSegmentIds: [],
    recoveredWrittenInsideReferenceZoneCount: 0,
    recoveredWrittenInsideReferenceZoneSegmentIds: [],
    sourceLineCoverageFalsePositiveCount: 0,
    exportCompletenessHardFail: false,
    duplicateSegmentIdCount: 0,
    duplicateSegmentIds: [],
    duplicateSegmentDetails: [],
    segmentIdAllocatorMaxBefore: 0,
    segmentIdAllocatorMaxAfter: 0,
    recoverySegmentIdAllocatedCount: 0,
    splitSegmentIdAllocatedCount: 0,
    captionOwnedBodyDuplicateEliminatedCount: captionOwnedDuplicateElimination.eliminatedSegmentIds.length,
    captionOwnedBodyDuplicateEliminatedSegmentIds: captionOwnedDuplicateElimination.eliminatedSegmentIds.slice(),
    captionOwnedBodyDuplicateTrimmedCount: captionOwnedDuplicateElimination.trimmedSegmentIds.length,
    captionOwnedBodyDuplicateTrimmedSegmentIds: captionOwnedDuplicateElimination.trimmedSegmentIds.slice(),
    captionOwnedBodyDuplicateEliminatedLineCount: captionOwnedDuplicateElimination.eliminatedLineCount,
  };
  let _recoveryIdAllocator = null;
  if (isPaperPdfConfig(pipelineConfig)) {
    _recoveryIdAllocator = createSegmentIdAllocator(segments);
    pipelinePages.forEach((page) => {
      const pageNum = Number(page.pageNumber || 0);
      const pageHeight = Number(page.pageHeight || 792);
      const headerZoneY = pageHeight * 0.04;
      const footerZoneY = pageHeight - 60;

      if (!segmentsByPage.has(pageNum)) segmentsByPage.set(pageNum, []);
      const pageSegs = segmentsByPage.get(pageNum);
      const captionSourceOwners = pageSegs.filter((segment) => segment && String(segment.type || '') === 'caption');
      const referenceModeActive = pageSegs.some((s) => s.referenceModeApplied || s.type === "reference");
      const segBboxes = pageSegs.map((s) => s.bbox).filter(Boolean);

      const pageLines = allLines.filter((l) => Number(l.pageNumber || 0) === pageNum);
      const uncoveredLines = [];
      const formulaLikeUncovered = [];

      pageLines.forEach((line) => {
        const bbox = line.bbox;
        if (!bbox) return;
        const ly = Number(bbox.y || 0);
        const lh = Number(bbox.height || 0);
        if (lh < 3) return;
        if (ly < headerZoneY || ly + lh > footerZoneY) return;
        const text = normalizeExtractedPdfText(line.text || "");
        if (!text || text.length < 3) return;
        if (/^\d+$/.test(text)) return;
        if (text.length < 5 && !/[A-Za-z]/.test(text)) return;
        const lineType = getPdfLineType(line);
        if (lineType === "pageNumber" || lineType === "header" || lineType === "footer" ||
            lineType === "margin" || lineType === "watermark" || lineType === "licenseText") return;
        if (isImageLabelText(text)) return;
        if (referenceModeActive && isReferenceText(text)) return;
        if (isPaperRawLineOwnedByCaptionSource(line, captionSourceOwners)) return;
        const cy = ly + lh / 2;
        const lx0 = Number(bbox.x || 0);
        const lx1 = lx0 + Number(bbox.width || 0);
        const isCovered = segBboxes.some((sbbox) => {
          const sy0 = Number(sbbox.y || 0) - 4;
          const sy1 = sy0 + Number(sbbox.height || 0) + 8;
          const sx0 = Number(sbbox.x || 0) - 8;
          const sx1 = sx0 + Number(sbbox.width || 0) + 16;
          return cy >= sy0 && cy <= sy1 && lx1 > sx0 && lx0 < sx1;
        });
        if (isCovered) return;
        uncoveredLines.push(line);
        if (isFormulaLikeLine(line)) formulaLikeUncovered.push(line);
      });

      // Group consecutive uncovered lines (same column, y gap ≤ 28pt) into recovery segments
      const sortedUncovered = uncoveredLines.slice().sort((a, b) => {
        const ca = a.column || "single";
        const cb = b.column || "single";
        if (ca !== cb) return ca < cb ? -1 : 1;
        return Number(a.bbox.y) - Number(b.bbox.y);
      });
      const recoveredSegs = [];
      const rejectedRecoverySegs = [];
      const zoneRejectedRecoverySegs = [];
      let groupLines = [];

      const tryAcceptRecovery = (candidate) => {
        // 1. Duplicate check (source-line ID overlap or ngram/bbox similarity)
        const duplicateCheck = isDuplicateRecoveryCandidate(candidate, pageSegs.concat(recoveredSegs));
        if (duplicateCheck.duplicate) {
          rejectedRecoverySegs.push({ ...candidate, duplicateRecoveryReason: duplicateCheck.reason, duplicateRecovery: duplicateCheck });
          return;
        }
        // 2. DOI-like or dangling numeric fragment check
        const candidateText = normalizeExtractedPdfText(candidate.sourceText || '');
        if (isDoiLikeOrDanglingRecoveryText(candidateText)) {
          zoneRejectedRecoverySegs.push({ ...candidate, zoneRecoveryReason: 'doi_like_text' });
          return;
        }
        // 3. Preserve zone proximity check (reference / licenseText / footer / header)
        const zoneCheck = isRecoveryCandidateInPreserveZone(candidate, pageSegs);
        if (zoneCheck.inZone) {
          zoneRejectedRecoverySegs.push({ ...candidate, zoneRecoveryReason: zoneCheck.reason, zonePreserveType: zoneCheck.preserveType });
          return;
        }
        recoveredSegs.push(candidate);
      };

      sortedUncovered.forEach((line) => {
        const prev = groupLines[groupLines.length - 1];
        if (!prev ||
            (line.column || "single") !== (prev.column || "single") ||
            Number(line.bbox.y) - (Number(prev.bbox.y) + Number(prev.bbox.height)) > 28) {
          if (groupLines.length) {
            const segId = _recoveryIdAllocator.next();
            tryAcceptRecovery(materializeSegmentIdentity(buildRecoveryBodySegment(groupLines, segId), segId, "coverage_recovery"));
          }
          groupLines = [line];
        } else {
          groupLines.push(line);
        }
      });
      if (groupLines.length) {
        const segId = _recoveryIdAllocator.next();
        tryAcceptRecovery(materializeSegmentIdentity(buildRecoveryBodySegment(groupLines, segId), segId, "coverage_recovery"));
      }

      recoveredSegs.forEach((seg) => {
        segments.push(seg);
        pageSegs.push(seg);
      });

      const totalBodyCandidateLines = pageLines.filter((l) => {
        const t = normalizeExtractedPdfText(l.text || "");
        if (!t || t.length < 3 || /^\d+$/.test(t)) return false;
        const lt = getPdfLineType(l);
        return lt !== "pageNumber" && lt !== "header" && lt !== "footer" &&
               lt !== "margin" && lt !== "watermark" && lt !== "licenseText";
      }).length;

      const zoneRejRefSegs = zoneRejectedRecoverySegs.filter((s) => ['overlaps_preserve_segment', 'neighbor_density_preserve'].includes(String(s.zoneRecoveryReason || '')) && String(s.zonePreserveType || '') === 'reference');
      const zoneRejLicSegs = zoneRejectedRecoverySegs.filter((s) => ['overlaps_preserve_segment', 'neighbor_density_preserve'].includes(String(s.zoneRecoveryReason || '')) && String(s.zonePreserveType || '') === 'licenseText');
      const zoneRejPreserveSegs = zoneRejectedRecoverySegs.filter((s) => ['overlaps_preserve_segment', 'neighbor_density_preserve'].includes(String(s.zoneRecoveryReason || '')));
      const zoneRejNeighborSegs = zoneRejectedRecoverySegs.filter((s) => String(s.zoneRecoveryReason || '') === 'neighbor_density_preserve');
      const zoneRejDoiSegs = zoneRejectedRecoverySegs.filter((s) => String(s.zoneRecoveryReason || '') === 'doi_like_text');

      page.uncoveredSourceLineCount = uncoveredLines.length;
      page.uncoveredSourceLineIds = uncoveredLines.map((l, i) => `uncovered-pg${pageNum}-${i + 1}`);
      page.recoveredUncoveredBodySegmentCount = recoveredSegs.length;
      page.recoveredUncoveredBodySegmentIds = recoveredSegs.map((s) => s.id);
      page.recoveredDuplicateRejectedCount = rejectedRecoverySegs.length;
      page.recoveredDuplicateRejectedSegmentIds = rejectedRecoverySegs.map((s) => s.id);
      page.recoveredDuplicateRejectedReasons = rejectedRecoverySegs.map((s) => ({
        id: s.id,
        reason: s.duplicateRecoveryReason || "",
        duplicateWithSegmentId: s.duplicateRecovery && s.duplicateRecovery.duplicateWithSegmentId || "",
        textOverlap: s.duplicateRecovery && s.duplicateRecovery.textOverlap || 0,
        bboxOverlap: s.duplicateRecovery && s.duplicateRecovery.bboxOverlap || 0,
      }));
      page.recoveredRejectedByPreserveZoneCount = zoneRejPreserveSegs.length;
      page.recoveredRejectedByPreserveZoneSegmentIds = zoneRejPreserveSegs.map((s) => s.id);
      page.recoveredRejectedByReferenceZoneCount = zoneRejRefSegs.length;
      page.recoveredRejectedByReferenceZoneSegmentIds = zoneRejRefSegs.map((s) => s.id);
      page.recoveredRejectedByLicenseZoneCount = zoneRejLicSegs.length;
      page.recoveredRejectedByLicenseZoneSegmentIds = zoneRejLicSegs.map((s) => s.id);
      page.recoveredRejectedDoiLikeCount = zoneRejDoiSegs.length;
      page.recoveredRejectedDoiLikeSegmentIds = zoneRejDoiSegs.map((s) => s.id);
      page.recoveredRejectedNeighborPreserveZoneCount = zoneRejNeighborSegs.length;
      page.recoveredRejectedNeighborPreserveZoneSegmentIds = zoneRejNeighborSegs.map((s) => s.id);
      page.recoveredZoneRejectedDetails = zoneRejectedRecoverySegs.map((s) => ({
        id: s.id,
        reason: s.zoneRecoveryReason || '',
        preserveType: s.zonePreserveType || '',
        text: normalizeExtractedPdfText(s.sourceText || '').slice(0, 60),
      }));
      page.sourceLineCoverageFalsePositiveCount = rejectedRecoverySegs.length + zoneRejectedRecoverySegs.length;
      page.formulaLikeLineMaskMissingCount = formulaLikeUncovered.length;
      page.formulaLikeLineMaskMissingIds = formulaLikeUncovered.map((l, i) => `formula-uncovered-pg${pageNum}-${i + 1}`);
      page.mixedFormulaLineRecoveredCount = recoveredSegs.filter((s) => s.recoveredFormulaLine).length;
      page.formulaTokenRedrawCount = recoveredSegs.reduce((sum, s) => sum + (s.recoveredFormulaLine ? (s.lines || []).length : 0), 0);
      page.sourceLineCoverageRatio = totalBodyCandidateLines > 0
        ? Number(((totalBodyCandidateLines - uncoveredLines.length) / totalBodyCandidateLines).toFixed(4))
        : 1;

      sourceCoverageAuditSummary.totalUncoveredLines += uncoveredLines.length;
      sourceCoverageAuditSummary.totalRecoveredSegments += recoveredSegs.length;
      sourceCoverageAuditSummary.totalFormulaLinesUncovered += formulaLikeUncovered.length;
      sourceCoverageAuditSummary.recoveredDuplicateRejectedCount += rejectedRecoverySegs.length;
      sourceCoverageAuditSummary.recoveredDuplicateRejectedSegmentIds.push(...rejectedRecoverySegs.map((s) => s.id));
      sourceCoverageAuditSummary.recoveredRejectedByPreserveZoneCount += zoneRejPreserveSegs.length;
      sourceCoverageAuditSummary.recoveredRejectedByPreserveZoneSegmentIds.push(...zoneRejPreserveSegs.map((s) => s.id));
      sourceCoverageAuditSummary.recoveredRejectedByReferenceZoneCount += zoneRejRefSegs.length;
      sourceCoverageAuditSummary.recoveredRejectedByReferenceZoneSegmentIds.push(...zoneRejRefSegs.map((s) => s.id));
      sourceCoverageAuditSummary.recoveredRejectedByLicenseZoneCount += zoneRejLicSegs.length;
      sourceCoverageAuditSummary.recoveredRejectedByLicenseZoneSegmentIds.push(...zoneRejLicSegs.map((s) => s.id));
      sourceCoverageAuditSummary.recoveredRejectedDoiLikeCount += zoneRejDoiSegs.length;
      sourceCoverageAuditSummary.recoveredRejectedDoiLikeSegmentIds.push(...zoneRejDoiSegs.map((s) => s.id));
      sourceCoverageAuditSummary.recoveredRejectedNeighborPreserveZoneCount += zoneRejNeighborSegs.length;
      sourceCoverageAuditSummary.recoveredRejectedNeighborPreserveZoneSegmentIds.push(...zoneRejNeighborSegs.map((s) => s.id));
      sourceCoverageAuditSummary.sourceLineCoverageFalsePositiveCount += rejectedRecoverySegs.length + zoneRejectedRecoverySegs.length;
      const resolvedUncoveredLineCount = recoveredSegs.reduce((sum, s) => sum + (s.lines || []).length, 0) +
        rejectedRecoverySegs.reduce((sum, s) => sum + (s.lines || []).length, 0) +
        zoneRejectedRecoverySegs.reduce((sum, s) => sum + (s.lines || []).length, 0);
      if (uncoveredLines.length > resolvedUncoveredLineCount) {
        sourceCoverageAuditSummary.exportCompletenessHardFail = true;
      }
    });
  }

  // === P0: post-recovery global ID uniqueness audit ===
  if (_recoveryIdAllocator) {
    sourceCoverageAuditSummary.segmentIdAllocatorMaxBefore = _recoveryIdAllocator.maxBefore;
    sourceCoverageAuditSummary.segmentIdAllocatorMaxAfter = _recoveryIdAllocator.maxAfter;
    sourceCoverageAuditSummary.recoverySegmentIdAllocatedCount = _recoveryIdAllocator.allocatedCount;
  }
  const _idAudit = assertUniqueSegmentIds(segments);
  sourceCoverageAuditSummary.duplicateSegmentIdCount = _idAudit.duplicateSegmentIdCount;
  sourceCoverageAuditSummary.duplicateSegmentIds = _idAudit.duplicateSegmentIds;
  sourceCoverageAuditSummary.duplicateSegmentDetails = _idAudit.duplicateSegmentDetails;
  if (!_idAudit.unique) {
    sourceCoverageAuditSummary.exportCompletenessHardFail = true;
    assertSegmentIdentityContractOrThrow(segments, "pretranslation_finalization");
  }

  if (isPaperPdfConfig(pipelineConfig)) {
    const ownershipFinalization = finalizePaperCaptionBodyOwnershipBeforeTranslation(segments);
    currentPdfCaptionRegionsByPage = ownershipFinalization.captionRegionsByPage;
    currentPdfFormulaProtectionByPage = buildPaperFormulaProtectionAuthority(segments, pipelineConfig);
    pipelinePages.forEach((page) => {
      page.captionRegions = currentPdfCaptionRegionsByPage[String(page.pageNumber)] || [];
    });
  }

  pipelinePages.forEach((page) => {
    const pageSegments = segmentsByPage.get(Number(page.pageNumber)) || [];
    page.segmentCount = pageSegments.length;
    page.segmentBboxRange = makeBboxRange(pageSegments.map((segment) => segment.bbox));
    page.captionSegments = detectCaptionSegments(pageSegments, page.imageRegions || []);
    page.referenceModeActive = pageSegments.some((segment) => segment.referenceModeApplied || segment.type === "reference");
    page.oversizedBodySegments = pageSegments.filter((segment) => segment.type === "body" && shouldSplitOversizedPaperSegment(segment)).map((segment) => segment.id).filter(Boolean);
    (page.zones || []).forEach((zone) => {
      zone.segmentIds = pageSegments.filter((segment) => segment.zoneType === zone.type).map((segment) => segment.id).filter(Boolean);
    });
    if (!page.rawTextItemCount) page.warnings.push("no_text_items");
    if (page.rawTextItemCount && !page.lineCount) page.warnings.push("no_lines_from_text_items");
    if (page.lineCount && !page.segmentCount) page.warnings.push("no_segments_from_lines");
    pageSegments.forEach((segment) => {
      const warning = getOversizedSegmentWarning(segment, { width: page.pageWidth, height: page.pageHeight });
      if (warning && !page.warnings.includes(warning)) page.warnings.push(warning);
    });
    if (isPaperPdfConfig(pipelineConfig)) {
      const pageNum = Number(page.pageNumber || 0);
      const footerY = Number(page.pageHeight || 792) - 64;
      const pageLines = allLines.filter((line) => Number(line.pageNumber || 0) === pageNum);
      const segBboxes = pageSegments.map((seg) => seg.bbox).filter(Boolean);
      page.uncoveredLineMaskBoxes = pageLines.filter((line) => {
        const bbox = line.bbox;
        if (!bbox) return false;
        const ly = Number(bbox.y || 0);
        const lh = Number(bbox.height || 0);
        if (lh < 4 || ly > footerY) return false;
        if (isNoisePdfLine(line)) {
          const lineText = normalizeExtractedPdfText(line.text || '');
          // Allow short but non-trivial source text (citation labels, equation numbers) — only hard-skip empty/single-char/pure-digit noise
          if (!lineText || lineText.length < 2 || /^\d+$/.test(lineText)) return false;
        }
        const cy = ly + lh / 2;
        const lx0 = Number(bbox.x || 0);
        const lx1 = lx0 + Number(bbox.width || 0);
        // Skip lines inside image regions (figure axis labels/annotations should remain visible)
        const pageImgRegions = Array.isArray(page.imageRegions) ? page.imageRegions : [];
        if (pageImgRegions.some((ir) => {
          const irY0 = Number(ir.y || 0);
          const irY1 = irY0 + Number(ir.height || 0);
          const irX0 = Number(ir.x || 0);
          const irX1 = irX0 + Number(ir.width || 0);
          return cy >= irY0 && cy <= irY1 && lx1 > irX0 && lx0 < irX1;
        })) return false;
        return !segBboxes.some((sbbox) => {
          const sy0 = Number(sbbox.y || 0) - 4;
          const sy1 = sy0 + Number(sbbox.height || 0) + 8;
          const sx0 = Number(sbbox.x || 0) - 8;
          const sx1 = sx0 + Number(sbbox.width || 0) + 16;
          return cy >= sy0 && cy <= sy1 && lx1 > sx0 && lx0 < sx1;
        });
      }).map((line) => {
        const adapted = {
          x: Number(line.bbox.x || 0),
          y: Number(line.bbox.y || 0),
          width: Number(line.bbox.width || 0),
          height: Number(line.bbox.height || 0),
          fontSize: Number(line.fontSize || 0),
          text: line.text || '',
          segmentId: '',
        };
        const mb = getMaskBoxFromLineBox(adapted);
        return { x: mb.x, y: mb.y, width: mb.width, height: mb.height };
      });
    }
  });
  logPdfSegmentationDebug(
    pageItemsByPage.size,
    allLines,
    segments,
    marginIgnoredLines,
    currentPdfIgnoredNoiseLines,
    currentPdfIgnoredPageNumberLines,
    currentPdfImageRegionsByPage,
    currentPdfIgnoredImageTextLines,
    currentPdfIgnoredImageTextPreviews
  );
  const text = normalizeExtractedPdfText(segments.map((segment) => segment.sourceText).join("\n\n"));
  const rawLines = allLines.map((line, index) => ({
    id: `line-${index + 1}`,
    pageNumber: line.pageNumber,
    column: line.column || "single",
    text: line.text,
    bbox: line.bbox,
    items: line.items,
  }));
  const pipelineDebug = {
    pdfTranslationMode: pipelineConfig && pipelineConfig.mode || "",
    pipelineLabel: pipelineConfig && pipelineConfig.label || "",
    pipelineConfigSummary: summarizePdfPipelineConfig(pipelineConfig || {}),
    pages: pipelinePages,
    sourceCoverageAudit: sourceCoverageAuditSummary,
    exportCompletenessHardFail: sourceCoverageAuditSummary.exportCompletenessHardFail,
    imageRegionBodyCounterProofAttemptCount: currentPdfImageRegionBodyCounterProofAttemptCount,
    imageRegionBodyCounterProofHitCount: currentPdfImageRegionBodyCounterProofHitCount,
    imageRegionBodyCounterProofShrinkCount: currentPdfImageRegionBodyCounterProofShrinkCount,
    imageRegionBodyCounterProofDropCount: currentPdfImageRegionBodyCounterProofDropCount,
    imageRegionBodyCounterProofSkippedReasons: currentPdfImageRegionBodyCounterProofSkippedReasons,
    imageRegionBeforeAfterBoxesByPage: currentPdfImageRegionBeforeAfterBoxesByPage,
    counterProofSegmentCandidateCount: currentPdfImageRegionSegmentCounterProofSegmentCandidateCount,
    counterProofLineBoxCandidateCount: currentPdfImageRegionSegmentCounterProofLineBoxCandidateCount,
    counterProofCandidateSegmentIds: currentPdfImageRegionSegmentCounterProofCandidateSegmentIds,
    counterProofRejectedByColumnCount: currentPdfImageRegionSegmentCounterProofRejectedByColumnCount,
    counterProofRejectedByNoOverlapCount: currentPdfImageRegionSegmentCounterProofRejectedByNoOverlapCount,
    counterProofRejectedByTextPatternCount: currentPdfImageRegionSegmentCounterProofRejectedByTextPatternCount,
    captionBodyOwnershipFinalizedBeforeTranslation: isPaperPdfConfig(pipelineConfig),
    captionRegionsFinalizedBeforeTranslation: isPaperPdfConfig(pipelineConfig),
    captionGroupsFinalizedBeforeTranslation: isPaperPdfConfig(pipelineConfig),
    captionGroupArtifactCount: pretranslationCaptionGroupFinalization.groupArtifacts.length,
  };
  return { lines: allLines, rawLines, paragraphs: allParagraphs, segments, text, pipelineDebug };
}

function runPdfExtractionPipeline(pageItemsByPage, config, imageGeometryByPage = new Map()) {
  let legacyResult;
  if (config && config.mode === "simple_pdf") {
    legacyResult = runSimplePdfSimplifiedCore(pageItemsByPage, config);
  } else if (config && (config.mode === "paper_pdf" || config.mode === "legacy_simple_pdf")) {
    legacyResult = buildStructuredPdfText(pageItemsByPage, config, imageGeometryByPage);
  } else {
    throw new Error("Unsupported PDF mode");
  }
  const semanticStructureShadow = runSemanticStructureShadowValidation(legacyResult, {
    mode: config.mode,
    inputStage: "runPdfExtractionPipeline.legacy_result",
  });
  return {
    ...legacyResult,
    semanticStructureArtifact: semanticStructureShadow.artifact,
    semanticStructureShadowValidation: semanticStructureShadow.comparison,
  };
}

async function extractPdfTextWithPdfJs(buffer, pipelineConfig) {
  const pdfjs = await loadPdfJs();
  const loadingTask = pdfjs.getDocument({
    data: new Uint8Array(buffer),
    disableFontFace: true,
    useSystemFonts: true,
    verbosity: pdfjs.VerbosityLevel ? pdfjs.VerbosityLevel.ERRORS : 0,
    disableWorker: true,
  });
  const pdf = await loadingTask.promise;
  const pageTexts = [];
  const textItems = [];
  const pageItemsByPage = new Map();
  const imageGeometryByPage = new Map();
  const rawTextByPage = [];

  for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const viewport = page.getViewport({ scale: 1 });
    const [content, operatorList] = await Promise.all([
      page.getTextContent({
        disableCombineTextItems: false,
        includeMarkedContent: false,
      }),
      isPaperPdfConfig(pipelineConfig) ? page.getOperatorList() : Promise.resolve(null),
    ]);
    if (isPaperPdfConfig(pipelineConfig)) {
      imageGeometryByPage.set(pageNumber, extractPdfImageGeometryArtifactsFromOperatorList(operatorList, viewport, pageNumber, pdfjs));
    }
    const pageItems = (content.items || [])
      .map((item) => normalizePdfTextItem(item, pageNumber, viewport.height, viewport.width))
      .filter(Boolean);
    textItems.push(...pageItems);
    pageItemsByPage.set(pageNumber, pageItems);
    const layoutText = normalizeExtractedPdfText(textItemsToLines(content.items || []).join("\n"));
    const sequentialText = normalizeExtractedPdfText(textItemsToSequentialLines(content.items || []).join("\n"));
    const pageText = textGarbageScore(sequentialText) <= textGarbageScore(layoutText) ? sequentialText : layoutText;
    rawTextByPage.push({
      pageNumber,
      text: pageText,
      charCount: pageText.length,
    });
    if (pageText) pageTexts.push(pageText);
  }

  const structured = runPdfExtractionPipeline(pageItemsByPage, pipelineConfig, imageGeometryByPage);
  const lines = structured.lines;
  const rawLines = structured.rawLines;
  const paragraphs = structured.paragraphs;
  const segments = structured.segments;
  const simpleBlocks = Array.isArray(structured.simpleBlocks) ? structured.simpleBlocks : [];
  const paperSegments = Array.isArray(structured.paperSegments)
    ? structured.paperSegments
    : (isPaperPdfConfig(pipelineConfig) ? segments : []);
  const pipelineDebug = structured.pipelineDebug || { pages: [] };
  const semanticStructureArtifact = structured.semanticStructureArtifact || null;
  const semanticStructureShadowValidation = structured.semanticStructureShadowValidation || null;
  const text = structured.text || normalizeExtractedPdfText(pageTexts.join("\n\n"));
  const simpleMode = isSimplePdfV2Config(pipelineConfig);
  return {
    text,
    rawTextByPage,
    textItems: simpleMode ? [] : textItems,
    lines,
    rawLines,
    paragraphs,
    segments,
    simpleBlocks,
    paperSegments,
    pipelineDebug,
    semanticStructureArtifact,
    semanticStructureShadowValidation,
    pdfTranslationMode: pipelineConfig && pipelineConfig.mode || "",
    pipelineLabel: pipelineConfig && pipelineConfig.label || "",
    pipelineConfigSummary: summarizePdfPipelineConfig(pipelineConfig || {}),
    pages: pdf.numPages,
    charCount: text.length,
    paragraphCount: simpleBlocks.length || paragraphs.length || (text ? text.split(/\n\s*\n/).filter(Boolean).length : 0),
  };
}

async function selectAndExtractPdf(payload) {
  const pipelineConfig = validatePdfTranslationMode(payload);
  const focused = BrowserWindow.getFocusedWindow();
  let filePath = String(process.env.PDF_SELECT_PATH || "").trim();
  if (!filePath || !fs.existsSync(filePath)) {
    const result = await dialog.showOpenDialog(focused || undefined, {
      title: pipelineConfig.mode === "paper_pdf" ? "选择 PDF 论文" : "选择 PDF 文件",
      properties: ["openFile"],
      filters: [{ name: "PDF", extensions: ["pdf"] }],
    });
    if (result.canceled || !result.filePaths || !result.filePaths[0]) {
      return { ok: false, canceled: true };
    }
    filePath = result.filePaths[0];
  }
  const stat = fs.statSync(filePath);
  const buffer = fs.readFileSync(filePath);
  let extracted;
  try {
    extracted = await extractPdfTextWithPdfJs(buffer, pipelineConfig);
  } catch (err) {
    console.error("[pdf] pdf.js extract failed:", err.message || err);
    throw err;
  }
  return {
    ok: true,
    fileName: path.basename(filePath),
    filePath,
    fileSize: stat.size,
    pdfTranslationMode: pipelineConfig.mode,
    modeLockedByUser: Boolean(payload && payload.modeLockedByUser),
    pipelineLabel: pipelineConfig.label,
    pipelineConfigSummary: summarizePdfPipelineConfig(pipelineConfig),
    ...extracted,
  };
}

function buildDesktopFeatureEnv() {
  const config = readSharedConfig();
  const rootUrl = config.serverBaseUrl.replace(/\/+$/, "");
  const provider = config.provider || {};
  const env = {
    ...process.env,
    LINGOFLOW_STARTED_BY_MAIN_UI: "1",
    LINGOFLOW_CONFIG_PATH: SHARED_CONFIG_PATH,
    LINGOFLOW_TARGET_LANGUAGE: config.targetLanguage,
    LINGOFLOW_PROXY_BASE_URL: rootUrl.endsWith("/v1") ? rootUrl : `${rootUrl}/v1`,
    LINGOFLOW_BETA_TOKEN: config.betaToken,
    LINGOFLOW_PROVIDER_TYPE: provider.type || "openai_compatible",
    LINGOFLOW_PROVIDER_BASE_URL: provider.baseUrl || "",
    LINGOFLOW_PROVIDER_API_KEY: provider.apiKey || "",
    LINGOFLOW_PROVIDER_MODEL: provider.model || "",
  };
  delete env.HTTP_PROXY;
  delete env.HTTPS_PROXY;
  delete env.ALL_PROXY;
  delete env.http_proxy;
  delete env.https_proxy;
  delete env.all_proxy;
  return env;
}

async function getDesktopFeatureStatus() {
  if (isDesktopFeatureRunning()) {
    return desktopFeatureStatus({ ok: true });
  }
  if (fs.existsSync(DESKTOP_FEATURE_EXE)) {
    const existing = await findPackagedDesktopFeatureProcess();
    if (existing) {
      return {
        ok: true,
        running: true,
        pid: existing.pid,
        startedAt: null,
        mode: "packaged-existing",
      };
    }
  }
  return desktopFeatureStatus({ ok: true });
}

function findPackagedDesktopFeatureProcess() {
  if (process.platform !== "win32") return Promise.resolve(null);
  return new Promise((resolve) => {
    execFile(
      "tasklist",
      ["/FI", "IMAGENAME eq DesktopFloatBallTest.exe", "/FO", "CSV", "/NH"],
      { windowsHide: true },
      (err, stdout) => {
        if (err) {
          resolve(null);
          return;
        }
        const line = String(stdout || "").split(/\r?\n/).find((row) => row.includes("DesktopFloatBallTest.exe"));
        if (!line) {
          resolve(null);
          return;
        }
        const parts = line.split('","').map((part) => part.replace(/^"|"$/g, ""));
        const pid = Number(parts[1]);
        resolve(Number.isFinite(pid) ? { pid } : { pid: null });
      },
    );
  });
}

function attachDesktopFeatureLifecycle(proc, mode) {
  desktopFeatureProc = proc;
  desktopFeatureProc.__launchMode = mode;
  desktopFeatureStartedAt = new Date().toISOString();

  proc.once("exit", (code, signal) => {
    console.log(`[desktop-feature] exited mode=${mode} code=${code} signal=${signal || "none"}`);
    if (desktopFeatureProc && desktopFeatureProc.pid === proc.pid) {
      desktopFeatureProc = null;
      desktopFeatureStartedAt = null;
    }
  });

  proc.once("error", (err) => {
    console.error(`[desktop-feature] spawn error mode=${mode}:`, err.message || err);
    if (desktopFeatureProc && desktopFeatureProc.pid === proc.pid) {
      desktopFeatureProc = null;
      desktopFeatureStartedAt = null;
    }
  });
}

async function startDesktopFeature() {
  if (isDesktopFeatureRunning()) {
    return desktopFeatureStatus({ ok: true, alreadyRunning: true });
  }

  if (fs.existsSync(DESKTOP_FEATURE_ROOT)) {
    try {
      const env = buildDesktopFeatureEnv();
      const proc = process.platform === "win32"
        ? spawn(WINDOWS_CMD, ["/d", "/s", "/c", "npm.cmd start"], {
            cwd: DESKTOP_FEATURE_ROOT,
            detached: false,
            stdio: "ignore",
            windowsHide: true,
            env,
          })
        : spawn(DESKTOP_FEATURE_NPM, ["start"], {
            cwd: DESKTOP_FEATURE_ROOT,
            detached: false,
            stdio: "ignore",
            env,
          });
      attachDesktopFeatureLifecycle(proc, "npm-start");
      console.log(`[desktop-feature] started npm launcher pid=${proc.pid}`);
      return desktopFeatureStatus({ ok: true, alreadyRunning: false });
    } catch (err) {
      console.error("[desktop-feature] npm start spawn failed:", err.message || err);
      return {
        ok: false,
        running: false,
        error: err && err.message ? err.message : String(err),
        path: DESKTOP_FEATURE_ROOT,
      };
    }
  }

  if (fs.existsSync(DESKTOP_FEATURE_EXE)) {
    const existing = await findPackagedDesktopFeatureProcess();
    if (existing) {
      return {
        ok: true,
        running: true,
        pid: existing.pid,
        startedAt: null,
        mode: "packaged-existing",
        alreadyRunning: true,
      };
    }

    const proc = spawn(DESKTOP_FEATURE_EXE, ["--started-by-main-ui"], {
      cwd: path.dirname(DESKTOP_FEATURE_EXE),
      detached: false,
      stdio: "ignore",
      windowsHide: false,
      env: buildDesktopFeatureEnv(),
    });
    attachDesktopFeatureLifecycle(proc, "packaged");
    console.log(`[desktop-feature] started packaged launcher pid=${proc.pid}`);
    return desktopFeatureStatus({ ok: true, alreadyRunning: false });
  }

  return {
    ok: false,
    running: false,
    error: "desktop_feature_missing",
    path: DESKTOP_FEATURE_ROOT,
  };
}

async function showDesktopFeature() {
  if (!isDesktopFeatureRunning()) {
    const status = await startDesktopFeature();
    return { ...status, showRequested: Boolean(status && status.ok) };
  }

  if (fs.existsSync(DESKTOP_FEATURE_ROOT)) {
    try {
      const env = buildDesktopFeatureEnv();
      const proc = process.platform === "win32"
        ? spawn(WINDOWS_CMD, ["/d", "/s", "/c", "npm.cmd start -- --show-launcher"], {
            cwd: DESKTOP_FEATURE_ROOT,
            detached: false,
            stdio: "ignore",
            windowsHide: true,
            env,
          })
        : spawn(DESKTOP_FEATURE_NPM, ["start", "--", "--show-launcher"], {
            cwd: DESKTOP_FEATURE_ROOT,
            detached: false,
            stdio: "ignore",
            env,
          });
      proc.unref();
      console.log(`[desktop-feature] requested launcher show pid=${proc.pid}`);
      return desktopFeatureStatus({ ok: true, alreadyRunning: true, showRequested: true });
    } catch (err) {
      console.error("[desktop-feature] show request failed:", err.message || err);
      return desktopFeatureStatus({
        ok: false,
        alreadyRunning: true,
        error: err && err.message ? err.message : String(err),
      });
    }
  }

  if (fs.existsSync(DESKTOP_FEATURE_EXE)) {
    try {
      const proc = spawn(DESKTOP_FEATURE_EXE, ["--show-launcher"], {
        cwd: path.dirname(DESKTOP_FEATURE_EXE),
        detached: false,
        stdio: "ignore",
        windowsHide: false,
        env: buildDesktopFeatureEnv(),
      });
      proc.unref();
      console.log(`[desktop-feature] requested packaged launcher show pid=${proc.pid}`);
      return desktopFeatureStatus({ ok: true, alreadyRunning: true, showRequested: true });
    } catch (err) {
      return desktopFeatureStatus({
        ok: false,
        alreadyRunning: true,
        error: err && err.message ? err.message : String(err),
      });
    }
  }

  return desktopFeatureStatus({ ok: false, error: "desktop_feature_missing" });
}

function safeTxtBaseName(fileName) {
  const parsed = path.parse(String(fileName || "pdf").trim() || "pdf");
  const base = parsed.name || "pdf";
  return base.replace(/[<>:"/\\|?*\x00-\x1F]/g, "_").slice(0, 120) || "pdf";
}

function getPdfPipelineConfig(pdfTranslationMode) {
  const mode = String(pdfTranslationMode || "").trim();
  if (mode === "simple_pdf") {
    return {
      mode: "simple_pdf",
      label: "普通版 PDF",
      pipelineBranch: "simple_pdf_simplified_core",
      enablePaperStructure: false,
      enableTitleZoneClassification: false,
      enableAuthorAffiliationClassification: false,
      enableReferencePreserve: false,
      enableCaptionClassification: false,
      enableEquationBlockPreserve: false,
      enableFormulaLinePreserve: false,
      enableInlineFormulaTokenProtect: true,
      preserveImages: true,
      imageTextOcr: false,
      enableImageTextOcr: false,
      preserveReferences: false,
      preserveFormulaBlocks: false,
      segmentationMode: "simple_simplified_blocks",
      writeStrategyPreference: "document_flow",
      progressMode: "simple",
    };
  }
  if (mode === "legacy_simple_pdf") {
    return {
      mode: "legacy_simple_pdf",
      label: "普通版 PDF（旧版）",
      pipelineBranch: "legacy_simple_document_flow",
      enablePaperStructure: false,
      enableTitleZoneClassification: false,
      enableAuthorAffiliationClassification: false,
      enableReferencePreserve: false,
      enableCaptionClassification: false,
      enableEquationBlockPreserve: false,
      enableFormulaLinePreserve: false,
      enableInlineFormulaTokenProtect: true,
      preserveImages: true,
      imageTextOcr: false,
      enableImageTextOcr: false,
      preserveReferences: false,
      preserveFormulaBlocks: false,
      segmentationMode: "legacy_simple_paragraph_flow",
      writeStrategyPreference: "document_flow",
      progressMode: "simple",
    };
  }
  if (mode === "paper_pdf") {
    return {
      mode: "paper_pdf",
      label: "论文版 PDF",
      pipelineBranch: "paper_overlay_flow",
      enablePaperStructure: true,
      enableTitleZoneClassification: true,
      enableAuthorAffiliationClassification: true,
      enableReferencePreserve: true,
      enableCaptionClassification: true,
      enableEquationBlockPreserve: true,
      enableFormulaLinePreserve: "equation_block_only",
      enableInlineFormulaTokenProtect: true,
      preserveImages: true,
      imageTextOcr: false,
      enableImageTextOcr: false,
      preserveReferences: true,
      preserveFormulaBlocks: true,
      segmentationMode: "paper_semantic_segments",
      writeStrategyPreference: "column_overlay",
      progressMode: "paper",
    };
  }
  throw new Error("PDF translation mode is required. Select simple_pdf or paper_pdf first.");
}

function validatePdfTranslationMode(payload) {
  return getPdfPipelineConfig(payload && payload.pdfTranslationMode);
}

function summarizePdfPipelineConfig(config) {
  return {
    pipelineBranch: config && config.pipelineBranch || "",
    enablePaperStructure: Boolean(config && config.enablePaperStructure),
    enableTitleZoneClassification: Boolean(config && config.enableTitleZoneClassification),
    enableAuthorAffiliationClassification: Boolean(config && config.enableAuthorAffiliationClassification),
    enableReferencePreserve: Boolean(config && config.enableReferencePreserve),
    enableCaptionClassification: Boolean(config && config.enableCaptionClassification),
    enableEquationBlockPreserve: Boolean(config && config.enableEquationBlockPreserve),
    enableFormulaLinePreserve: config && Object.prototype.hasOwnProperty.call(config, "enableFormulaLinePreserve") ? config.enableFormulaLinePreserve : false,
    enableInlineFormulaTokenProtect: Boolean(config && config.enableInlineFormulaTokenProtect),
    preserveImages: Boolean(config && config.preserveImages),
    imageTextOcr: Boolean(config && config.imageTextOcr),
    preserveReferences: Boolean(config && config.preserveReferences),
    preserveFormulaBlocks: Boolean(config && config.preserveFormulaBlocks),
    segmentationMode: config && config.segmentationMode || "",
    writeStrategyPreference: config && config.writeStrategyPreference || "",
    progressMode: config && config.progressMode || "",
  };
}


function simpleExtractLinesFromPageItems(pageItemsByPage) {
  const lines = [];
  let lineNumber = 1;
  (pageItemsByPage || new Map()).forEach((items, pageNumber) => {
    mergeTextItemsIntoLines(items || []).forEach((line) => {
      const bbox = line && line.bbox || {};
      lines.push({
        pageNumber: Number(pageNumber || line.pageNumber || 0),
        text: String(line && line.text || ""),
        lineNumber: lineNumber,
        y: Number(bbox.y || line.y || 0),
        x: Number(bbox.x || line.x || 0),
        fontSize: Number(line.avgFontSize || line.fontSize || bbox.height || 0),
        pageWidth: Number(line.pageWidth || (line.items && line.items[0] && line.items[0].pageWidth) || 0),
        pageHeight: Number(line.pageHeight || (line.items && line.items[0] && line.items[0].pageHeight) || 0),
      });
      lineNumber += 1;
    });
  });
  return lines.sort((a, b) => Number(a.pageNumber || 0) - Number(b.pageNumber || 0) || Number(a.y || 0) - Number(b.y || 0) || Number(a.x || 0) - Number(b.x || 0));
}

function simpleNormalizeLines(lines) {
  return (lines || []).map((line) => ({
    pageNumber: Number(line.pageNumber || 0),
    text: normalizeExtractedPdfText(String(line.text || "").replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, " ")),
    lineNumber: Number(line.lineNumber || 0),
    y: Number(line.y || 0),
    x: Number(line.x || 0),
    fontSize: Number(line.fontSize || 0),
    pageWidth: Number(line.pageWidth || 0),
    pageHeight: Number(line.pageHeight || 0),
  })).filter((line) => line.text && textGarbageScore(line.text) < 0.5);
}

function simpleLineId(line) {
  return `p${Number(line && line.pageNumber || 0)}-l${Number(line && line.lineNumber || 0)}`;
}

function simpleEstimateLineWidth(line) {
  const text = normalizeExtractedPdfText(line && line.text || "");
  const fontSize = Math.max(6, Number(line && line.fontSize || 10));
  const cjk = (text.match(/[\u3400-\u9fff]/g) || []).length;
  const latin = (text.match(/[A-Za-z0-9]/g) || []).length;
  const other = Math.max(0, text.length - cjk - latin);
  return cjk * fontSize + latin * fontSize * 0.52 + other * fontSize * 0.48;
}

function simpleMedian(numbers, fallback = 0) {
  const values = (numbers || []).map(Number).filter((value) => Number.isFinite(value) && value > 0).sort((a, b) => a - b);
  if (!values.length) return fallback;
  const mid = Math.floor(values.length / 2);
  return values.length % 2 ? values[mid] : (values[mid - 1] + values[mid]) / 2;
}

function simpleTextStats(text) {
  const value = normalizeExtractedPdfText(text || "");
  const cjk = (value.match(/[\u3400-\u9fff]/g) || []).length;
  const latinChars = (value.match(/[A-Za-z]/g) || []).length;
  const latinWords = (value.match(/[A-Za-z]+(?:[-'][A-Za-z]+)*/g) || []).length;
  const chars = Math.max(1, value.length);
  return {
    text: value,
    cjk,
    latinChars,
    latinWords,
    chineseRatio: cjk / chars,
    latinRatio: latinChars / chars,
    isMostlyCjk: cjk > 0 && cjk >= latinChars * 0.7,
    isMostlyLatin: latinChars > cjk,
  };
}

function simpleEstimateBodyLineMetrics(lines) {
  const source = (lines || []).filter((line) => normalizeExtractedPdfText(line.text || ""));
  const pageHeights = source.map((line) => Number(line.pageHeight || 0)).filter(Boolean);
  const pageHeight = simpleMedian(pageHeights, 792);
  const bodyCandidates = source.filter((line) => {
    const y = Number(line.y || 0);
    const text = normalizeExtractedPdfText(line.text || "");
    return y > pageHeight * 0.12 && y < pageHeight * 0.88 && text.length >= 12;
  });
  const target = bodyCandidates.length ? bodyCandidates : source;
  const sorted = source.slice().sort((a, b) => Number(a.pageNumber || 0) - Number(b.pageNumber || 0) || Number(a.y || 0) - Number(b.y || 0));
  const gaps = [];
  for (let i = 1; i < sorted.length; i += 1) {
    if (Number(sorted[i].pageNumber || 0) !== Number(sorted[i - 1].pageNumber || 0)) continue;
    const gap = Number(sorted[i].y || 0) - Number(sorted[i - 1].y || 0);
    if (gap > 2 && gap < 80) gaps.push(gap);
  }
  const font = simpleMedian(target.map((line) => Number(line.fontSize || 0)), 11);
  const bodyX = simpleMedian(target.map((line) => Number(line.x || 0)), 54);
  const widths = target.map(simpleEstimateLineWidth).filter((value) => value > font * 4);
  const pageWidth = simpleMedian(source.map((line) => Number(line.pageWidth || 0)).filter(Boolean), 595);
  return {
    bodyX,
    bodyFontSize: font,
    normalLineGap: simpleMedian(gaps, font * 1.35),
    bodyLineWidthEstimate: simpleMedian(widths, pageWidth * 0.72),
    pageTopThreshold: pageHeight * 0.08,
    pageBottomThreshold: pageHeight * 0.92,
  };
}

function simpleIsNumberedListStart(lineOrText) {
  const text = normalizeExtractedPdfText(typeof lineOrText === "string" ? lineOrText : lineOrText && lineOrText.text || "");
  return /^\s*(?:\d+[.)]\s+|\([0-9]+\)\s+|第?[一二三四五六七八九十]+[、.．]\s*)/.test(text);
}

function simpleIsBulletListStart(lineOrText) {
  const text = normalizeExtractedPdfText(typeof lineOrText === "string" ? lineOrText : lineOrText && lineOrText.text || "");
  return /^\s*(?:[-*•●◆◇▪▫]\s+|[a-zA-Z][.)]\s+)/.test(text);
}

function simpleIsChineseSectionMarker(lineOrText) {
  const text = normalizeExtractedPdfText(typeof lineOrText === "string" ? lineOrText : lineOrText && lineOrText.text || "");
  return /^\s*(?:第[一二三四五六七八九十百\d]+[章节篇]|[一二三四五六七八九十]+[、.．]\s*)/.test(text);
}

function simpleIsSourceLine(lineOrText) {
  const text = normalizeExtractedPdfText(typeof lineOrText === "string" ? lineOrText : lineOrText && lineOrText.text || "");
  if (!text) return false;
  if (/^(?:Professor|Mr\.|Mrs\.|Dr\.)\s+[A-Z][A-Za-z' -]+(?:\s*\(.+\))?$/i.test(text)) return true;
  if (/\b(?:Essay|Letter|pamphlet|Tribune|Expression|Interglossia|Politics|New York)\b/i.test(text) && text.length <= 120) return true;
  if (/^[A-Z][A-Za-z' -]+\s+\([^)]+\)$/.test(text)) return true;
  return false;
}

function simpleIsQuoteLikeLine(lineOrText) {
  const text = normalizeExtractedPdfText(typeof lineOrText === "string" ? lineOrText : lineOrText && lineOrText.text || "");
  return /^[“"']|[”"']$/.test(text) || /^\s{0,2}>/.test(text);
}

function simpleEndsWithStrongSentencePunctuation(text) {
  return /[。！？.!?]$/.test(normalizeExtractedPdfText(text || ""));
}

function simpleEndsWithSentencePunctuation(text) {
  return /[。！？；：.!?;:]$/.test(normalizeExtractedPdfText(text || ""));
}

function simpleEndsWithCommaLikePunctuation(text) {
  return /[，、,；;：:]$/.test(normalizeExtractedPdfText(text || ""));
}

function simpleLooksTitleCase(text) {
  const words = String(text || "").match(/[A-Za-z][A-Za-z'-]*/g) || [];
  if (words.length < 2 || words.length > 16) return false;
  const important = words.filter((word) => !/^(and|or|the|a|an|of|in|on|to|for|with)$/i.test(word));
  const capped = important.filter((word) => /^[A-Z]/.test(word));
  return important.length > 0 && capped.length / important.length >= 0.72;
}

function simpleAnnotateLineFeatures(lines, metrics = simpleEstimateBodyLineMetrics(lines)) {
  const sorted = (lines || []).slice().sort((a, b) => Number(a.pageNumber || 0) - Number(b.pageNumber || 0) || Number(a.y || 0) - Number(b.y || 0) || Number(a.x || 0) - Number(b.x || 0));
  return sorted.map((line, index) => {
    const text = normalizeExtractedPdfText(line.text || "");
    const stats = simpleTextStats(text);
    const previous = index > 0 && Number(sorted[index - 1].pageNumber || 0) === Number(line.pageNumber || 0) ? sorted[index - 1] : null;
    const gap = previous ? Number(line.y || 0) - Number(previous.y || 0) : 0;
    const lineWidthEstimate = simpleEstimateLineWidth(line);
    const pageWidth = Number(line.pageWidth || 0) || 595;
    const centerX = Number(line.x || 0) + lineWidthEstimate / 2;
    const indentDelta = Number(line.x || 0) - Number(metrics.bodyX || 0);
    return {
      pageNumber: Number(line.pageNumber || 0),
      lineNumber: Number(line.lineNumber || 0),
      lineId: simpleLineId(line),
      text,
      x: Number(line.x || 0),
      y: Number(line.y || 0),
      fontSize: Number(line.fontSize || 0),
      pageWidth: Number(line.pageWidth || 0),
      pageHeight: Number(line.pageHeight || 0),
      textCharCount: text.length,
      latinRatio: stats.latinRatio,
      chineseRatio: stats.chineseRatio,
      isMostlyChinese: stats.isMostlyCjk,
      isMostlyLatin: stats.isMostlyLatin,
      isShortLine: stats.isMostlyCjk ? stats.cjk <= 30 : stats.latinWords <= 12,
      isVeryShortLine: stats.isMostlyCjk ? stats.cjk <= 10 : stats.latinWords <= 4,
      startsWithLowercaseLatin: /^[a-z]/.test(text),
      startsWithNumberedList: simpleIsNumberedListStart(text),
      startsWithBullet: simpleIsBulletListStart(text),
      startsWithChineseSectionMarker: simpleIsChineseSectionMarker(text),
      endsWithSentencePunctuation: simpleEndsWithSentencePunctuation(text),
      endsWithStrongSentencePunctuation: simpleEndsWithStrongSentencePunctuation(text),
      endsWithCommaLikePunctuation: simpleEndsWithCommaLikePunctuation(text),
      endsWithHyphen: /[A-Za-z]-$/.test(text),
      gapFromPrevious: gap,
      gapRatioFromPrevious: metrics.normalLineGap ? gap / Math.max(1, metrics.normalLineGap) : 0,
      indentDeltaFromBody: indentDelta,
      isIndented: indentDelta > Math.max(10, Number(metrics.bodyFontSize || 10) * 0.75),
      isCenteredCandidate: Math.abs(centerX - pageWidth / 2) < pageWidth * 0.14,
      lineWidthRatioEstimate: pageWidth ? lineWidthEstimate / pageWidth : 0,
      isSourceLine: simpleIsSourceLine(text),
      isQuoteLikeLine: simpleIsQuoteLikeLine(text),
    };
  });
}

function simpleRemoveHeadersFooters(lines) {
  const byText = new Map();
  (lines || []).forEach((line) => {
    const key = normalizeExtractedPdfText(line.text || "");
    if (!key) return;
    if (!byText.has(key)) byText.set(key, new Set());
    byText.get(key).add(Number(line.pageNumber || 0));
  });
  const pageCount = new Set((lines || []).map((line) => Number(line.pageNumber || 0))).size;
  const stats = { removedHeaderFooterCount: 0, removedPageNumberCount: 0 };
  const kept = (lines || []).filter((line) => {
    const text = normalizeExtractedPdfText(line.text || "");
    if (!text) return false;
    const pageHeight = Number(line.pageHeight || 0);
    const nearTop = pageHeight > 0 && Number(line.y || 0) < pageHeight * 0.06;
    const nearBottom = pageHeight > 0 && Number(line.y || 0) > pageHeight * 0.92;
    const shortText = text.length <= 48;
    const repeated = pageCount >= 3 && byText.has(text) && byText.get(text).size >= Math.max(2, Math.ceil(pageCount * 0.5));
    const firstPageYearLikeMeta = Number(line.pageNumber || 0) === 1 &&
      /^(?:18|19|20)\d{2}$/.test(text) &&
      pageHeight > 0 &&
      Number(line.y || 0) < pageHeight * 0.45;
    if (!firstPageYearLikeMeta && /^(?:[-–—*]?\s*)?(?:\d{1,4}|Page\s+\d{1,4}|第\s*\d{1,4}\s*页)(?:\s*[-–—*]?)$/i.test(text)) {
      stats.removedPageNumberCount += 1;
      return false;
    }
    if ((nearTop || nearBottom) && repeated && shortText) {
      stats.removedHeaderFooterCount += 1;
      return false;
    }
    if ((nearTop || nearBottom) && /https?:\/\/|www\.|downloaded from|copyright|©|watermark/i.test(text)) {
      stats.removedHeaderFooterCount += 1;
      return false;
    }
    return true;
  });
  simpleRemoveHeadersFooters.lastStats = stats;
  return kept;
}

function simpleIsMetaLine(line) {
  const text = normalizeExtractedPdfText(line && line.text || "");
  if (!text) return false;
  if (/^(?:19|20)\d{2}(?:[-/年.]\d{1,2})?(?:[-/月.]\d{1,2}日?)?$/.test(text)) return true;
  if (/^(?:作者|撰文|日期)[:：]\s*\S+/.test(text)) return true;
  const allWords = text.match(/[A-Za-z'’-]+/g) || [];
  const capitalizedWords = text.match(/[A-Z][A-Za-z'’-]*/g) || [];
  const hasTitleConnector = /\b(?:and|or|of|the|in|on|to|for|with)\b/i.test(text);
  if (allWords.length >= 2 && allWords.length <= 4 && capitalizedWords.length === allWords.length && !hasTitleConnector) return true;
  return false;
}

function simpleIsTitleCandidate(line, metrics) {
  const text = normalizeExtractedPdfText(line && line.text || "");
  if (!text || /^[\d\s-]+$/.test(text)) return false;
  const stats = simpleTextStats(text);
  const yLimit = Number(line.pageHeight || 0) ? Number(line.pageHeight || 0) * 0.30 : 220;
  if (Number(line.y || 0) > yLimit) return false;
  if (simpleEndsWithStrongSentencePunctuation(text) || /[.;。！？]$/.test(text)) return false;
  const shortEnough = stats.isMostlyCjk ? stats.cjk <= 30 : stats.latinWords >= 2 && stats.latinWords <= 18;
  const fontLooksLarge = Number(metrics && metrics.bodyFontSize || 0) > 0 && Number(line.fontSize || 0) >= Number(metrics.bodyFontSize || 0) * 1.08;
  const centered = Boolean(line.isCenteredCandidate);
  const titleCase = simpleLooksTitleCase(text);
  return Boolean(shortEnough && (stats.isMostlyCjk || titleCase || centered || fontLooksLarge) && (centered || fontLooksLarge || titleCase));
}

function simpleDetectFrontMatter(lines, metrics) {
  const firstPageLines = (lines || []).filter((line) => Number(line.pageNumber || 0) === 1);
  const topLines = firstPageLines.filter((line) => Number(line.y || 0) <= (Number(line.pageHeight || 0) || 792) * 0.45).slice(0, 12);
  const titleLineIds = [];
  const metaLineIds = [];
  let bodyStartLineId = "";
  let reason = "";
  let titleSeen = false;
  for (let i = 0; i < topLines.length; i += 1) {
    const line = topLines[i];
    const text = normalizeExtractedPdfText(line.text || "");
    if (!text) continue;
    const looksBody = text.length >= 55 || (line.lineWidthRatioEstimate > 0.48 && simpleEndsWithSentencePunctuation(text));
    if (!titleSeen && simpleIsTitleCandidate(line, metrics)) {
      titleLineIds.push(line.lineId);
      titleSeen = true;
      reason = "simple_front_matter_title";
      continue;
    }
    if (titleSeen && simpleIsMetaLine(line)) {
      metaLineIds.push(line.lineId);
      continue;
    }
    if (titleSeen && looksBody) {
      bodyStartLineId = line.lineId;
      break;
    }
    if (!titleSeen && looksBody) {
      bodyStartLineId = line.lineId;
      break;
    }
  }
  return { titleLineIds, metaLineIds, bodyStartLineId, reason };
}

function simpleDetectTitle(lines, metrics = simpleEstimateBodyLineMetrics(lines)) {
  const frontMatter = simpleDetectFrontMatter(lines, metrics);
  const titleLine = (lines || []).find((line) => frontMatter.titleLineIds.includes(line.lineId)) || null;
  return { titleLine, titleDetected: Boolean(titleLine), frontMatter };
}

function simpleLineKey(line) {
  return line && line.lineId ? line.lineId : [line && line.pageNumber, line && line.lineNumber, line && line.text].join("|");
}

function simpleLooksShortSubheading(line) {
  const text = normalizeExtractedPdfText(line && line.text || "");
  if (!text || simpleEndsWithSentencePunctuation(text)) return false;
  if (line.startsWithNumberedList || line.startsWithBullet || line.startsWithChineseSectionMarker) return true;
  if (line.isMostlyChinese) return text.length <= 16 && line.isShortLine;
  return line.isMostlyLatin && line.isShortLine && (simpleLooksTitleCase(text) || /^[A-Z][A-Z\s-]{3,}$/.test(text));
}

function simpleComputeParagraphBreakScore(prevLine, currLine, context) {
  const reasons = [];
  let score = 0;
  if (!prevLine || !currLine) return { shouldBreak: true, score: 100, reasons: ["first_line"] };
  const titleIds = context && context.titleLineIds || new Set();
  const metaIds = context && context.metaLineIds || new Set();
  if (titleIds.has(currLine.lineId)) { score += 100; reasons.push("current_title_line"); }
  if (currLine.startsWithNumberedList) { score += 90; reasons.push("numbered_list_start"); }
  if (currLine.startsWithBullet) { score += 85; reasons.push("bullet_list_start"); }
  if (currLine.startsWithChineseSectionMarker) { score += 80; reasons.push("chinese_section_marker"); }
  if (metaIds.has(currLine.lineId) || (metaIds.has(prevLine.lineId) && !metaIds.has(currLine.lineId))) { score += 75; reasons.push("front_matter_boundary"); }
  if (Number(prevLine.pageNumber || 0) !== Number(currLine.pageNumber || 0)) {
    score += 35; reasons.push("page_boundary");
  } else if (currLine.gapRatioFromPrevious > 1.6) {
    score += 70; reasons.push("large_line_gap");
  }
  if (currLine.isIndented && prevLine.endsWithStrongSentencePunctuation) { score += 60; reasons.push("indented_after_complete_sentence"); }
  if (simpleLooksShortSubheading(currLine) && prevLine.endsWithStrongSentencePunctuation) { score += 55; reasons.push("short_subheading_like_line"); }
  if (currLine.isSourceLine) { score += 50; reasons.push("source_line"); }
  if (prevLine.isSourceLine && currLine.startsWithNumberedList) { score += 45; reasons.push("source_to_numbered_list"); }
  if (prevLine.isVeryShortLine && prevLine.endsWithStrongSentencePunctuation) { score += 40; reasons.push("previous_short_complete_line"); }

  if (prevLine.endsWithHyphen && currLine.startsWithLowercaseLatin) { score -= 100; reasons.push("hyphen_continuation"); }
  if (!prevLine.endsWithSentencePunctuation) { score -= 80; reasons.push("previous_not_sentence_end"); }
  if (currLine.startsWithLowercaseLatin && !prevLine.endsWithStrongSentencePunctuation) { score -= 70; reasons.push("lowercase_continuation"); }
  if (!(prevLine.endsWithStrongSentencePunctuation && currLine.isIndented) &&
    currLine.gapRatioFromPrevious > 0 &&
    currLine.gapRatioFromPrevious <= 1.35 &&
    Math.abs(Number(currLine.x || 0) - Number(prevLine.x || 0)) <= Math.max(18, Number(context && context.metrics && context.metrics.bodyFontSize || 11) * 2)) {
    score -= 60; reasons.push("normal_gap_same_baseline");
  }
  if (prevLine.isMostlyChinese && currLine.isMostlyChinese && !/[。！？；]$/.test(prevLine.text)) { score -= 50; reasons.push("chinese_continuous_line"); }
  if (!currLine.startsWithNumberedList && !currLine.startsWithBullet && !simpleLooksShortSubheading(currLine) && prevLine.lineWidthRatioEstimate > 0.45) {
    score -= 40; reasons.push("previous_full_width_line");
  }
  if (prevLine.endsWithCommaLikePunctuation) { score -= 30; reasons.push("comma_like_continuation"); }
  return { shouldBreak: score >= 50, score, reasons };
}

function simpleMergeParagraphs(lines, titleInfo, metrics = simpleEstimateBodyLineMetrics(lines)) {
  const frontMatter = titleInfo && titleInfo.frontMatter || { titleLineIds: [], metaLineIds: [] };
  const titleIds = new Set(frontMatter.titleLineIds || []);
  const metaIds = new Set(frontMatter.metaLineIds || []);
  const bodyLines = (lines || []).filter((line) => !titleIds.has(simpleLineKey(line)));
  const paragraphs = [];
  let current = [];
  let currentBreakReasons = [];
  const flush = () => {
    if (!current.length) return;
    paragraphs.push({ lines: current, breakReasons: currentBreakReasons.slice() });
    current = [];
    currentBreakReasons = [];
  };
  bodyLines.forEach((line) => {
    const previous = current[current.length - 1];
    if (!previous) {
      current.push(line);
      return;
    }
    const decision = simpleComputeParagraphBreakScore(previous, line, { metrics, titleLineIds: titleIds, metaLineIds: metaIds });
    if (decision.shouldBreak) {
      currentBreakReasons.push({ beforeLineId: previous.lineId, currentLineId: line.lineId, score: decision.score, reasons: decision.reasons });
      flush();
      current = [line];
      currentBreakReasons = [{ atLineId: line.lineId, score: decision.score, reasons: decision.reasons }];
      return;
    }
    currentBreakReasons.push({ joinedLineId: line.lineId, score: decision.score, reasons: decision.reasons });
    current.push(line);
  });
  flush();
  return paragraphs;
}

function simpleMakeBlockFromLines(id, type, lines, outputOrder, extra = {}) {
  const sourceText = simpleJoinParagraphLines(lines || []);
  const firstLine = lines && lines[0] || {};
  const lastLine = lines && lines[lines.length - 1] || firstLine;
  return {
    id,
    type: simpleNormalizeBlockType(type),
    sourceText,
    translatedText: "",
    status: "pending",
    sourcePageRange: [Number(firstLine.pageNumber || 0), Number(lastLine.pageNumber || firstLine.pageNumber || 0)],
    sourceLineRange: [Number(firstLine.lineNumber || 0), Number(lastLine.lineNumber || firstLine.lineNumber || 0)],
    outputOrder,
    firstLinePageNumber: Number(firstLine.pageNumber || 0),
    lastLinePageNumber: Number(lastLine.pageNumber || firstLine.pageNumber || 0),
    crossedPageBoundary: Number(firstLine.pageNumber || 0) !== Number(lastLine.pageNumber || firstLine.pageNumber || 0),
    mergeReason: extra.mergeReason || (Number(firstLine.pageNumber || 0) !== Number(lastLine.pageNumber || firstLine.pageNumber || 0) ? "simple_cross_page_paragraph_continuation" : ""),
    breakReasons: extra.breakReasons || [],
    splitReason: extra.splitReason || "",
    error: "",
  };
}

function simpleNormalizeBlockType(type) {
  const value = String(type || "body");
  if (["title", "paragraph", "body", "header", "footer", "pageNumber", "noise", "watermark", "margin"].includes(value)) return value;
  if (["abstract", "abstract-title", "keywords", "heading", "caption", "reference", "formula", "imageText", "author", "affiliation", "correspondence", "funding", "receivedDate"].includes(value)) return "body";
  return "body";
}

function simpleJoinParagraphLines(lines) {
  let text = "";
  (lines || []).forEach((line) => {
    const current = normalizeExtractedPdfText(line && line.text || "");
    if (!current) return;
    if (!text) {
      text = current;
      return;
    }
    if (/[A-Za-z]-$/.test(text) && /^[a-z]/.test(current)) {
      text = text.slice(0, -1) + current;
      return;
    }
    const previousCjk = /[\u3400-\u9fff]$/.test(text);
    const currentCjk = /^[\u3400-\u9fff]/.test(current);
    text += previousCjk || currentCjk ? current : " " + current;
  });
  return normalizeExtractedPdfText(text);
}

function simpleShouldMergeCrossPageBlocks(previous, block) {
  if (!previous || !block) return { merge: false, reasonSignals: ["missing_block"], confidence: 0 };
  if (previous.type !== "body" || block.type !== "body") return { merge: false, reasonSignals: ["type_mismatch"], confidence: 0 };
  if (Number(previous.lastLinePageNumber || 0) + 1 !== Number(block.firstLinePageNumber || 0)) return { merge: false, reasonSignals: ["non_contiguous_pages"], confidence: 0 };
  const prevText = normalizeExtractedPdfText(previous.sourceText || "");
  const nextText = normalizeExtractedPdfText(block.sourceText || "");
  if (simpleEndsWithStrongSentencePunctuation(prevText)) return { merge: false, reasonSignals: ["previous_complete_sentence"], confidence: 0 };
  if (simpleIsNumberedListStart(nextText) || simpleIsBulletListStart(nextText) || simpleIsChineseSectionMarker(nextText) || simpleIsSourceLine(nextText)) {
    return { merge: false, reasonSignals: ["next_starts_new_structure"], confidence: 0 };
  }
  const signals = ["previous_not_strong_sentence_end"];
  let confidence = 0.62;
  if (/^[a-z,，、；;：:）)]/.test(nextText)) { signals.push("next_continuation_head"); confidence += 0.2; }
  if (/[，、,；;：:]$/.test(prevText)) { signals.push("previous_weak_punctuation"); confidence += 0.12; }
  if (!/[。！？；.!?;:]$/.test(prevText)) { signals.push("previous_no_sentence_punctuation"); confidence += 0.08; }
  return { merge: confidence >= 0.62, reasonSignals: signals, confidence: Math.min(0.98, confidence) };
}

function simpleMergeCrossPageParagraphs(blocks) {
  const output = [];
  const pairs = [];
  (blocks || []).forEach((block) => {
    const previous = output[output.length - 1];
    const decision = simpleShouldMergeCrossPageBlocks(previous, block);
    if (decision.merge) {
      const previousId = previous.id;
      const nextId = block.id;
      previous.sourceText = makeParagraphSourceText([{ text: previous.sourceText }, { text: block.sourceText }]);
      previous.lastLinePageNumber = block.lastLinePageNumber;
      previous.sourcePageRange = [previous.firstLinePageNumber, block.lastLinePageNumber];
      previous.sourceLineRange = [previous.sourceLineRange[0], block.sourceLineRange[1]];
      previous.crossedPageBoundary = true;
      previous.mergeReason = "simple_cross_page_paragraph_continuation";
      previous.breakReasons = [...(previous.breakReasons || []), { crossPageMergedBlockId: nextId, reasons: decision.reasonSignals, confidence: decision.confidence }];
      pairs.push({
        previousBlockId: previousId,
        nextBlockId: nextId,
        previousTextTail: makePreviewText((previous.sourceText || "").slice(-120)),
        nextTextHead: makePreviewText((block.sourceText || "").slice(0, 120)),
        reasonSignals: decision.reasonSignals,
        confidence: decision.confidence,
      });
      return;
    }
    output.push(block);
  });
  const merged = output.map((block, index) => ({ ...block, id: `simple-${index + 1}`, outputOrder: index + 1 }));
  simpleMergeCrossPageParagraphs.lastPairs = pairs;
  return merged;
}

function simpleGetOverlongLimit(text) {
  const stats = simpleTextStats(text);
  if (stats.chineseRatio >= 0.35) return 900;
  if (stats.latinRatio >= 0.45) return 1400;
  return 1100;
}

function simpleSentenceSplitText(text, maxChars) {
  const value = normalizeExtractedPdfText(text || "");
  if (value.length <= maxChars) return [value];
  const chunks = [];
  let start = 0;
  const punctuation = /[。！？；.!?;:]/g;
  let match;
  let lastCut = 0;
  while ((match = punctuation.exec(value))) {
    const cut = match.index + 1;
    const sliceLen = cut - start;
    const previous = value.slice(Math.max(0, match.index - 3), match.index + 1);
    if (/\b(?:Mr|Mrs|Ms|Dr|Prof|St|No)\.$/.test(previous) || /\d\.\d$/.test(value.slice(Math.max(0, match.index - 1), match.index + 2))) continue;
    if (sliceLen >= maxChars * 0.55) {
      chunks.push(value.slice(start, cut).trim());
      start = cut;
      lastCut = cut;
    }
  }
  if (start < value.length) chunks.push(value.slice(start).trim());
  if (chunks.some((chunk) => chunk.length > maxChars * 1.25) || !lastCut) return [value];
  return chunks.filter(Boolean);
}

function simpleSplitOverlongBlocks(blocks) {
  const output = [];
  let splitCount = 0;
  (blocks || []).forEach((block) => {
    if (!["body", "paragraph"].includes(String(block.type || "body"))) {
      output.push(block);
      return;
    }
    const limit = simpleGetOverlongLimit(block.sourceText || "");
    if (cleanPdfText(block.sourceText || "").length <= limit) {
      output.push(block);
      return;
    }
    const chunks = simpleSentenceSplitText(block.sourceText || "", limit);
    if (chunks.length <= 1) {
      output.push(block);
      return;
    }
    splitCount += chunks.length - 1;
    chunks.forEach((chunk, index) => {
      appendSegment({
        ...block,
        sourceText: chunk,
        splitReason: "simple_overlong_block_sentence_split",
        mergeReason: index === 0 && block.crossedPageBoundary ? block.mergeReason || "simple_cross_page_paragraph_continuation" : "",
        crossedPageBoundary: index === 0 ? block.crossedPageBoundary : false,
      });
    });
  });
  simpleSplitOverlongBlocks.lastSplitCount = splitCount;
  return output.map((block, index) => ({ ...block, id: `simple-${index + 1}`, outputOrder: index + 1 }));
}

function simpleBuildCrossPageMergePairsFromBlocks(blocks) {
  return (blocks || []).filter((block) => block.crossedPageBoundary).map((block) => ({
    previousBlockId: block.id,
    nextBlockId: block.id,
    previousTextTail: makePreviewText((block.sourceText || "").slice(0, 120)),
    nextTextHead: makePreviewText((block.sourceText || "").slice(-120)),
    reasonSignals: ["block_spans_page_boundary", block.mergeReason || "simple_cross_page_paragraph_continuation"],
    confidence: 0.82,
  }));
}

function simpleBuildBlocks(lines, titleInfo) {
  const blocks = [];
  let outputOrder = 1;
  if (titleInfo && titleInfo.titleLine) {
    blocks.push(simpleMakeBlockFromLines(`simple-${outputOrder}`, "title", [titleInfo.titleLine], outputOrder));
    outputOrder += 1;
  }
  const metrics = simpleEstimateBodyLineMetrics(lines);
  const frontMatter = titleInfo && titleInfo.frontMatter || {};
  const metaIds = new Set(frontMatter.metaLineIds || []);
  simpleMergeParagraphs(lines, titleInfo, metrics).forEach((paragraph) => {
    const paragraphLines = Array.isArray(paragraph) ? paragraph : paragraph.lines || [];
    if (!paragraphLines.length) return;
    blocks.push(simpleMakeBlockFromLines(`simple-${outputOrder}`, "body", paragraphLines, outputOrder, {
      mergeReason: paragraphLines.some((line) => metaIds.has(line.lineId)) ? "simple_front_matter_meta" : "",
      breakReasons: paragraph.breakReasons || [],
    }));
    outputOrder += 1;
  });
  return simpleSplitOverlongBlocks(simpleMergeCrossPageParagraphs(blocks).filter((block) => cleanPdfText(block.sourceText)));
}

function runSimplePdfSimplifiedCore(pageItemsByPage, config) {
  if (!isSimplePdfV2Config(config)) throw new Error("runSimplePdfSimplifiedCore requires simple_pdf simplified config");
  const extractedLines = simpleExtractLinesFromPageItems(pageItemsByPage);
  const normalizedLines = simpleNormalizeLines(extractedLines);
  const preMetrics = simpleEstimateBodyLineMetrics(normalizedLines);
  const featuredLines = simpleAnnotateLineFeatures(normalizedLines, preMetrics);
  const sourceLines = simpleAnnotateLineFeatures(simpleRemoveHeadersFooters(featuredLines), simpleEstimateBodyLineMetrics(featuredLines));
  const metrics = simpleEstimateBodyLineMetrics(sourceLines);
  const titleInfo = simpleDetectTitle(sourceLines, metrics);
  const blocks = simpleBuildBlocks(sourceLines, titleInfo);
  assertSimpleMainBoundary(blocks);
  const removalStats = simpleRemoveHeadersFooters.lastStats || {};
  const sourceTextChars = sourceLines.reduce((sum, line) => sum + cleanPdfText(line.text || "").length, 0);
  const sourcePageCount = pageItemsByPage && pageItemsByPage.size ? pageItemsByPage.size : 0;
  const inputKind = sourcePageCount > 0 && (sourceLines.length === 0 || sourceTextChars < Math.max(12, sourcePageCount * 8)) ? "scan_pdf" : "text_pdf";
  const summary = simpleBuildReport(blocks, {
    inputKind,
    sourceLineCount: sourceLines.length,
    sourcePageCount,
    writtenBlockCount: 0,
    removedHeaderFooterCount: Number(removalStats.removedHeaderFooterCount || 0),
    removedPageNumberCount: Number(removalStats.removedPageNumberCount || 0),
    metaLineCount: titleInfo && titleInfo.frontMatter ? titleInfo.frontMatter.metaLineIds.length : 0,
    bodyStartLineId: titleInfo && titleInfo.frontMatter ? titleInfo.frontMatter.bodyStartLineId : "",
    overlongBlockSplitCount: Number(simpleSplitOverlongBlocks.lastSplitCount || 0),
    crossPageMergePairs: (simpleMergeCrossPageParagraphs.lastPairs && simpleMergeCrossPageParagraphs.lastPairs.length)
      ? simpleMergeCrossPageParagraphs.lastPairs
      : simpleBuildCrossPageMergePairsFromBlocks(blocks),
  });
  if (inputKind === "scan_pdf") {
    summary.scanPdfNotSupported = true;
    summary.userMessage = "该 PDF 可能是扫描件或图片型 PDF，当前普通版无法提取文字，请使用 OCR 模式。";
  }
  return {
    text: blocks.map((block) => block.sourceText).filter(Boolean).join("\n\n"),
    simpleBlocks: blocks,
    segments: blocks,
    lines: sourceLines,
    rawLines: sourceLines,
    paragraphs: [],
    paperSegments: [],
    pipelineDebug: { summary, pages: [], blocks: simpleBuildBlockDebugReport(blocks), crossPageMergePairs: summary.crossPageMergePairs || [] },
  };
}


async function exportTranslatedTxt(payload) {
  validatePdfTranslationMode(payload);
  const focused = BrowserWindow.getFocusedWindow();
  const fileName = String(payload && payload.fileName ? payload.fileName : "pdf.pdf");
  const content = String(payload && payload.content ? payload.content : "");
  if (!content.trim()) {
    return { ok: false, canceled: false, error: "empty_content" };
  }
  const defaultPath = path.join(app.getPath("documents"), `${safeTxtBaseName(fileName)}_translated.txt`);
  const result = await dialog.showSaveDialog(focused || undefined, {
    title: "保存翻译 TXT",
    defaultPath,
    filters: [{ name: "Text", extensions: ["txt"] }],
  });
  if (result.canceled || !result.filePath) {
    return { ok: false, canceled: true };
  }
  fs.writeFileSync(result.filePath, content, { encoding: "utf8" });
  return { ok: true, filePath: result.filePath };
}

async function exportTranslatedDocx(payload) {
  validatePdfTranslationMode(payload);
  const focused = BrowserWindow.getFocusedWindow();
  const fileName = String(payload && payload.fileName ? payload.fileName : "pdf.pdf");
  const paragraphs = Array.isArray(payload && payload.paragraphs)
    ? payload.paragraphs.map((item) => String(item || "").trim()).filter(Boolean)
    : [];
  if (!paragraphs.length) {
    return { ok: false, canceled: false, error: "empty_content" };
  }

  const defaultPath = path.join(app.getPath("documents"), `${safeTxtBaseName(fileName)}_translated.docx`);
  const result = await dialog.showSaveDialog(focused || undefined, {
    title: "保存翻译 DOCX",
    defaultPath,
    filters: [{ name: "Word Document", extensions: ["docx"] }],
  });
  if (result.canceled || !result.filePath) {
    return { ok: false, canceled: true };
  }

  const children = [];
  paragraphs.forEach((text, index) => {
    children.push(new Paragraph({
      children: [new TextRun({ text, font: "Microsoft YaHei", size: 24 })],
      spacing: { after: 180 },
    }));
    if (index < paragraphs.length - 1) {
      children.push(new Paragraph({ children: [new TextRun({ text: "", font: "Microsoft YaHei", size: 24 })] }));
    }
  });

  const doc = new Document({
    styles: {
      default: {
        document: {
          run: { font: "Microsoft YaHei", size: 24 },
          paragraph: { spacing: { line: 360 } },
        },
      },
    },
    sections: [{ properties: {}, children }],
  });
  const buffer = await Packer.toBuffer(doc);
  fs.writeFileSync(result.filePath, buffer);
  return { ok: true, filePath: result.filePath };
}

function getCjkFontCandidates() {
  return [
    "C:\\Windows\\Fonts\\msyh.ttc",
    "C:\\Windows\\Fonts\\simsun.ttc",
    "C:\\Windows\\Fonts\\simhei.ttf",
    "/System/Library/Fonts/PingFang.ttc",
    "/System/Library/Fonts/STHeiti Light.ttc",
    "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",
    "/usr/share/fonts/truetype/noto/NotoSansCJK-Regular.ttc",
    "C:\\Windows\\Fonts\\Noto Sans SC (TrueType).otf",
    "C:\\Windows\\Fonts\\NotoSansSC-VF.ttf",
    "C:\\Windows\\Fonts\\Deng.ttf",
  ];
}

function findCjkFontPath() {
  return getCjkFontCandidates().find((candidate) => fs.existsSync(candidate)) || null;
}

let cachedCjkFont = null;
let cachedCjkFontDoc = null;
let cachedCjkFontMeta = null;
let cjkFontEmbedCallCount = 0;

function resetCjkFontExportCache() {
  cachedCjkFont = null;
  cachedCjkFontDoc = null;
  cachedCjkFontMeta = null;
  cjkFontEmbedCallCount = 0;
}

async function canDrawWithCjkFont(fontPath) {
  const probeDoc = await PDFDocument.create();
  probeDoc.registerFontkit(fontkit);
  const probeFont = await probeDoc.embedFont(fs.readFileSync(fontPath), { subset: false });
  const probePage = probeDoc.addPage([220, 80]);
  probePage.drawText("中文字体测试", {
    x: 10,
    y: 40,
    size: 12,
    font: probeFont,
    color: rgb(0, 0, 0),
  });
  await probeDoc.save();
  return true;
}

async function loadCjkFontLegacyUnused(pdfDoc) {
  if (cachedCjkFont && cachedCjkFontDoc === pdfDoc) {
    return cachedCjkFontMeta;
  }
  pdfDoc.registerFontkit(fontkit);
  const candidates = getCjkFontCandidates().filter((candidate) => fs.existsSync(candidate));
  for (const fontPath of candidates) {
    try {
      const fontBytes = fs.readFileSync(fontPath);
      try {
        cjkFontEmbedCallCount += 1;
        const embeddedCjkFont = await pdfDoc.embedFont(fontBytes, { subset: true });
        cachedCjkFont = embeddedCjkFont;
        cachedCjkFontDoc = pdfDoc;
        cachedCjkFontMeta = { font: embeddedCjkFont, fontPath, subset: true, embedFontCalls: cjkFontEmbedCallCount };
        debugPdfLog("[pdf-export] using cjk font:", fontPath, "subset=true", "embedFontCalls=", cjkFontEmbedCallCount);
        return cachedCjkFontMeta;
      } catch (subsetError) {
        debugPdfWarn("[pdf-export] cjk font subset failed, fallback to full font:", fontPath, subsetError && subsetError.message ? subsetError.message : subsetError);
        cjkFontEmbedCallCount += 1;
        const embeddedCjkFont = await pdfDoc.embedFont(fontBytes, { subset: false });
        cachedCjkFont = embeddedCjkFont;
        cachedCjkFontDoc = pdfDoc;
        cachedCjkFontMeta = { font: embeddedCjkFont, fontPath, subset: false, embedFontCalls: cjkFontEmbedCallCount };
        debugPdfLog("[pdf-export] using cjk font:", fontPath, "subset=false", "embedFontCalls=", cjkFontEmbedCallCount);
        return cachedCjkFontMeta;
      }
    } catch (error) {
      debugPdfWarn("[pdf-export] skipped cjk font:", fontPath, error && error.message ? error.message : error);
    }
  }
  throw new Error("未找到中文字体，无法正确导出中文 PDF。");
}

async function loadCjkFont(pdfDoc) {
  if (cachedCjkFont && cachedCjkFontDoc === pdfDoc) {
    return cachedCjkFontMeta;
  }
  pdfDoc.registerFontkit(fontkit);
  const candidates = getCjkFontCandidates().filter((candidate) => fs.existsSync(candidate));

  for (const fontPath of candidates) {
    try {
      const probeDoc = await PDFDocument.create();
      probeDoc.registerFontkit(fontkit);
      await probeDoc.embedFont(fs.readFileSync(fontPath), { subset: true });
      const fontBytes = fs.readFileSync(fontPath);
      cjkFontEmbedCallCount += 1;
      const embeddedCjkFont = await pdfDoc.embedFont(fontBytes, { subset: true });
      cachedCjkFont = embeddedCjkFont;
      cachedCjkFontDoc = pdfDoc;
      cachedCjkFontMeta = { font: embeddedCjkFont, fontPath, subset: true, embedFontCalls: cjkFontEmbedCallCount };
      debugPdfLog("[pdf-export] using cjk font:", fontPath, "subset=true", "embedFontCalls=", cjkFontEmbedCallCount);
      return cachedCjkFontMeta;
    } catch (error) {
      debugPdfWarn("[pdf-export] skipped cjk font subset:", fontPath, error && error.message ? error.message : error);
    }
  }

  for (const fontPath of candidates) {
    try {
      const probeDoc = await PDFDocument.create();
      probeDoc.registerFontkit(fontkit);
      await probeDoc.embedFont(fs.readFileSync(fontPath), { subset: false });
      const fontBytes = fs.readFileSync(fontPath);
      cjkFontEmbedCallCount += 1;
      const embeddedCjkFont = await pdfDoc.embedFont(fontBytes, { subset: false });
      cachedCjkFont = embeddedCjkFont;
      cachedCjkFontDoc = pdfDoc;
      cachedCjkFontMeta = { font: embeddedCjkFont, fontPath, subset: false, embedFontCalls: cjkFontEmbedCallCount };
      debugPdfLog("[pdf-export] using cjk font:", fontPath, "subset=false", "embedFontCalls=", cjkFontEmbedCallCount);
      return cachedCjkFontMeta;
    } catch (error) {
      debugPdfWarn("[pdf-export] skipped cjk font full:", fontPath, error && error.message ? error.message : error);
    }
  }

  throw new Error("未找到中文字体，无法正确导出中文 PDF。");
}

function cleanPdfText(text) {
  return String(text || "").replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
}

function sanitizeTextForPdf(text, targetLanguage = "") {
  let value = cleanPdfText(text).normalize("NFC");
  value = value
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f]/g, "")
    .replace(/[\ufffe\uffff\ufffd]/g, "")
    .replace(/[\ud800-\udfff]/g, "");
  if (isEnglishTargetLanguage(targetLanguage)) {
    value = value
      .replace(/\u2212|\u2013|\u2014/g, "-")
      .replace(/\u223c/g, "~")
      .replace(/\u00d7/g, "x")
      .replace(/\u2248/g, "approx")
      .replace(/\u00b1/g, "+/-")
      .replace(/\u03bb/g, "lambda")
      .replace(/\u0393/g, "Gamma")
      .replace(/M\u2299/g, "M_sun");
  }
  return value;
}

