    schemaVersion: PDF_IMAGE_GEOMETRY_SCHEMA_VERSION,
    coordinateSpace: "pdf-page-top-left-points",
    source: "pdfjs-operator-list",
    pageNumber: Number(pageNumber || 0),
    pageWidth: Number(Number(viewport && viewport.width || 0).toFixed(2)),
    pageHeight: Number(Number(viewport && viewport.height || 0).toFixed(2)),
    pageGeometryHash,
