function getPdfSegmentWriteKind(segment, lineMasks) {
  return paperLayoutAuthority.resolveWriteKind(segment, lineMasks, cleanPdfText);
}

function getPdfWriteStyle(kind, averageFontSize, strategy) {
  return paperLayoutAuthority.resolveWriteStyle(kind, averageFontSize, strategy);
}

function pdfFontSupportsCharacter(font, char) {
  if (!font || !char) return false;
  try {
    const characterSet = font.getCharacterSet();
    return Array.isArray(characterSet) && characterSet.includes(char.codePointAt(0));
  } catch (_error) {
    return true;
  }
}

function makePdfFontRuns(line, primaryFont, fallbackFont) {
  const runs = [];
  Array.from(String(line || "")).forEach((char) => {
    const font = pdfFontSupportsCharacter(primaryFont, char)
      ? primaryFont
      : (pdfFontSupportsCharacter(fallbackFont, char) ? fallbackFont : primaryFont);
    const previous = runs[runs.length - 1];
    if (previous && previous.font === font) previous.text += char;
    else runs.push({ font, text: char });
  });
  return runs;
}

function drawFittedPdfText(page, fitted, font, box, pad, align, fallbackFont = null) {
  let cursorY = box.y + box.height - pad - fitted.size;
  fitted.paragraphs.forEach((paragraph, paragraphIndex) => {
    paragraph.forEach((line) => {
      if (cursorY < box.y + pad - fitted.size) return;
      const fontRuns = makePdfFontRuns(line, font, fallbackFont);
      const lineWidth = fontRuns.reduce((sum, run) => sum + run.font.widthOfTextAtSize(run.text, fitted.size), 0);
      const drawX = align === "center"
        ? box.x + pad + Math.max(0, (box.width - pad * 2 - lineWidth) / 2)
        : box.x + pad;
      let runX = drawX;
      fontRuns.forEach((run) => {
        page.drawText(run.text, {
          x: runX,
          y: cursorY,
          size: fitted.size,
          font: run.font,
          color: rgb(0, 0, 0),
        });
        runX += run.font.widthOfTextAtSize(run.text, fitted.size);
      });
      cursorY -= fitted.lineHeight;
    });
    if (paragraphIndex < fitted.paragraphs.length - 1) {
      cursorY -= fitted.paragraphSpacing;
    }
  });
}

function normalizeReportPageLayouts(segmentReports, pipelineDebug) {
  const byPage = new Map();
  segmentReports.forEach((report) => {
    const pageNumber = Number(report.pageNumber || 0);
    if (!pageNumber) return;
    if (!byPage.has(pageNumber)) byPage.set(pageNumber, []);
    byPage.get(pageNumber).push(report);
  });
  const pageLayouts = [];
  (pipelineDebug && Array.isArray(pipelineDebug.pages) ? pipelineDebug.pages : []).forEach((page) => {
    const pageNumber = Number(page.pageNumber || 0);
    if (pageNumber && !byPage.has(pageNumber)) byPage.set(pageNumber, []);
  });
  byPage.forEach((reports, pageNumber) => {
    const columns = new Set(reports.map((report) => String(report.column || "single")));
    const rawLayouts = new Set(reports.map((report) => String(report.layoutType || "")).filter(Boolean));
    const pipelinePage = pipelineDebug && Array.isArray(pipelineDebug.pages)
      ? pipelineDebug.pages.find((page) => Number(page.pageNumber || 0) === Number(pageNumber))
      : null;
    if (!reports.length && pipelinePage && Array.isArray(pipelinePage.columns)) {
      pipelinePage.columns.forEach((column) => columns.add(String(column || "single")));
    }
    let layoutType = rawLayouts.has("mixed")
      ? "mixed"
      : (rawLayouts.has("double_column") ? "double_column" : (rawLayouts.values().next().value || pipelinePage && pipelinePage.layoutType || "single_column"));
    if (columns.has("left") && columns.has("right")) {
      layoutType = columns.has("single") || rawLayouts.has("mixed") ? "mixed" : "double_column";
    }
    reports.forEach((report) => {
      report.layoutType = layoutType;
    });
    pageLayouts.push({
      pageNumber,
      layoutType,
      segmentCount: reports.length,
      columns: [...columns].length ? [...columns] : ["single"],
    });
  });
  return pageLayouts.sort((a, b) => a.pageNumber - b.pageNumber);
}

function getPdfPreserveReasonLabelForReport(report) {
  const type = String(report && report.type || "unknown");
  const skipReason = String(report && report.skipReason || "");
  if (skipReason === "formula_equation_block_preserve" || type === "formula") return "公式块";
  if (type === "reference") return "参考文献";
  if (type === "author") return "作者";
  if (type === "footer") return "页脚";
  if (type === "header") return "页眉";
  if (type === "pageNumber") return "页码";
  if (type === "licenseText") return "版权/许可";
  if (type === "imageText" || type === "imageRegion") return "图片文字";
  if (type === "margin") return "页边内容";
  if (type === "noise") return "噪声";
  if (type === "watermark") return "水印";
  return "其他";
}
