      computedZhCaptionFontSize: 0,
      computedZhHeadingFontSize: 0,
      computedZhTitleFontSize: 0,
      computedZhMetadataFontSize: 0,
      naturalTextHeight: 0,
      sourceBoxHeight: 0,
      naturalHeightRatio: 0,
      forcedHeightMatchApplied: false,
      expandedLineSpacingToMatchSourceHeight: false,
      sourceHeightStretchApplied: false,
      visualParagraphGroupId: "",
      visualParagraphGroupIndex: 0,
      visualParagraphGroupSize: 0,
      groupSplitReason: "",
      visualParagraphGroupWriteApplied: false,
      visualParagraphGroupNaturalHeight: 0,
      visualParagraphGroupSourceHeight: 0,
      visualParagraphGroupHeightRatio: 0,
      isFormulaLike: pureFormulaSegment || preservedFormulaLines.length > 0,
      formulaPreserveMode: "none",
      formulaLinePreserveCount: preservedFormulaLines.length,
      formulaSpanPreserveCount: 0,
      formulaWholeSegmentPreserve: false,
      formulaWholeSegmentReason: "",
      preservedFormulaLines,
      translatedProseLines,
      mixedFormulaProse,
      formulaLineDemotedToInline,
      protectedFormulaTokens: [],
      formulaTokenRestoreApplied: false,
