    let groupSplitForLayoutMemberCount = 0;
    let continuationRejectedByLayoutCount = 0;
    let bodyWrittenIntoReferenceZoneCount = 0;
    let bodyWrittenIntoImageRegionCount = 0;
    let bodyWrittenIntoFormulaRegionCount = 0;
    let realCollisionCount = 0;
    let nearCollisionCount = 0;
    let bboxArtifactCollisionCount = 0;
